       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"124043f2-6d2b-5115-abc8-8289d9cc87a2","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد م س روق -س رقة ذهب ومبالغ مالية من منزل -بينة غير موص لة -رد دع وى -للمدعي مين املدعى عليهما متى","document_number":"34185130","case_number":"34122821","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/10","year":"1434","subject":"مطالبة برد م س روق -س رقة ذهب ومبالغ مالية من منزل -بينة غير موص لة -رد دع وى -للمدعي مين املدعى عليهما متى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/10 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34185130 :‬‬\n                   ‫َر ْق ُم الدعوى‪34122821 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34239334‬تاريخه‪1434/6/13:‬هـ‬\n\n\n‫مطالبــة بــرد م ـسـ ــروق ‪ -‬سـ ــرقة ذهــب ومبالــغ ماليــة مــن منــزل ‪ -‬بينــة‬\n‫غيــر موصـ ــلة ‪ -‬رد دعـ ــوى ‪ -‬للمدعــي ميــن املدعــى عليهمــا متــى‬\n                                                              ‫طلبهــا ‪.‬‬\n\n\n\n‫مــا ذكــره القاضــي مــن املبــادئ العامــة وقواعــد العدالــة يف تســبيب‬\n                                                                 ‫حكمــه ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بــأن املدعــى عليهمــا اشــتركا يف ســرقة ذهــب ومبالــغ‬\n‫ماليــة مــن منزلــه ؛ وطلــب إلزامهمــا بإعــادة قيمــة املســروقات ‪ -‬أنكــر‬\n‫املدعــى عليهمــا دعــوى املدعــي جتاههمــا جملــة وتفصيــا ‪ -‬املدعــي قــدم‬\n‫بينــات غيــر موصلــة ولــم يقبــل ميــن املدعــى عليهمــا علــى نفــي دعــواه‪-‬‬\n‫مــن املقــرر شــرعا أن البينــة علــى املدعــي واليمــن علــى املدعــى عليــه‬\n‫‪ -‬قضــت احملكمــة بصــرف النظــر عــن دعــوى املدعــي وأفهمتــه أن لــه‬\n‫ميــن املدعــى عليهمــا متــى أراد ‪ -‬قنــع املدعــى عليهمــا باحلكــم وعــارض‬\n‫عليــه املدعــي‪ -‬قــررت محكمــة االســتئناف باألكثريــة املوافقــة علــى‬\n                                                                      ‫احلكــم ‪.‬‬\n\n\n\n                                                                                    ‫‪248‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة العامــة‬\n      ‫باملدينــة املنــورة وبنــاء علــى املعاملــة الــواردة مــن مركــز شــرطة قبــاء‬\n      ‫برقــم ‪ 192/13/6‬وتاريــخ‪1434/3/15 :‬ه ـ واحملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة باملدينــة املنــورة برقــم ‪ 34122821‬وتاريــخ‬\n      ‫‪1434/03/15‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34648118‬وتاريــخ‬\n      ‫‪1434/03/15‬ه ـ ففــي ي ــوم االثنــن افتتحــت اجللســة وفيهــا حضــر ‪....‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وحضــر حلضــوره املدعــى‬\n      ‫عليهــم ‪ ....‬باكســتاني اجلنســية مبوجــب اإلقامــة رقــم ‪ ....‬بنجالديشــي‬\n      ‫اجلنســية مبوجــب اإلقامــة رقــم و‪ ........‬باكســتاني اجلنســية مبوجــب‬\n      ‫اإلقامــة رقــم ‪ 2257460176‬ورفعــت اجللســة لطلــب مترجــم للمدعــى‬\n      ‫عليهــم ويف جلســة أخــرى حضــر الطرفــان املــدون هويتهمــا ســابق ًا‬\n      ‫ا إن املدعــى عليهــم احلاضــرون هــذا املجلــس قــد‬     ‫فادعــى األول قائ ـ ً‬\n      ‫قامــوا بســرقة محتويــات شــقتي بنيــة متلكهــا وقــد اتفــق األول والثانــي‬\n      ‫علــى االســتيالء علــى محتويــات شــقتي وتوجــد مظاهــر خارجيــة ظاهــر‬\n      ‫احلالــة تــدل علــى قيامهــم بســرقة احملتويــات وحيــث قامــا باعتــداء علــى‬\n      ‫ا غيــر مشــروع وهــي كالتالــي ( ‪ /1‬عقــد ذهــب‬    ‫حيــازة ممتلكاتــي نقـ ً‬\n      ‫مطعــم باللؤلــؤ ‪ /2‬اســورة ذهــب جنيهــات عيــار واحــد وعشــرين ‪ /3‬خــامت‬ ‫ّ‬\n      ‫ذهــب ابيــض ‪ /4‬طقــم مكــون مــن حلــق واســورة لؤلــؤ ‪ /5‬عــدد خمــس‬\n      ‫خــوامت لؤلــؤ ‪ /6‬عــدد أربعــون خــامت ذهــب ‪ /7‬طقــم املــاس مكــون مــن‬\n      ‫اســورة وحلــق ‪ /8‬عــدد اثنــان خــامت ‪ /9‬طقــم ذهــب فصــوص بنــي كامــل‬\n      ‫مكــون مــن حلــق واســورة وخــامت ‪ /10‬طقــم ذهــب فصــوص بنــي كامــل‬\n\n‫‪249‬‬\n\f‫مكــون مــن عقــد وحلــق وخــامت ‪ /11‬شــرش ذهــب ‪ /12‬كــف ذهــب‬\n‫وخــوامت عددهــا خمســة ‪ /13‬طقــم فيــروز أزرق مــع حلــق وتعليقــة ‪/14‬‬\n‫طقــم زوقــوم احمــر تعليقــة وخــامت وحلــق ‪ /15‬طقــم ذهــب فصــوص‬\n‫اخضــر حلــق وخــامت واســورة ‪ /16‬طقــم ذهــب اصفــر مــع اســورة تعليقــة‬\n‫وخــامت وحلــق ‪ /17‬مصحــف ذهــب مــع سلســلة ‪ /18‬عــدد عشــرة مــن‬\n‫السالســل الذهبيــة ‪ /19‬تعليقــة مــن الذهــب علــى شــكل ريــال ‪/20‬‬\n‫عــدد ثمانيــة عشــر بناجــر ‪ /21‬عــدد ثمانيــة عشــر مــن األســاور املختلطــة‬\n‫‪ /22‬عــدد عشــر حلــق مختلــف األشــكال واألنــواع ‪ /23‬طقــم علــى‬\n‫شــكل مقــاة مكــون مــن حلــق واســورة وخــامت وعقــد ‪ /24‬ذهــب‬\n‫ابيــض طقمــن ‪ /25‬اســورة مــع عــدد اثنــن خــوامت ذهــب ابيــض ‪/26‬‬\n‫ســاعة يــد ذهــب ‪ /27‬ســاعة لؤلــؤ وســاعة أميجــا ذهــب عيــار ســبع‬\n‫وعشــرين اصفــر ‪ /28‬مبالــغ ماليــة وقــدره خمســة وســتون ألــف ريــال‬\n‫‪ /29‬كيــس مــن النقــود لعمــات ورقيــة غيــر معلومــة املقــدار ) حيــث‬\n‫اتفقــا ســوي ًا علــى االســتيالء علــى ممتلكاتــي دون وجــه حــق أطلــب‬\n‫إلزامهــم بإعــادة املســروقات ومجموعهــا مائتــن وخمســون ألــف ريــال‬\n‫هــذه دعــواي وبســؤال املدعــي عــن املتهــم الثالــث بنجالديشــي اجلنســية‬\n‫باإلقامــة رقــم فقــال هــذا ال أتهمــه بشــيء ودعــواي علــى ‪...../2 ..../1‬‬\n‫‪/3‬وبســؤال املدعــى عليهــم عــن دعــوى املدعــي أجــاب كل واحــد منهمــا‬\n‫بلغــة عربيــة مفهومــة مــا ذكــره املدعــي غيــر صحيــح فلــم أقــم بالســرقة‬\n‫علم ـ ًا أننــي لــم أدخــل بيتــه إال مــرة عندمــا كان معنــا هــذه إجابتــي ثــم‬\n‫جــرى ســؤال املدعــي هــل لديــك بينــة فقــال نعــم ويف هــذه اجللســة حضــر‬\n‫‪ /‬مصــري اجلنســية مبوجــب اإلقامــة رقــم وعمــره ســتة وخمســون عامــا‬\n‫ا أشــهد هلل‬  ‫وعملــه دكتــور وليــس لــه عالقــة بالطرفــن فشــهد قائ ـ ً‬\n\n\n                                                                                      ‫‪250‬‬\n\f      ‫ا املوافــق ‪1433/1/18‬هـ‬       ‫تعالــى أننــي شــاهدت الســاعة الثانيــة عشــر ليـ ً‬\n      ‫وهــو خــارج مــن بــاب العمــارة وقــال لــي ال تقفــل البــاب هــذا مــا لــدي مــن‬\n      ‫شــهادة وبعــرض الشــاهد وشــهادته علــى املدعــى عليــه قــال مــا ذكــره‬\n      ‫الشــاهد غيــر صحيــح وأمــا الشــاهد فــا أعلــم عنــه شــيئا ويف جلســة‬\n      ‫أخــرى حضــر املدعــي هويتــه ســابق ًا وحضــر حلضــوره املدعــى عليهمــا‬\n      ‫املــدون هويتهمــا ســابق ًا وأحضــر املدعــي ‪ /‬مصــري اجلنســية مبوجــب‬\n      ‫اإلقامــة رقــم وعملــه محاســب وعمــره ســبع وأربعــون عام ـ ًا وعالقتــه‬\n      ‫ا أشــهد هلل تعالــى أن‬   ‫بالطرفــن أجنبــي عــن املتداعيــن فشــهد قائ ـ ً‬\n      ‫املدعــى عليــه عمــل يف دورة امليــاه اخلــاص بشــقتي يــوم االثنــن الســاعة‬\n      ‫الثانيــة إال ربــع حتــى الســاعة الثانيــة والنصــف وبعدهــا غــادر املــكان‬\n      ‫ولــم يرجــع إال يــوم اخلميــس هــذا مــا لــدي مــن شــهادة فجــرى عــرض‬\n      ‫الشــاهد وشــهادته عليــه بواســطة مترجــم احملكمــة ‪ .....‬باكســتاني‬\n      ‫اجلنســية مبوجــب اإلقامــة رقــم علــى املدعــى عليــه أجــاب بقولــه مــا‬\n      ‫ذكــره الشــاهد صحيــح ولكنــي تركــت العمــل ألجــل أن يحضــر‬\n      ‫معلــم الســيراميك ليصلــح الســيراميك ثــم أقــوم بتركيــب الســباكة‬\n      ‫هــذا مــا لــدي وأمــا شــهادته فــا تــدل علــى شــيء ممــا ذكــر وجــرى‬\n      ‫تزكيــة الشــاهدين مــن قبــل مصــري اجلنســية مبوجــب اإلقامــة رقــم‬\n      ‫مصــري اجلنســية مبوجــب اإلقامــة رقــم فجــرى ســؤال املدعــي هــل لديــك‬\n      ‫مزيــد بينــة فقــال ليــس لــدي ســوى مــا قدمــت هــذا مــا لــدي فجــرى إفهــام‬\n      ‫املدعــي أن لــه ميــن املدعــى عليهمــا فقــال أرفــض ميــن املدعــى عليهمــا وال‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومــا قــرره الطرفــان‬ ‫أريدهــا فبنـ ً‬\n      ‫وألنــكار املدعــى عليهمــا مــا جــاء يف دعــوى املدعــي ولعــدم البينــة‬\n      ‫املوصلــة مــن املدعــي ولرفضــه ميــن املدعــى عليهمــا وألن اليمــن حــق‬\n\n\n‫‪251‬‬\n\f‫للمدعــي لذلــك كلــه فقــد حكمــت بصــرف النظــر عــن دعــوى املدعــي‬\n‫وأخليــت ســبيل املدعــى عليهمــا وأفهمــت املدعــي أن لــه ميــن املدعــى‬\n‫عليهمــا متــى مــا أراد وبعــرض احلكــم علــى املدعــي واملدعــى عليهما قرر‬\n‫املدعــي عــدم القناعــة باحلكــم وقــرر املدعــى عليهمــا قناعتهمــا باحلكــم‬\n‫فجــرى إفهــام املدعــي باحلضــور غــد ًا الســتالم نســخة مــن احلكــم لتقــدمي‬\n‫اعتراضــه عليــه خــال ثالثــن يومـ ًا مــن تاريــخ االســتالم وإذا لــم يتقــدم‬\n‫خاللهــا فإنــه يســقط حقــه يف االســتئناف ويكتســب احلكــم القطعيــة‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n                                                     ‫حــرر يف ‪1434/04/09‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد والصــاة والســام علــى مــن ال نبــي بعــده ففــي‬\n‫هــذا اليــوم االثنــن املوافــق ‪1434/7/10‬ه ـ افتتحــت اجللســة وقــد‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف بخطابهــم رقــم ‪34648118‬‬\n‫وتاريــخ ‪1434/06/26‬ه ـ مرفقــا بــه القــرار رقــم ‪ 34239334‬وتاريــخ‬\n‫‪1434/06/13‬هـ الصادر من قضاة الدائرة اجلزائية السابعة مبحكمة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة املتضمــن املوافقــة علــى احلكــم‬\n‫باألكثريــة لــذا جــرى إحلــاق ذلــك وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/07/10‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                    ‫‪252‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":248,"source_page_end":252,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7c910d6463779316e1594176b368702b195be6c1cd9bc1313d81052c61dae427","normalized_text_hash":"00989326f16ca158aa40ce937192ab65964f2c9aa6e9e5acd93bdf9d8964c999","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p248-34185130"},{"id":"36c01daf-32a6-5e33-a4d9-e41ec8cb50be","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة مبلغ مالي عن طريق احتيال مصريف -على اليد ما أخذت حتى تؤديه -اإلقرار باستالم املبالغ -احلكم بإلزام املدعى عليه بدفع املبلغ املدعى به -إفهام بالرجوع على من غره .","document_number":"34227500","case_number":"34148388","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بحائل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/29","year":"1434","subject":"رد مسروق -سرقة مبلغ مالي عن طريق احتيال مصريف -على اليد ما أخذت حتى تؤديه -اإلقرار باستالم املبالغ -احلكم بإلزام املدعى عليه بدفع املبلغ املدعى به -إفهام بالرجوع على من غره .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/5/29 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34227500 :‬‬\n                         ‫َر ْق ُم الدعوى‪34148388 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34280282‬تاريخه‪1434/7/26:‬هـ‬\n\n\n      ‫رد مســروق ‪ -‬ســرقة مبلــغ مالــي عــن طريــق احتيــال مصــريف‪ -‬علــى‬\n      ‫اليــد مــا أخــذت حتــى تؤديــه ‪ -‬اإلقــرار باســتالم املبالــغ ‪ -‬احلكــم بإلــزام‬\n      ‫املدعــى عليــه بدفــع املبلــغ املدعــى بــه ‪ -‬إفهــام بالرجــوع علــى مــن غــره ‪.‬‬\n\n\n\n\n         ‫قول النبي صلى اهلل عليه وسلم‪(:‬على اليد ما أخذت حتى تؤديه) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بأنــه مت التحايــل عليــه وذلــك باتصــال شــخص يدعــي أنــه‬\n      ‫موظــف يف املصــرف الــذي بــه حســابه املصــريف وطلــب منــه معلومــات‬\n      ‫عــن حســابه ثــم أجريــت ســحوبات وحتويــات ماليــة مــن حســابه إلــى‬\n      ‫عــدة حســابات؛ وقــد تبــن مــن خــال التحقيقــات أن أحــد التحويــات‬\n      ‫كان لصالــح املدعــى عليــه ‪ ،‬ولــذا فقــد طلــب إلزامــه بإعــادة املبلــغ ‪-‬‬\n      ‫أقــر املدعــى عليــه باســتالم املبلــغ املذكــور يف الدعــوى نقــدا بعــد أن‬\n      ‫مت حتويلــه إلــى حســاب أحــد معارفــه‪ ،‬ودفــع بــأن شــخصا آخــر طلــب‬\n      ‫منــه رقــم حســاب ليحــول عليــه مبلغــا يخصــه ‪ ،‬وأنــه قــام بتســليم املبلــغ‬\n      ‫لشــخص مــن طــرف الشــخص املذكــور نقــدا بعــد اســتالمه لــه مــن‬\n      ‫املصــرف‪ ،‬ولــم يكــن يعلــم بتحايلــه علــى املدعــي لســرقة مبلــغ مالــي‬\n\n‫‪253‬‬\n\f‫مــن حســابه ‪ -‬املدعــى عليــه أقــر باســتالم املبلــغ املذكــور يف الدعــوى‬\n‫نقــدا ‪ -‬قضــت احملكمــة بإلــزام املدعــى عليــه بدفــع املبلــغ املدعــى بــه‬\n‫للمدعــي وأفهمتــه بــأن لــه الرجــوع علــى مــن غــره ‪ -‬قنــع املدعــي باحلكــم‬\n‫وعــارض عليــه املدعــى عليــه ‪ -‬قــررت محكمــة االســتئناف املصادقــة‬\n                                                                   ‫علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة العامــة‬\n‫بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بحائــل املســاعد برقــم ‪ 34148388‬وتاريــخ ‪ 1434/04/01‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 34719066‬وتاريــخ ‪ 1434/03/22‬ه ـ ففــي‬\n‫يــوم األربعــاء املوافــق‪ 1434/05/29‬ه ـ فتحــت اجللســة الســاعة ‪10 : 00‬‬\n‫وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وادعــى‬\n‫علــى احلاضــر معــه مينــي اجلنســية مبوجــب اإلقامــة الصــادرة مــن جــدة‬\n‫برقــم قائــا يف دعــواه عليــه أنــه قبــل ســنة تقريب ـ ًا اتصــل علــي شــخص‬\n‫يدعــي أنــه موظــف يف بنــك ‪ ...‬وذكــر أن اســمه‪ ...‬موظف يف قســم التميز‬\n‫بالبنــك وقــال لــي إن حســابي موقــف ويحتــاج الــى تنشــيط وطلــب منــي‬\n‫بعــض املعلومــات مــن أجــل تنشــيط احلســاب فأعطيتــه بعــض املعلومــات‬\n‫وبعــد ثالثــة أيــام مــن مكاملتــه حصلــت ســحوبات مــن حســابي علــى عــدة‬\n‫مــرات ولــم اكتشــف ذلــك إال بعــد مضــي مــدة عندمــا أردت أن اســحب‬\n‫عــن طريــق الصرافــة فدخلــت البطاقــة فيهــا ولــم تخــرج فراجعــت‬\n‫املصــرف يف حينــه فاتضــح أنــه مت ســحب مبالــغ مــن حســابي مجموعهــا‬\n‫مائتــان وخمســون ألــف ريــال ثــم طلبــت كشــف حســاب فظهــر فيــه‬\n\n                                                                                     ‫‪254‬‬\n\f      ‫االختــاس عبــارة عــن حتويــات ماليــة بأســماء أشــخاص آخريــن ال‬\n      ‫أعرفهــم فتقدمــت إلــى اجلهــات األمنيــة وبعــد البحــث والتحقيــق فيــه‬\n      ‫اتضــح أن هــذه املبالــغ وزعــت علــى أربــع حســابات مــن ضمنهــا حســاب‬\n      ‫شــخص اســمه مينــي اجلنســية يســكن يف مدينــة جــدة حيــث دخــل يف‬\n      ‫حســابه مبلــغ ســتني ألــف ريــال وعنــد التحقيــق معــه احضــر شــخصني‬\n      ‫األول مينــي اجلنســية والثانــي هــذا احلاضــر ‪ ...‬واقــروا عنــد التحقيــق أن‬\n      ‫ليــس لــه دخــل بهــذا املبلــغ احملــول مــن حســابي إلــى حســابه وقــد صــدر‬\n      ‫علــى هــذا احلاضــر وكذلــك زميلــه ‪ ....‬حكــم يف احلــق العــام بالســجن‬\n      ‫ملــدة عشــرة أشــهر واجللــد أربعمائــة جلــدة مفرقــة علــى دفعــات مبوجــب‬\n      ‫القــرار الصــادر مــن احملكمــة اجلزائيــة بحائــل برقــم ‪ 33303242‬يف‬\n      ‫‪1433/06/17‬هـ ـ املصــدق مــن محكمــة االســتئناف بالقصيــم برقــم‬\n      ‫‪ 33478025‬يف ‪ 1433/12/26‬هـ ـ وقــد تنازلــت عــن املدعــو بعدمــا دفــع‬\n      ‫لــي مبلــغ ثالثــن ألــف ريــال التــي ســحبها مــن حســابي إلــى حســاب لــذا‬\n      ‫اطلــب ســؤال املدعــى عليــه والزامــه بتســديد املبلــغ املتبقي وقــدره ثالثون‬\n      ‫ألــف ريــال حــاال هــذه دعــواي وبســؤال املدعــى عليــه اجــاب قائــا مــا‬\n      ‫ذكــره املدعــي ال أعلــم عنــه شــيئا وحقيقــة األمــر أنــه قبــل ســنة وعشــرة‬\n      ‫أشــهر بالضبــط اتصــل بــي شــخص وقــال لــي أنــه ابــن خالتــي واســمه‬\n      ‫‪ .......‬وأنــا ال أعرفــه وقــال لــي أنــه قــال كان يشــتغل يف شــركة ‪......‬‬\n      ‫وأن اجلــوازات أمســكته ولــه حقــوق عنــد شــركة ‪ ......‬وطلــب منــي رقــم‬\n      ‫حســاب يحــول لــه مســتحقاته لــدى الشــركة وقــال لــي ســوف يتصــل‬\n      ‫عليــك مديــر العمــال شــخص مينــي اســمه ‪ ........‬تعطيــه رقــم احلســاب‬\n      ‫ويحــول ذلــك مســتحقاتي ثــم اتصــل علــي شــخص يدعــي أن اســمه‬\n      ‫وأنــه مديــر عمــال شــركة ‪ ......‬فأعطيتــه حســاب فقــام بتحويــل مبلــغ‬\n\n\n‫‪255‬‬\n\f‫ســتني الــف ريــال فلــم علمــت بــأن املبلــغ كبيــر اتصلــت علــى ولــد خالتــي‬\n‫فأخبرنــي أنهــا مســتحقات ثمانيــة أشــخاص وطلــب أن اقــوم بتحويلهــا‬\n‫إلــى اليمــن فقــام بســحب نصفهــا مبلــغ ثالثــن ألــف ريــال واعطانــي‬\n‫اياهــا ثــم ذهبــت إلــى احلــواالت بجــده فقالــوا لــي إن املبلــغ كثيــر وطلبــوا‬\n‫ورقــة مــن الكفيــل فاتصلــت علــى مديــر العمــل ‪ .......‬فقــال لــي خلهــا‬\n‫عنــدك أنــا أرســل شــخص اآلن اســمه ‪ .......‬يســتلمها منــك وخــذ منهــا‬\n‫مبلــغ خمســمائة ريــال اشــتر بهــا بطاقــة موبايلــي وارســلها إلــى ولــد خالــك‬\n‫وبعــد ســاعة ونصــف جــاء (‪ )......‬واســتلم مبلــع تســعة وعشــرين ألفــا‬\n‫وخمســمائة ريــال ثــم طلــب منــي أن اقــوم بتحويل املبلغ املتبقي يف حســاب‬\n‫وقــدره ثالثــون ألــف ريــال إلــى حســاب شــخص اســمه ســوري اجلنســية‬\n‫فقــام بتحويلهــا حســب طلبــي وبعــد ســبعة أشــهر قامــت اجلهــات األمنيــة‬\n‫بالقبــض علــى بســبب هــذه املبالــغ فقمــت بتبرئتــه مــن هــذه املشــكلة‬\n‫ألنــه ليــس لــه دخــل فيهــا واتضــح أن هــذه املبالــغ اختالســات مــن عصابــة‬\n‫فقمــت باالتصــال علــى فلــم يــرد علــى واتصلــت علــى اليمــن فأتضــح أننــي‬\n‫غــرر بــي مــن أشــخاص ال أعرفهــم واســتغلوني يف ذلــك فقمــت بتســليم‬\n‫نفســي إلــى اجلهــات الرســمية واخبرتهــم بكامــل القصــة وأنــه غــرر بــي‬\n‫مــن هــؤالء االشــخاص وأنــا لــم اســرق ولــم اشــارك يف هــذه االختالســات‬\n‫كمــا اتضــح أن الــذي دفــع مبلــغ ثالثــن ألــف ريــال للمدعــي وتنــازل عنــه‬\n‫املدعــي لــه صلــة بهــذه القضيــة ولــذا فليــس للمدعــي عنــدي أي شــيء‬\n‫هــذه اجابتــي ثــم جــرى عــرض الصلــح علــى الطرفــن فقــرر املدعــى عليــه‬\n‫قائــا ال مانــع لــدي مــن دفــع املبلــغ بشــرط ضمــان عــدم ترحيلــي مــن‬\n‫الســعودية ألنــه صــدر علــي أمــر ترحيــل فأفهمنــاه أن اجــراءات الترحيــل‬\n‫ليســت مــن اختصــاص احملكمــة فقــرر قائــا أننــي مســتعد بدفــع املبلــغ‬\n\n\n                                                                                        ‫‪256‬‬\n\f      ‫بشــرط عــدم الترحيــل وأمــا غيــر ذلــك فــا أوافــق عليهــا فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واالجابــة واالطــاع علــى املعاملــة ومــن ضمنهــا‬\n      ‫احلكــم يف احلــق العــام املصــدق مــن االســتئناف وحيــث أقــر املدعــى عليــه‬\n      ‫بــأن هــذه االختالســات عبــارة عــن حتويــات ماليــه متــت بالتنســيق معــه‬\n      ‫وأنــه هــو املســؤول عنهــا وأن صاحــب احلســاب احملــول باســمه وهــو ليــس‬\n      ‫لــه دخــل بهــذه القضيــة وأنــه هــو و قــد غــرر بــه مــن أشــخاص يدعــون أنهم‬\n      ‫اقــارب لــه واتضــح أنهــم ســراق وحيــث أقــر املدعــى عليــه بأنــه قــد اســتلم‬\n      ‫الثالثــن الــف ريــال احملولــة بحســاب ولقــول النبــي صلــى اهلل عليــه وســلم‬\n      ‫« علــى اليــد مــا أخــذت حتــى تؤديــه» وحيــث اقتصــر املدعــي يف دعــواه‬\n      ‫ضــد املدعــى عليــه( ‪ ).........‬حســب اقــراره املرفــق لذلــك كلــه فقــد ثبــت‬\n      ‫لــدي صحــة دعــوى املدعــي ضــد املدعــى عليــه وحكمــت بالــزام املدعــى‬\n      ‫عليــه بدفــع املبلــغ املدعــى بــه وقــدره ثالثــون ألــف ريــال حــاال وبذلــك‬\n      ‫حكمــت وافهمــت املدعــى عليــه بــأن لــه الرجــوع علــى مــن غــره وبعــرض‬\n      ‫احلكــم علــى الطرفــن قــرر املدعــي قناعتــه أمــا املدعــى عليــه فقــرر‬\n      ‫عــدم القناعــة وطلــب تقــدمي الئحــة اعتراضيــة فأجبتــه لطلبــه وســوف يتــم‬\n      ‫تســليمه نســخة مــن احلكــم بعــد التوقيــع وافهمتــه بــأن مــدة االعتــراض‬\n      ‫وقدرهــا ثالثــون يومــا ســوف تبــدأ مــن هــذا اليــوم ‪143/5/29‬هـ ـ واذا‬\n      ‫مضــت هــذه املــدة ولــم يتقــدم بالئحتــه فتســقط معارضتــه فهــم ذلــك‬\n      ‫وعليــه جــرى التوقيــع‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/29‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n      ‫األولــى لتدقيــق القضايــا احلقوقيــة مبحكمــة االســتئناف مبنطقــة حائــل‬\n      ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بحائــل برقــم‬\n\n\n‫‪257‬‬\n\f‫‪ 34719066‬وتاريــخ ‪1434/7/10‬ه ـ واملقيــدة لدينــا برقــم ‪34719066‬‬\n‫بتاريــخ ‪1434/7/15‬ه ـ املرفــق بهــا الصــك رقــم ‪ 34227500‬يف‬\n‫‪1434/05/29‬ه ـ الصــادر مــن فضيلــة القاضي‪......./‬اخلــاص بدعــوى‬\n‫‪ ........‬ضــد ‪ ........‬مينــي اجلنســية بشــأن مبلــغ مالــي علــى الصفــة املوضحــة‬\n‫يف الصــك وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫وأوراق املعاملــة ‪ :‬فقــد جــرت املصادقــة علــى مــا حكــم بــه فضيلتــه واهلل‬\n      ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪258‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":253,"source_page_end":258,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6ee1b179d6db14fa439e1e174c0fd341641905e1a1583bf42878cb451e6d9dfe","normalized_text_hash":"0409b1549227e04a9a47357e36407e801b7144eac355331ae890f1d3eee54738","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p253-34227500"},{"id":"0a51b273-bd26-58e4-83c1-a5e9b3c251df","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة مبلغ مالي من سيارة -عجز عن إقامة البينة -اليمن على نفي الدعوى حق للمدعي وله عدم قبولها -احلكم برد دعوى -استحقاق املدعي ليمن املدعى عليه على نفي الدعوى","document_number":"34234369","case_number":"34234420","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/7","year":"1434","subject":"رد مسروق -سرقة مبلغ مالي من سيارة -عجز عن إقامة البينة -اليمن على نفي الدعوى حق للمدعي وله عدم قبولها -احلكم برد دعوى -استحقاق املدعي ليمن املدعى عليه على نفي الدعوى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/6/7 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34234369 :‬‬\n                         ‫َر ْق ُم الدعوى‪34234420 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34259203‬تاريخه‪1434/7/4:‬هـ‬\n\n\n      ‫رد مســروق ‪ -‬ســرقة مبلــغ مالــي مــن ســيارة ‪ -‬عجــز عــن إقامــة البينــة‬\n      ‫‪ -‬اليمــن علــى نفــي الدعــوى حــق للمدعــي ولــه عــدم قبولهــا ‪ -‬احلكــم‬\n      ‫بــرد دعــوى ‪ -‬اســتحقاق املدعــي ليمــن املدعــى عليــه علــى نفــي الدعــوى‬\n                                                                   ‫متــى طلبهــا ‪.‬‬\n\n\n\n\n      ‫قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن علــى‬\n                                                                       ‫مــن أنكــر) ‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل املدعــي علــى احلاضــر معــه بأنــه قــام بســرقة مبلــغ مالــي‬\n      ‫مــن ســيارة موكلــه َّإبــان عملــه كســائق خــاص لديــه‪ ،‬وطلــب إلزامــه‬\n      ‫بإعــادة املبلــغ املســروق إلــى موكلــه ‪ -‬أنكــر املدعــى عليــه مــا جــاء يف‬\n      ‫دعــوى املدعــي جتاهــه ‪ -‬املدعــي لــم يقــدم بينــة تثبــت دعــواه ولــم يقبــل‬\n      ‫ميــن املدعــى عليــه علــى نفيهــا ‪ -‬قضــت احملكمــة بــرد دعــوى املدعــي‬\n      ‫وأخلــت ســبيل املدعــى عليــه منهــا وأفهمــت املدعــي أن لــه ميــن املدعــى‬\n      ‫عليــه علــى نفــي دعــواه متــى مــا طلــب ذلــك ‪ -‬قنــع املدعــى عليــه باحلكــم‬\n      ‫وعــارض عليــه املدعــي‪ -‬قــررت محكمــة االســتئناف املصادقــة علــى‬\n                                                                             ‫احلكــم ‪.‬‬\n‫‪259‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا د‪ .... .‬القاضــي يف احملكمــة العامــة‬\n‫بعنيــزة بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيس احملكمــة العامة‬\n‫بعنيــزة برقــم ‪ 34234420‬وتاريــخ ‪ 1434/05/21‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 341239421‬وتاريــخ ‪ 1434/05/21‬ه ـ ففــي يــوم االثنــن املوافــق‬\n‫‪ 1434/06/05‬هـ افتتحت اجللسة الساعة ‪ 10 : 30‬وفيها حضر سعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم وكيــا عــن بالوكالــة الصــادرة‬\n‫مــن كتابــة العــدل الثانيــة بحائــل برقــم ‪ 3463265‬يف‪1434/5/19‬ه ـ‬\n‫وحضــر حلضــوره املدعــى عليــه ‪ ...‬هنــدي اجلنســية ال يحمــل إثبــات هويــة‬\n‫واملعــرف بــه مــن قبــل وكيــل املدعــي ‪ ،‬وادعــى املدعــي وكالــة قائــا يف‬\n‫دعــواه عليــه ‪ :‬أن هــذا احلاضــر كان يعمــل ســائق خــاص لــدى موكلــي‬\n‫والــدي ويف شــهر ذي احلجــة مــن عــام ‪1433‬ه ـ قــام بفتــح بــاب ســيارة‬\n‫موكلــي والــدي اخلاصــة بــه مــن أمــام بيــت موكلــي الواقــع يف مدينــة ‪...‬‬\n‫يف حــي ‪ ...‬ولــم تكــن األبــواب مقفلــة وقتهــا وقــام بســرقة مبلــغ وقــدره‬\n‫ســبعة آالف وأربعمائــة ريـ‪ 7400‬ــال وأخــذ جــواز ســفره اخلــاص بــه ثــم‬\n‫هــرب أطلــب إلزامــه بإعــادة املبلــغ املســروق ملوكلــي وقــدره ســبعة آالف‬\n‫وأربعمائــة ريـ‪ 7400‬ــال هــذه دعــواي وبعــرض الدعــوى علــى املدعــى عليه‬\n‫أجــاب قائــا بــأن مــا ذكــره املدعــي وكالــة كلــه غيــر صحيــح فلــم‬\n‫اشــتغل لــدى موكلــه ســائق خــاص و الصحيــح أننــي عملــت لــدى املدعــي‬\n‫أصالــة بالغنــم بالصليبيــة وكنــت اتفقــت معــه يف الهنــد علــى العمــل‬\n‫لديــه يف بقالــة وكان يســيء معاملتــي ويضربنــي وال أعــرف بيتــه الــذي‬\n‫يف ‪ ...‬ولــم أقــم بفتــح بــاب الســيارة ولــم أســرق املبلــغ املذكــور ولــم آخــذ‬\n\n                                                                                        ‫‪260‬‬\n\f      ‫جــواز ســفري هكــذا أجــاب ‪ ،‬وبعــرض إجابتــه علــى املدعــي وكالــة‬\n      ‫قــال ‪ :‬الصحيــح مــا ذكــرت ولــدي بينــة ‪ ،‬وأطلــب إمهالــي إلحضارهــا ‪،‬‬\n      ‫ويف جلســة أخــرى حضــر املدعــي وكالــة وحضــر املدعــى عليــه أصالــة‬\n      ‫هنــدي اجلنســية مبوجــب رقــم احلــدود املذكــور يف خطاب مدير الشــرطة‬\n      ‫رقــم ‪31/3509/1116‬وبســؤال املدعــى وكالــة هــل أحضــر البينــة التــي‬\n      ‫وعــد بإحضارهــا يف اجللســة املاضيــة فقــال لــم أحضــر البينة وال أســتطيع‬\n      ‫إحضارهــا فقــد بحثــت ولــم أجــد فأفهمتــه بــأن لــه ميــن املدعــى عليــه‬\n      ‫فقــال ال أطلــب ميــن املدعــى عليــه وال أقبلهــا وبســؤال املدعــى عليــه هــل‬\n      ‫يحلــف علــى نفــي الدعــوى فقــال نعــم واســتعد ببذلهــا فبنــاء علــى مــا‬\n      ‫تقــدم مــن الدعــوى واإلجابــة وألن املدعــى عليــه أنكــر الســرقة واملدعــي‬\n      ‫لــم يثبتهــا ببينــة وقــرر بأنــه ال يســتطيع إحضارهــا وملــا ورد يف احلديــث‬\n      ‫مــن أن البينــة علــى املدعــي واليمــن علــى مــن أنكــر فقــد رددت دعــوى‬\n      ‫املدعــي وأخليــت ســبيل املدعــى عليــه وافهمــت املدعــي بــأن لــه ميــن‬\n      ‫املدعــي متــى طلبهــا وبــه حكمــت وبعــرض احلكــم علــى الطرفــن قــرر‬\n      ‫املدعــي عــدم القناعــة وطلــب رفعــه حملكمــة االســتئناف بــدون الئحــة‬\n      ‫اعتراضيــة واملدعــى عليــه القناعــة فأمــرت برفعــه حملكمــة االســتئناف‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                ‫وســلم ‪ .‬حــرر يف ‪1434/06/07‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ......‬القاضــي يف احملكمــة العامــة‬\n      ‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بعنيــزة برقــم ‪ 34234420‬وتاريــخ ‪1434/05/21‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 341239421‬وتاريــخ ‪1434/05/21‬ه ـ ففــي‬\n      ‫يــوم االثنــن املوافق‪1434/07/17‬ه ـ افتتحــت اجللســة وفيهــا وردتنــا‬\n\n\n‫‪261‬‬\n\f‫املعاملــة مــن محكمــة االســتئناف بالقصيــم برقــم ‪ 34149550‬وتاريــخ‬\n‫‪1434/7/10‬ه ـ واخلاصــة بدعــوى … ضــد ‪(.........‬هنــدي اجلنســية)‬\n‫وبرفقهــا القــرار رقــم ‪ 34259203‬وتاريــخ ‪1434/7/4‬ه ـ وباالطــاع‬\n‫عليــه وجــد يتضمــن وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة‬\n‫لــم يظهــر مــا يوجــب املالحظــة علــى مــا حكــم بــه فضيلتــه ‪ .‬وبــاهلل‬\n‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                        ‫يف ‪1434/07/17‬هــ‪.‬‬\n\n\n\n\n                                                                                  ‫‪262‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":259,"source_page_end":262,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f253df3ff59fd2bc939f57b34becbae368a4447adb0db53b8fbddc450db43ea6","normalized_text_hash":"236a66d571ab396ebc94a500eafbc80e1ebeabcfd05eb86779a333242df8c50b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p259-34234369"},{"id":"61d74784-e1a3-5871-8e1d-ecd116f48e8b","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد مسروق -عدم إقامة الدعوى من املدعي العام لعدم وجود دليل -سرقة ذهب ومبالغ مالية من منزل -بينة غير موصلة -اليمن على نفي الدعوى -رد الدعوى .","document_number":"34293396","case_number":"34248172","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/9","year":"1434","subject":"مطالبة برد مسروق -عدم إقامة الدعوى من املدعي العام لعدم وجود دليل -سرقة ذهب ومبالغ مالية من منزل -بينة غير موصلة -اليمن على نفي الدعوى -رد الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/8/9 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34293396 :‬‬\n                         ‫َر ْق ُم الدعوى‪34248172 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 35122832‬تاريخه‪1435/1/22:‬هـ‬\n\n\n      ‫مطالبــة بــرد مســروق‪ -‬عــدم إقامــة الدعــوى مــن املدعــي العــام لعــدم‬\n      ‫وجــود دليــل ‪ -‬ســرقة ذهــب ومبالــغ ماليــة مــن منــزل ‪ -‬بينــة غيــر‬\n                     ‫موصلــة ‪ -‬اليمــن علــى نفــي الدعــوى ‪ -‬رد الدعــوى ‪.‬‬\n\n\n\n\n      ‫‪( -1‬أن النبــي صلــى اهلل عليــه وســلم قضــى أن اليمــن علــى املدعــى‬\n                                                         ‫عليــه)‪ .‬رواه البخــاري ‪.‬‬\n      ‫‪ -2‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن‬\n                                          ‫علــى املدعــى عليــه)‪ .‬رواه الترمــذي ‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل املدعــي بــأن املدعــى عليــه املمثــل بوكيلــه احلاضــر قــام‬\n      ‫بتحريــض أشــخاص علــى ســرقة أطقــم ذهــب ومبلــغ مالــي مــن منــزل‬\n      ‫موكلــه ؛ وطلــب إلزامــه بإعــادة املســروقات إلــى موكلــه مــع تعويــض‬\n      ‫مــادي واحلكــم عليــه بعقوبــة تعزيريــة ‪ -‬أنكــر وكيــل املدعــى عليــه‬\n      ‫الدعــوى ودفــع بــأن موكلــه موظــف يف الشــركة التــي متلــك املنــزل‬\n      ‫وقــد طلبــت منــه الكتابــة عليــه مبــا يــدل علــى أنــه معــروض للبيــع وال‬\n      ‫رابــط بــن ذلــك ومــا جــاء يف الدعــوى‪ -‬قــدم املدعــي بينــات غيــر موصلــة‬\n      ‫واملدعــى عليــه أصالــة حلــف اليمــن علــى نفــي دعــواه طبــق مــا طلــب‬\n\n‫‪263‬‬\n\f‫منــه‪ -‬مــن املقــرر شــرعا أن البينــة علــى املدعــي واليمــن علــى املدعــى‬\n‫عليــه ‪ -‬لذلــك قضــت احملكمــة بــرد دعــوى املدعــي يف مواجهــة املدعــى‬\n‫عليــه لعــدم ثبــوت صحتهــا ‪ -‬قنــع املدعــى عليــه وعــارض املدعــي علــى‬\n        ‫احلكــم‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظة جدة وبناء على املعاملة احملالة لنا من فضيلة رئيس احملكمة‬\n‫العامــة مبحافظــة جــدة برقــم ‪ 34248172‬وتاريــخ ‪1434/05/28‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 341263432‬وتاريــخ ‪1434/05/25‬ه ـ ففــي‬\n‫يــوم الثالثــاء املوافق‪1434/07/25‬ه ـ افتتحــت اجللســة الســاعة ‪:00‬‬\n‫‪ 01‬وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬‬\n‫بصفتــه وكيــا عــن‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬‬\n‫بصفتــه وكيــل مبوجــب وكالــة رقــم ‪ 57281‬وتاريــخ ‪1433/6/29‬ه ـ‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة شــمال محافظــة جــدة واملــوكل بهــا‬\n‫مــن املدعــي ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ...‬مبوجــب‬\n‫الوكالــة رقــم ‪ 34558009‬وتاريــخ ‪1434/5/4‬هـ‪،‬وادعــى علــى احلاضــر‬\n‫معــه ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬بصفته وكيال‬\n‫عــن ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم بالوكالــة رقــم‬\n‫‪ 34920445‬وتاريــخ ‪1434/7/15‬ه ـ قائــا‪ :‬تتمثــل دعــواي يف قيــام‬\n‫املدعــى عليــه بتحريــض مجموعــة مــن األشــخاص يف غيابــي باالعتــداء‬\n‫علــى منــزل موكلــي واقتحامــه وســرقة ثالثــة أطقــم ذهــب ومبلــغ مالــي‬\n‫قيمتــه خمســة عشــر ألــف ريــال وقــام بكتابــة عبــارات عليــه تفيــد أنــه‬\n\n\n                                                                                 ‫‪264‬‬\n\f      ‫املالــك ويريــد بيعــه ونصهــا (للبيــع مــن املالــك مباشــرة لالستفســار ‪)....‬‬\n      ‫حيــث أن موكلــي كان يف إجــازة رســمية مــن العمــل تنتهــي بتاريــخ ‪19‬‬\n      ‫شعبان ‪1433‬هـ لعالج مشكلة خلع بالفك ‪ ،‬وعند عودته للمنزل وجد‬\n      ‫األبــواب مفتحــة وغرفــة النــوم مبعثــرة وعلــى الفــور توجــه إلــى مركــز‬\n      ‫شــرطة الســامر لتحريــر محضــر بذلــك وأثنــاء حتريــر احملضــر مبركــز‬\n      ‫شــرطة الســامر قــام النقيــب باالتصــال علــى رقــم اجلــوال املوضــح بعاليــه‬\n      ‫ورد عليــه املدعــى عليــه وقــد حتــدث النقيــب إلــى املدعــى عليــه باجلــوال‬\n      ‫يدعــي بأنــه مشــتر يريــد شــراء الفيــا ‪ ،‬فقــال لــه املدعــى عليــه نعــم أنــا‬\n      ‫املالــك ومســتعد إلنهــاء البيــع واإلفــراغ خــال يومــن ‪ ،‬وذكــر أنــه فعــل‬\n      ‫ذلــك بتوجيهــات شــركة ‪ ..........‬كــون موكلــي مســتأجر منهــا الفيــا‬\n      ‫بعقــد إيجــار مــع الوعــد بالتمليــك ولتأخــر موكلــي عــن دفــع القســط‬\n      ‫الشــهري للفيــا قــام املدعــى عليــه مبباشــرة االعتــداء ‪ ،‬مــع أن العقــد‬\n      ‫بــن موكلــي وبــن الشــركة ال يجيــز لهــا فســخ العقــد إال يف حالــة‬\n      ‫تأخــره عــن دفــع ثالثــة أقســاط متتاليــة ‪ ،‬ولــكل مــا تقــدم ألتمــس مــن‬\n      ‫فضيلتكــم أوال‪ -:‬احلكــم بإدخــال شــركة ‪ .......‬طرف ـ ًا يف الدعــوى‬\n      ‫الرتباطهــا باملوضــوع ارتباط ـ ًا ال يقبــل التجزئــة‪ .‬ثانيــا‪ :‬احلكــم بإلــزام‬\n      ‫املدعــى عليــه بــرد املســروقات مــن ذهــب ومبالــغ ماليــة ‪ .‬ثالثــا‪ -:‬احلكــم‬\n      ‫بتعزيــر املدعــى عليــه مبــا يجــب شــرع ًا نتيجــة العتدائــه علــى حرمــة‬\n      ‫املنــازل ‪ ،‬مــع احلكــم لــي بالتعويــض املــادي نتيجــة كل هــذه األفعــال‬\n      ‫احملرمــة شــرع ًا ‪ .‬هــذه دعــواي‪ ،‬وبعــرض ذلــك علــى املدعــى عليــه‬\n      ‫وكالــة قــدم مذكــرة هــذا نصهــا‪ -1 :‬إن االدعــاء الــذي ذكــره املدعــي‬\n      ‫عــن فعــل التحريــض واقتحــام املنــزل بقصــد الســرقة غيــر صحيــح جملــة‬\n      ‫ا ‪-2.‬موكلــي يعمــل موظــف يف الشــركة التــي متتلــك العقــار‬            ‫وتفصي ـ ً‬\n      ‫املســتأجر مــن املدعــي وقــد طلبــت الشــركة مــن موكلــي عــرض العقــار‬\n\n‫‪265‬‬\n\f‫للبيــع ‪ ،‬حيــث أنهــا متتلــك العقــار ويحــق لهــا التصــرف فيــه تصــرف املالك‬\n‫مبلكــه ‪ ،‬وعلــى إثــر ذلــك قــام موكلــي بتوجيــه فريــق العمــل امليدانــي‬\n‫اخلــاص بالشــركة بكتابــة عبــارة (العقــار للبيــع مــن املالــك مباشــرة‬\n‫‪ ،)....‬وال نــرى أن كتابــة هــذه العبــارة علــى الســور اخلارجــي للمنــزل‬\n‫بغــرض عرضــه للبيــع لهــا رابطــة ســببيه يف واقعــة الســرقة التــي يدعــي‬\n‫بهــا املدعــي‪ -3.‬ســبق وأن تقــدم وكيــل املدعــي ببــاغ لقســم شــرطة‬\n‫الســامر اتهــم فيهــا موكلــي بالســرقة ‪ ،‬حيــث مت اســتدعاء موكلــي‬\n‫وأخــذ أقوالــه أمــام الضابــط احملقــق ومت كذلــك أخــذ بصماتــه‪ ،‬ووفقـ ًا‬\n‫إلفــادة قســم الشــرطة مت إحالــة امللــف إلــى هيئــة التحقيــق واالدعــاء‬\n‫العــام‪ ،‬وأعيــد منهــا لعــدم وجــود أدلــة تثبــت عالقــة موكلــي بالســرقة‪،‬‬\n‫وطلبــت الهيئــة يف مثــل هــذه احلــاالت والتــي ال يوجــد فيهــا لــدى املدعــي‬\n‫أي بينــة ضــد املدعــى عليــه إحالــة امللــف للمحكمــة للنظــر فيهــا باحلــق‬\n‫اخلــاص‪ ،‬وقــد مت إحالــة امللــف للمحكمــة العامــة بالرقــم ‪41/2433‬‬\n‫وتاريــخ ‪1434/05/22‬ه ـ ‪-4.‬طلــب املدعــي إيقــاع العقوبــة ضــد موكلــي‬\n‫ال يقــوم علــى ســند صحيــح بالنظــام ‪ ،‬حيــث أن املدعــي نصــب نفســه‬\n‫ممثـ ًـا عــن االدعــاء العــام‪ .‬وممــا تقــدم فــإن موكلــي يطالــب احلكــم‬\n‫بصــرف النظــر عــن الدعــوى‪ .‬وبعــرض ذلــك علــى املدعــي وكالــة قــال‪:‬‬\n‫أطلــب اإلمهــال إلحضــار بينتــي علــى صحــة الدعــوى‪ .‬ثــم رفعــت اجللســة‬\n‫لذلــك ‪.‬ويف يــوم الثالثــاء املوافــق ‪1434/08/09‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 02 :30‬وفيهــا حضــر املدعــي وكالــة واملدعــى عليــه وكالــة‬\n‫‪ ،......‬كمــا حضــر املدعــي ‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ ، ....‬وحضــر املدعــى عليــه ‪ ...‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم‪ ...‬وبســؤال املدعــي وكالــة عمــا طلــب اإلمهــال مــن أجلــه‬\n‫أحضــر للشــهادة وأدائهــا ‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n\n                                                                                    ‫‪266‬‬\n\f      ‫رقــم ‪ .....‬وهــو مــن مواليــد ‪1392‬ه ـ ويعمــل يف حــرس احلــدود ‪ ،‬ويســكن‬\n      ‫يف حــي ‪ ....‬مبحافظــة جــدة ‪ ،‬وليــس بينــه وبــن طــريف الدعــوى قرابــة ‪،‬‬\n      ‫وشــهد قائــا‪ :‬أشــهد هلل تعالــى بأنــه قبــل حوالــي عــام وجــدت شــخصني‬\n      ‫يقومــان بطباعــة عبــارة علــى جــدار منزلــي فأوقفتهمــا ثــم اتضــح أنهمــا‬\n      ‫يريــدان منــزل املدعــي‪ ،‬ثــم انتقــا إلــى منــزل املدعــي وطبعــا عبــارة‬\n      ‫(للبيــع مــن املالــك مباشــرة لالستفســار) ‪ .‬هكــذا شــهد ‪ .‬وبعــرض ذلــك‬\n      ‫علــى املدعــى عليــه وكالــة قــال‪ :‬إن شــهادة الشــاهد غيــر موصلــة إلــى‬\n      ‫مــا يدعــي بــه املدعــي ‪ .‬وبعــرض ذلــك علــى املدعــي وكالــة قــال‪ :‬شــهادة‬\n      ‫الشــاهد تــدل علــى أن املدعــي هــو مــن وجــه الشــخصني بعمــل مــا قامــا‬\n      ‫بعملــه ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال‪ :‬شــهادة الشــاهد‬\n      ‫ال تــدل علــى ذلــك إطالقــا ‪ .‬وبســؤال املدعــي علــى دعــواه قــال‪ :‬ليــس‬\n      ‫لــدي بينــة ‪ ،‬وأطلــب ميــن املدعــى عليــه علــى إنــكار مــا ورد يف الدعــوى‬\n      ‫‪ ،‬وأقبــل ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه اســتعد لذلــك ‪ ،‬ثــم حلــف‬\n      ‫قائــا‪ :‬واهلل العظيــم الــذي ال إلــه إال هــو أن مــا ذكــره املدعــي مــن‬\n      ‫قيامــي بتحريــض مجموعــة مــن األشــخاص يف غيــاب املدعــي لالعتــداء‬\n      ‫علــى منزلــه واقتحامــه وســرقة ثالثــة أطقــم ذهــب ومبلــغ مالــي قيمتــه‬\n      ‫خمســة عشــر ألــف ريــال وقيامــي بكتابــة عبــارات عليــه تفيــد أننــي‬\n      ‫املالــك وأننــي أريــد بيعــه ونصهــا (للبيــع مــن املالــك مباشــرة لالستفســار)‬\n      ‫فغيــر صحيــح‪ ،‬وأمــا مــا يخــص االتصــال مــن قبــل النقيــب وأننــي أجبــت‬\n      ‫عليــه فــا أعلــم عــن صحتــه‪ ،‬حيــث أننــي أعمــل لــدى شــركة‪،.......‬‬\n      ‫وهــذا اإلجــراء متبــع لديهــا ‪ ،‬ويتصــل علــي أكثــر مــن شــخص ألكثــر‬\n      ‫مــن عقــار ‪ ،‬وال أســتطيع حتديــد االتصــال محــل الدعــوى هــل هــو مــن‬\n      ‫بينهــا أم ال ‪ .‬هكــذا حلــف ‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n      ‫‪ ،‬وبنــاء علــى إنــكار املدعــى عليــه لدعــوى املدعــي ‪ ،‬وبنــاء علــى أن‬\n\n‫‪267‬‬\n\f‫املدعــي لــم يقــم البينــة علــى صحــة مــا ادعــاه يف مواجهــة املدعــى عليــه ‪،‬‬\n‫وجملــة مــا يف األمــر قيــام أشــخاص مــن قبــل الشــركة بعمــل مــا ذكــره‬\n‫املدعــي علــى جــدار املنــزل محــل الدعــوى ‪ ،‬وبنــاء علــى طلــب املدعــي‬\n‫ميــن املدعــى عليــه علــى إنــكار دعــواه ‪ ،‬وبنــاء علــى ميــن املدعــى عليــه‬\n‫علــى إنــكار دعــوى املدعــي ‪ ،‬وبنــاء علــى أن تصــرف املوظــف ومــن يف‬\n‫حكمــه يقــع ضمــن مســؤوليات مــن اجلهــة التابعــة لــه ‪ ،‬مــا لــم يتعــدى أو‬\n‫يتجاوز الصالحيات السلطات املمنوحة له ‪ ،‬وحيث أن تلك التصرفات‬\n‫تتوجــه الدعــوى فيهــا ابتــداء علــى الشــركة التــي يتبعهــا ذلــك املوظــف ‪،‬‬\n‫وحلديــث (أن النبــي صلــى اهلل عليــه وســلم قضــى أن اليمــن علــى املدعــى‬\n‫عليــه) رواه البخــاري ‪ ،‬وحلديــث (البينــة علــى املدعــي واليمــن علــى‬\n‫املدعــى عليــه) رواه الترمــذي ‪ ،‬قــال العمــل عنــد أهــل العلــم مــن أصحــاب‬\n‫النبــي صلــى اهلل عليــه وســلم وغيرهــم أن البينــة علــى املدعــي واليمــن‬\n‫علــى املدعــى عليــه ‪ ،‬لذلــك كلــه ‪ ،‬فقــد حكمــت بــرد دعــوى املدعــي‬\n‫يف مواجهــة املدعــى عليــه لعــدم ثبــوت صحتهــا ‪ .‬وبــه قنــع املدعــى عليــه ‪،‬‬\n‫وقــرر املدعــي االعتــراض ‪ ،‬وجــرى تســليمه نســخة مــن احلكــم وإفهامــه‬\n‫بــأن لــه احلــق يف االعتــراض عليــه خــال ثالثــن يومــا ‪ ،‬وإال ســقط حقــه‬\n‫يف االعتــراض ‪ ،‬واكتســب احلكــم القطعيــة ‪ .‬وأقفلــت اجللســة الســاعة‬\n‫‪ . 03 :00‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                  ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/08/09‬ه ـ ‪.‬‬\n\n\n\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 35122832‬وتاريــخ‬\n                                                ‫‪1435/1/22‬هـ‪.‬‬\n\n\n\n                                                                                      ‫‪268‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":263,"source_page_end":268,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b4a95efa5139fd67a9b48f069323ca297f4bf810c8ab6e0b96e53ae700c2f474","normalized_text_hash":"4cd8847346576d0ba18ecaa2490ebe09f777418449b1551852ec5ba6b7de67e7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p263-34293396"},{"id":"e0e467d3-83a8-5b08-a7b3-112edfb1e9b3","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة مبلغ مالي عن طريق احتيال مصريف -دفع املدعى عليه انه ليس املستفيد الفعلي -ثبوت استالم املبلغ بإقرار املدعى عليه -احلكم بإلزام املدعى عليه بدفع املبلغ املدعى به - إفهام املدعى عليه بالرجوع على من غره .","document_number":"33443865","case_number":"150210726","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/1","year":"1434","subject":"رد مسروق -سرقة مبلغ مالي عن طريق احتيال مصريف -دفع املدعى عليه انه ليس املستفيد الفعلي -ثبوت استالم املبلغ بإقرار املدعى عليه -احلكم بإلزام املدعى عليه بدفع املبلغ املدعى به - إفهام املدعى عليه بالرجوع على من غره .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/11/1 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33443865 :‬‬\n                         ‫َر ْق ُم الدعوى‪150210726 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 349355‬تاريخه‪1434/1/12:‬هـ‬\n\n\n      ‫رد مســروق ‪ -‬ســرقة مبلــغ مالــي عــن طريــق احتيــال مصــريف ‪ -‬دفــع‬\n      ‫املدعــى عليــه انــه ليــس املســتفيد الفعلــي ‪ -‬ثبــوت اســتالم املبلــغ بإقــرار‬\n      ‫املدعــى عليــه ‪ -‬احلكــم بإلــزام املدعــى عليــه بدفــع املبلــغ املدعــى بــه ‪-‬‬\n                                     ‫إفهــام املدعــى عليــه بالرجــوع علــى مــن غــره ‪.‬‬\n\n\n\n\n      ‫‪( -1‬أن النبــي صلــى اهلل عليــه وســلم قضــى أن اليمــن علــى املدعــى‬\n                                                         ‫عليــه)‪ .‬رواه البخــاري ‪.‬‬\n      ‫‪ -2‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن‬\n                                          ‫علــى املدعــى عليــه) رواه الترمــذي ‪.‬‬\n      ‫‪ -3‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬علــى اليــد مــا أخــذت حتــى‬\n                                                           ‫تؤديــه) رواه األربعــة ‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل املصــرف املدعــي بــأن املدعــى عليــه قــام بالتحايــل علــى‬\n      ‫موكلــه وذلــك بتقــدمي تفويــض مــزور يخولــه إجــراء التحويــات املاليــة‬\n      ‫مــن حســاب أحــد العمــاء لديــه ‪ ،‬ثــم قــام بتحويــل مبلــغ مالــي من حســاب‬\n      ‫العميــل املذكــور إلــى حســابه وقــام بســحبه مــن املصــرف نقــدا‪ ،‬وبعــد‬\n      ‫ذلــك اعتــرض العميــل علــى ســحب املبلــغ املذكــور مــن حســابه فاســتعاد‬\n\n‫‪269‬‬\n\f‫املصــرف مــن حســاب املدعــى عليــه نصــف ذلــك املبلــغ لصالــح العميــل‬\n‫املذكــور؛ ولــذا فقــد طلــب إلزامــه بإعــادة النصــف اآلخــر مــن ذلــك‬\n‫املبلــغ ‪ -‬أقــر املدعــى عليــه باســتالم املبلــغ املذكــور يف الدعــوى نقــدا‬\n‫بعــد أن مت حتويلــه إلــى حســابه‪ ،‬ودفــع بــأن شــخصا آخــر طلــب منــه‬\n‫املوافقــة علــى حتويــل املبلــغ إلــى حســابه فوافــق علــى ذلــك‪ ،‬وأنــه قــام‬\n‫بتســليم املبلــغ للشــخص املذكــور نقــدا بعــد اســتالمه لــه مــن املصــرف‪،‬‬\n‫ولــم يكــن يعلــم بتحايلــه علــى املدعــي لســرقة مبلــغ مالــي مــن حســاب‬\n‫أحــد عمالئــه ‪ -‬املدعــى عليــه أقــر باســتالم املبلــغ املذكــور يف الدعــوى‬\n‫نقــدا ‪ -‬قضــت احملكمــة بإلــزام املدعــى عليــه بتســليم املدعــي أصالــة‬\n‫املبلــغ املدعــى بــه وأفهمتــه بــأن لــه الرجــوع علــى مــن غــره متــى مــا ثبــت‬\n‫ذلــك ‪ -‬قنــع املدعــي باحلكــم وعــارض عليــه املدعــى عليــه ‪ -‬قــررت‬\n                              ‫محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 150210726‬وتاريــخ‬\n‫‪1430/08/04‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3061885‬وتاريــخ‬\n‫‪1430/08/03‬ه ـ ففــي يــوم الســبت املوافق‪1433/05/08‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 08 :40‬وفيهــا حضــر ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم بصفتــه وكيــا عــن‪ ...‬ســعودي مبوجــب ســجل مدنــي رقــم‬\n‫بصفتــه رئيــس مجلــس إدارة البنــك ‪ .........‬وبوكالتــه عــن كل مــن ‪....‬‬\n‫ســجل مدنــي رقــم‪ ...‬و‪ ......‬ســجل مدنــي رقــم ‪ ....‬و‪ ....‬ســجل مدنــي رقــم ‪...‬‬\n\n                                                                                         ‫‪270‬‬\n\f      ‫و‪ ......‬ســجل مدنــي رقــم ‪ ....‬و‪ ......‬ســجل مدنــي رقــم ‪ ...‬و‪ ......‬ســجل مدنــي‬\n      ‫رقــم ‪ .......‬و‪ ...‬ســجل مدنــي رقــم‪ ...‬و‪ .......‬ســجل مدنــي رقــم‪ ...‬بالوكالــة‬\n      ‫رقــم ‪ 21719‬والوكالــة رقــم ‪ 21725‬الصادرتــن مــن هــذه اإلدارة يف‬\n      ‫‪1431/06/23‬ه ـ جلــد ‪ 3001‬وبصفتهــم أعضــاء مجلــس إدارة البنــك‬\n      ‫‪ .........‬شــركة مســاهمه ســعودية بالســجل التجــاري رقــم ‪ ......‬يف‬\n      ‫‪1376/12/27‬ه ـ ســجل جــدة والصــادر بــه املرســوم امللكــي رقــم م‪19/‬‬\n      ‫يف ‪1417/11/23‬هـ وقرار مجلس الوزراء رقم ‪ 186‬يف ‪1417/11/22‬هـ‬\n      ‫واملصــدق نظامــه األساســي مــن اإلدارة العامــة للشــركات بــوزارة‬\n      ‫التجــارة برقــم ‪ 2405/205/222‬يف ‪1422/06/24‬ه ـ واملتضمن النظام‬\n      ‫األساســي تعيــن األعضــاء يف اجلمعيــة العموميــة يف املــادة ‪ 16‬واملعينــن‬\n      ‫مبوجــب محضــر انعقــاد اجلمعيــة العامــة يف ‪1430/04/03‬ه ـ و اجلمعيــة‬\n      ‫العامــة احلاديــة عشــر يف ‪1431/04/15‬ه ـ ومبوجــب خطــاب مديــر عــام‬\n      ‫وزارة التجــارة و الصناعــة بجــدة برقــم ‪ 17167‬يف‪1431 / 05 / 20‬ه ـ‬\n      ‫وبعــد تعريفــه مــن‪ ...... :‬ســعودي ســجل مدنــي ‪ ...‬و‪ ......‬ســعودي ســجل‬\n      ‫مدنــي‪ .....‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بجنــوب‬\n      ‫جــدة برقــم ‪ 31391‬وتاريــخ ‪1431/9/20‬ه ـ جلــد ‪ 3097‬وادعــى علــى‬\n      ‫احلاضــر معــه ‪......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪....‬‬\n      ‫بصفتــه وكيــا لــ‪ ......‬فلســطيني اجلنســية مبوجــب اإلقامــة رقــم ‪....‬‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة شــمال محافظــة‬\n      ‫جــدة برقــم ‪ 35561‬وتاريــخ ‪1433/4/19‬ه ـ جلــد ‪ 11639‬قائــا‪ :‬لقــد‬\n      ‫قــام املدعــى عليــه بتحويــل مبلــغ وقــدره ‪ 300‬ألــف ريــال مــن حســاب ‪...‬‬\n      ‫لــدى البنــك ‪ ...‬رقــم إلــى حســابه رقــم لــدى البنــك ‪ ...‬مبوجــب تفويــض‬\n      ‫مــزور صــادر عــن املصنــع ‪ ،...‬وقــد تقــدم املصنــع ‪ ...‬بشــكوى لــدى البنك‬\n\n\n‫‪271‬‬\n\f‫بتاريــخ ‪2008/7/2‬م يعتــرض فيهــا علــى حتويــل املبلــغ املذكــور حلســاب‬\n‫شــخص غيــر معــروف لديهــم‪ ،‬ومــن خــال البحــث تبــن أن التحويــل مت‬\n‫مــن خــال املدعــى عليــه مبوجــب التفويــض املــزور وعليــه ختــم ومصــدق‬\n‫مــن الغرفــة التجاريــة‪ ،‬وعلــى الفــور مت مخاطبــة شــرطة محافظــة جــدة‬\n‫قســم مكافحــة التزييــف والتزويــر بتاريــخ ‪2009/1/26‬م وتزويدهــم‬\n‫بنمــوذج التفويــض املمنــوح للمدعــى عليــه مــن قبــل الشــركة ومنــوذج‬\n‫طلــب احلوالــة محــل النــزاع‪ ،‬وقــد صــدر التقريــر الفنــي لألدلــة اجلنائيــة‬\n‫بتاريــخ ‪2009/2/2‬م واملتضمــن أن التوقيــع املنســوب لصاحــب املصنــع‬\n‫مــزور‪ ،‬وقــد قــام البنــك ‪ ...‬بإعــادة مبلــغ وقــدره ‪ 150‬ألــف ريــال حلســاب‬\n‫املصنــع‪ ،‬وأطلــب احلكــم بإلــزام املدعــى عليــه بدفــع مبلــغ وقــدره ‪150‬‬\n‫ألــف ريــال ملوكلــي‪ .‬هــذه دعــواي‪ .‬وبعــرض ذلــك علــى املدعــى عليــه‬\n‫وكالــة قــال‪ :‬أطلــب اإلمهــال للــرد‪ .‬وبســؤال املدعــى عليــه وكالــة هــل‬\n‫اســتلم موكلــك مبلــغ ‪ 300‬ألــف ريــال محــل الدعــوى قــال‪ :‬نعــم‪ ،‬لقــد مت‬\n‫حتويــل هــذا املبلــغ حلســاب موكلــي‪ ،‬وتفاصيلــه أحضرهــا اجللســة‬\n‫القادمة‪ .‬ثم رفعت اجللسة لذلك‪ .‬ويف يوم الثالثاء املوافق‪1433/06/03‬هـ‬\n‫افتتحــت اجللســة الســاعة ‪ 01 :16‬وفيهــا حضــر ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم بصفتــه وكيــا عــن ســعودي مبوجــب ســجل مدنــي‬\n‫رقــم بصفتــه رئيــس مجلــس إدارة البنــك ‪ ...‬وبوكالتــه عــن كل مــن ‪..../‬‬\n‫ســجل مدنــي رقــم‪ ....‬و‪ ....‬ســجل مدنــي رقــم‪ ....‬و‪ ....‬ســجل مدنــي رقــم‪.....‬‬\n‫و‪ .....‬ســجل مدنــي رقــم‪ ...‬و‪ ....‬ســجل مدنــي رقــم ‪....‬و‪....‬ســجل مدنــي‬\n‫رقــم‪ .....‬و ‪ ...‬ســجل مدنــي رقــم‪ .......‬و‪ ....‬ســجل مدنــي رقــم‪ .....‬بالوكالــة‬\n‫رقــم ‪ 21719‬والوكالــة رقــم ‪ 21725‬الصادرتــن مــن هــذه اإلدارة يف ‪23‬‬\n‫‪1431 / 06 /‬ه ـ جلــد ‪ 3001‬وبصفتهــم أعضــاء مجلــس إدارة البنــك ‪...‬‬\n\n\n                                                                                      ‫‪272‬‬\n\f      ‫التجــاري شــركة مســاهمه ســعودية بالســجل التجــاري رقــم ‪ /‬يف‪/ 27‬‬\n      ‫‪1376 / 12‬ه ـ ســجل جــدة والصــادر بــه املرســوم امللكــي رقــم م ‪ 19 /‬يف‬\n      ‫‪1417 / 11 / 23‬ه ـ وقــرار مجلــس الــوزراء رقــم ‪ 186‬يف ‪/ 11 / 22‬‬\n      ‫‪1417‬ه ـ واملصــدق نظامــه األساســي مــن اإلدارة العامــة للشــركات‬\n      ‫بــوزارة التجــارة برقــم ‪ 2405 / 205 / 222‬يف ‪1422 / 06 / 24‬ه ـ‬\n      ‫واملتضمــن النظــام األساســي تعيــن األعضــاء يف اجلمعيــة العموميــة يف‬\n      ‫املــادة ‪ 16‬واملعينــن مبوجــب محضــر انعقــاد اجلمعيــة العامــة يف ‪04 / 03‬‬\n      ‫‪1430 /‬ه ـ و اجلمعيــة العامــة احلاديــة عشــر يف ‪1431 / 04 / 15‬ه ـ‬\n      ‫ومبوجــب خطــاب مديــر عــام وزارة التجــارة و الصناعــة بجــدة برقــم‬\n      ‫‪ 17167‬يف‪1431 / 05 / 20‬ه ـ وبعــد تعريفــه مــن‪....... :‬ســعودي ســجل‬\n      ‫مدنــي‪ .....‬و‪ ......‬ســعودي ســجل مدنــي ‪ ......‬مبوجــب الوكالــة الصــادرة‬\n      ‫مــن كتابــة العــدل الثانيــة بجنــوب جــدة برقــم ‪ 31384‬وتاريــخ‬\n      ‫‪1431/9/20‬ه ـ جلــد ‪ 3097‬وحضــر املدعــى عليــه وكالــة‪ ،‬وبســؤال‬\n      ‫املدعــى عليــه وكالــة عــن مــا طلــب اإلمهــال مــن أجلــه قــدم مذكــرة عــن‬\n      ‫موكلــه هــذا نصهــا‪ :‬إننــي وقبــل تاريــخ ‪1430/3/13‬ه ـ قمــت بالذهــاب‬\n      ‫إلــى مطــار امللــك عبــد العزيــز مبحافظــة جــدة الســتقبال احــد معــاريف‬\n      ‫حيــث أننــي أرســلت شــهاداتي الدراســية إلــى دولــة مصــر وذلك للتســجيل‬\n      ‫يف إحــدى اجلامعــات هنــاك وبعــد اســتالمي الشــهادات جاءنــي رجــل‬\n      ‫بالعقــد الرابــع مــن العمــر ويدعــى (‪ ).......‬وكانــت ترافقــه زوجتــه وابنــه‬\n      ‫وطلــب منــي أن أقــوم بإيصالــه إلــى شــارع ‪ ...‬وقمــت بإيصالــه وبعــد ذلــك‬\n      ‫طلــب منــي أن أقــوم بإيصالــه ملشــاويره اخلاصــة وذلــك مقابــل مبلــغ مائتان‬\n      ‫وخمســون (‪ )250‬ريــال فوافقــت لعــدم وجــود عمــل لــدي ‪ ،‬ويف اليــوم‬\n      ‫الثالــث مــن مجيئــه قــام باالتصــال بــي عنــد الســاعة احلادية عشــر صباحا‬\n\n\n‫‪273‬‬\n\f‫وقــال لــي انــه يريــد الذهــاب إلــى املطــار ويف الطريــق ذكــر لــي انــه ميلــك‬\n‫مؤسســة جتاريــة يف مدينــة الريــاض وانــه بحاجــة إلــى مبلــغ مالــي ولكــن‬\n‫ال يســتطيع أن يســحب املبلــغ مــن حســاب مؤسســته لعــدم وجــود اخلتــم‬\n‫لديــه فســألني أن كان يوجــد لــدي حســاب بالبنــك ‪ ...‬ليقــوم بتحويــل‬\n‫املبلــغ مــن حســاب مؤسســته إلــى حســابي ليتــم ســحبه مــن قبلــي ‪ ،‬فقمت‬\n‫بإعطائــه حســابي اخلــاص بالبنــك ‪ ...‬وبالفعــل مت التحويــل وكان املبلــغ‬\n‫قــدره ثالثمائــة ألــف (‪ )300,000‬ريــال وكان ذلــك بعــد االستفســار مــن‬\n‫فــرع البنــك ‪ ...‬مبطــار امللــك عبــد العزيــز ‪ ،‬فقــال لــي قــم بســحب مبلــغ‬\n‫مائتــان وخمســة وتســعون ألــف (‪ )295,000‬ريــال لــه وان أقــوم بأخــذ‬\n‫مبلــغ خمســة أالف (‪ )5000‬ريــال وذلــك مقابــل خدمتــي لــه وبعــد عشــرة‬\n‫شــهور قامــت املباحــث باســتيقايف بطريــق املدينــة وإيداعــي الســجن‬\n‫بدعــوى أن التحويــل مت بواســطة ورق مــزورة مــن مدينــة الريــاض التــي مت‬\n‫التحويــل منهــا حيــث اننــي ال اعلــم مــن الــذي قــام بهــذا العمــل طيلــة‬\n‫مكوثــي بالســجن لعلــم فضيلتكــم أن ال حــول لــي وال قــوة إال بــاهلل‪،‬‬\n‫وبعــد خروجــي بأمــر اهلل ســبحانه وتعالــى بحثــت عــن املتســبب عــن ذلــك‬\n‫وهــو شــخص فلســطيني اجلنســية ويدعــى ‪ /‬ورقــم جوالــه ‪ .../‬وعلمــت انــه‬\n‫هــو مــن انتحــل شــخصية كفيلــة املدعــو ‪ /‬واســتطعت أيضـ ًا بتوفيــق مــن‬\n‫اهلل ســبحانه وتعــال باحلصــول علــى رقــم جــوال كفيــل املدعــو ‪ /‬وهــو ‪/‬‬\n‫وقــد قمــت ببــاغ لشــرطة محافظــة جــدة لــدى ضابــط التحقيــق املختــص‬\n‫فأبلغنــي أن يتــم طلبــه عــن طريــق القاضــي لكــون القضيــة منظــورة‬\n‫لديــه ولــم يتــم لبــت بهــا‪ .‬لــذا ارجــو مــن اهلل ثــم مــن فضيلتكــم طلــب‬\n‫الشــخص الــذي قــام بذلــك وهــو املتســبب بدخولــي الســجن وكذلــك‬\n‫التزويــر وهــو مــن يســتحق العقــاب وليــس أنــا‪ .‬وبعــرض ذلــك علــى املدعــي‬\n\n\n                                                                                        ‫‪274‬‬\n\f      ‫وكالــة قــال‪ :‬أطلــب اإلمهــال للــرد‪ .‬ثــم رفعــت اجللســة لذلــك ولطلــب‬\n      ‫املتداخــل‪ .‬ويف يــوم الســبت املوافق‪1433/07/05‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ 01 :15‬وفيهــا حضــر املدعــي وكالــة علــي‪ ،‬وحضــر املدعــى‬\n      ‫عليــه أصالــة ‪ ...‬فلســطيني اجلنســية مبوجــب اإلقامــة رقــم ‪ ،‬وبســؤال‬\n      ‫املدعــي وكالــة عمــا طلــب الوكيــل اآلخــر اإلمهــال مــن أجلــه قــال‪ :‬إن‬\n      ‫مذكــرة املدعــى عليــه إمنــا هــي ســرد لقصــة ال عالقــة ملوكلــي البنــك‬\n      ‫فيهــا‪ ،‬وإمنــا يؤكــد فيهــا بــأن املبلــغ أودع يف حســابه بقبولــه ومعرفتــه‪،‬‬\n      ‫وأطلــب إلــزام املدعــى عليــه بإعــادة املبلــغ محــل الدعــوى وقــدره ‪150‬‬\n      ‫ألــف ريــال‪ ،‬والــذي أديــن بســببه لــدى ديــوان املظالــم وحكــم عليــه‬\n      ‫بغرامــة ماليــة والســجن‪ .‬وبعــرض ذلــك علــى املدعــى عليــه قــال‪ :‬إننــي أقــر‬\n      ‫باســتالم املبلــغ بعــد أن أودع يف حســابي‪ ،‬ولكــن ملصلحــة مســتفيد آخــر‬\n      ‫هــو ‪ ،...‬وقــد مت طلبــه لهــذه اجللســة ولــم يحضــر‪ ،‬وأطلــب إحضــاره بالقوة‬\n      ‫اجلبريــة‪ .‬وباالطــاع علــى أوراق املعاملــة وجــد أنــه مت طلــب ‪ ...‬وتبليــغ ‪...‬‬\n      ‫ابــن كفيــل املدعــى عليــه عــن طريــق محضــري اخلصــوم‪ .‬ثــم رفعــت‬\n      ‫إلحضــار املتداخــل أردنــي اجلنســية مبوجــب اإلقامــة رقــم ولــو أدى ذلــك‬\n      ‫الســتخدام القــوة اجلبريــة‪ .‬ويف يــوم األحــد املوافــق ‪1433/08/04‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 02 :00‬وفيهــا حضــر الطرفــان‪ ،‬وقــد أبــرز‬\n      ‫املدعــى عليــه خطــاب مديــر شــعبة تنفيــذ األحــكام احلقوقيــة بشــمال‬\n      ‫جــده املكلــف برقــم ‪/79‬ح ش ‪ 22/‬وتاريــخ ‪1433/8/4‬ه ـ املتضمــن أنــه‬\n      ‫لــم يتــم العثــور علــى املذكــور حيــث أفادنــا ابنــه بــأن والــده مســافر خارج‬\n      ‫اململكــة حســبما يتضــح لكــم مــن محضــر االنتقــال املرفــق ‪ .‬أه ـ ثــم‬\n      ‫قــدم املدعــى عليــه مذكــرة هــذا نصهــا‪ :‬أوال ‪ /‬ال يحــق للبنــك ‪ ...‬إنــكار‬\n      ‫أو إثبــات مــا ذكرتــه يف اجللســة الســابقة وإن أنكــر أقوالــي فذلــك‬\n\n\n‫‪275‬‬\n\f‫يعتبــر اتهامــا باطــا وحيــث أننــي مــا زلــت أطالــب بالتحقــق مــن أقوالــي‬\n‫الســابقة وإحضــار الســيد ‪ /‬أردنــي اجلنســية وعنــد حضــوره ســوف يتــم‬\n‫إثبــات صحــة أقوالــي بــإذن اهلل ثانيــا ‪ /‬إن احلكــم الصــادر بحقــي مــن‬\n‫ديــوان املظالــم املتعلــق بقضيــة التزويــر لم يتم إصداره إال ألنني املســتفيد‬\n‫( ألن احلوالــة نزلــت يف حســابي ) مــن مبلــغ احلوالــة وانــه لــم يتــم احلكــم‬\n‫بنــاء علــى تورطــي بعمليــه التزويــر وحيــث أن املســتفيد الفعلــي مــن عمليه‬\n‫التحويــل هــو ‪.............‬وحيــث أن ديننــا احلنيــف قــد حثنــا علــى معاقبــة‬\n‫فاعــل اجلــرم وليــس شــخصا آخــر كمــا جــاء يف القــران الكــرمي قــول‬\n‫اهلل تعالــى ( وال تــزر وازرة وزر أخــرى) لذلــك نرجــو مــن فضيلتكــم‬\n‫التحقــق والتأكــد مــن اجلانــي وذلــك بإحضــار الســيد ‪ ...‬أردنــي اجلنســية‬\n‫وأخــذ أقوالــه وعندهــا بــإذن اهلل ســوف يتــم إظهــار احلــق ومعرفــه فاعــل‬\n‫اجلــرم‪ .‬وبعــرض ذلــك علــى املدعــي وكالــة قــال‪ :‬ليــس لــدي إضافــة علــى‬\n‫مــا ذكــر يف الدعــوى‪ ،‬وأطلــب اإلمهــال للرجــوع ملوكلــي يف ذلــك‪،‬‬\n‫وأطلــب التعميــم علــى املتداخــل أردنــي اجلنســية مبوجــب اإلقامــة رقــم‬\n‫بحســب إفــادة املدعــى عليــه‪ .‬ثــم رفعــت اجللســة لذلــك‪ .‬ويف يــوم األحــد‬\n‫املوافــق ‪1433/09/17‬ه ـ افتتحــت اجللســة الســاعة ‪ 01 :00‬وفيهــا حضر‬\n‫الطرفــان‪ ،‬ولــم يردنــا شــيء بخصــوص املتداخل ‪ ،‬وحيــث تعذر إحضاره‬\n‫فــإن الدعــوى تتوجــه للمدعــى عليــه‪ ،‬حيــث إن عليــه عــبء إحضــار‬\n‫املتداخــل‪ ،‬وبســؤال املدعــى عليــه البينــة علــى مــا دفــع بــه يف الدعــوى‬\n‫قــال‪ :‬أطلــب اإلمهــال إلحضارهــا‪ .‬ثــم رفعــت اجللســة لذلــك‪ .‬ويف يــوم‬\n‫االثنني املوافق ‪1433/11/01‬هـ افتتحت اجللســة الســاعة ‪ 01 :30‬وفيها‬\n‫حضــر الطرفــان‪ ،‬وبســؤال املدعــى عليــه عمــا طلــب اإلمهــال مــن أجلــه‬\n‫قــال‪ :‬أطلــب اإلمهــال مــرة أخــرى‪ .‬وبعــرض ذلــك علــى املدعــي وكالــة‬\n\n\n                                                                                      ‫‪276‬‬\n\f      ‫قــال‪ :‬ال أمهلــه‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‪ ،‬وبنــاء علــى‬\n      ‫إقــرار املدعــى عليــه باســتالم كامــل املبلــغ محــل الدعــوى وقــدره‬\n      ‫ثالثمائــة ألــف ريــال‪ ،‬وذلــك بإيــداع املبلــغ يف حســابه‪ ،‬ومــن ثــم صــرف‬\n      ‫مبلــغ قــدره مائتــان وخمســة وتســعون ألــف ريــال‪ ،‬وتســليم ذلــك املبلــغ‬\n      ‫للمدعــو ‪ ،‬وإبقــاؤه ملبلــغ خمســة آالف ريــال يف حســابه‪ ،‬وبنــاء علــى تعــذر‬\n      ‫الوصــول للمدعــو‪ ، .......‬وبنــاء علــى أن املدعــى عليــه لــم يقــم البينــة علــى‬\n      ‫دفعــه بعــد إمهالــه لذلــك‪ ،‬وحلديــث (علــى اليــد مــا أخــذت حتــى تؤديــه)‬\n      ‫رواه األربعــة‪ ،‬وحلديــث (أن النبــي صلــى اهلل عليــه وســلم قضى أن اليمني‬\n      ‫علــى املدعــى عليــه) رواه البخــاري‪ ،‬وحلديــث (البينــة علــى املدعــي‬\n      ‫واليمــن علــى املدعــى عليــه) رواه الترمــذي‪ ،‬قــال أبــو عيســى‪ :‬العمــل‬\n      ‫عنــد أهــل العلــم مــن أصحــاب النبــي صلــى اهلل عليــه وســلم وغيرهــم أن‬\n      ‫البينــة علــى املدعــي واليمــن علــى املدعــى عليــه‪ ،‬لذلــك كلــه‪ ،‬فقــد‬\n      ‫حكمــت علــى املدعــى عليــه ‪ ...‬بدفــع مبلــغ وقــدره مائــة وخمســون ألــف‬\n      ‫ريــال للمدعــي البنــك ‪ ، ...‬وأفهمــت املدعــى عليــه بــأن لــه الرجــوع علــى‬\n      ‫املدعــو باملبلــغ احملكــوم بــه متــى مــا ثبــت ذلــك‪ .‬وبه قنع املدعــي وكالة‪،‬‬\n      ‫وقــرر املدعــى عليــه االعتــراض‪ ،‬وجــرى تســليمه نســخة مــن احلكــم‬\n      ‫وإفهامــه بــأن لــه احلــق يف االعتــراض عليــه خــال ثالثــن يومــا‪ ،‬وإال‬\n      ‫ســقط حقــه يف االعتــراض‪ ،‬واكتســب احلكــم القطعيــة‪ .‬وأقفلــت‬\n      ‫اجللســة الســاعة ‪ 02 :00‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                 ‫وعلى آله وصحبه وسلم‪ .‬حرر يف ‪1433/11/01‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي باحملكمــة العامــة بجدة خلف‬\n      ‫الشــيخ ففــي يــوم الســبت املوافــق ‪1434/01/24‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ 8 :15‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف بخطــاب‬\n\n\n‫‪277‬‬\n\f‫رئيســها رقــم ‪ 3429475‬وتاريــخ ‪1434/1/17‬ه ـ وبالقــرار رقم ‪349355‬‬\n‫وتاريــخ ‪1434/1/12‬ه ـ واملتضمــن مــا يلــي وبدراســة الصــك وصــورة‬\n‫ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم وحتــى ال‬\n‫يخفــى جــرى أثباتــه وأمــرت بإحلاقــه بصكــه وســجله وأقفلــت اجللســة‬\n‫الســاعة‪ 8 :32‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n                             ‫آلــه وصحبــه وســلم حــرر يف ‪1434/1/24‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                  ‫‪278‬‬\n\f279\n\f280\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":269,"source_page_end":280,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"84eb0d81b9c79642bac342ba76e31a768adcb136e736ac66161061175c818b59","normalized_text_hash":"34c3754272bd32581387eeb99e5c0885f0785cfabc2fc9e41a8583ae533d8ac3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p269-33443865"},{"id":"1291bb0f-5960-5196-acc2-15143cd0c21b","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مختلس -اختاس مبالغ مالية عن طريق خيانة األمانة -بينات غير موصلة -إثبات الدفع بالبراءة -ضمان األجير اخلاص -احلكم برد دعوى -استحقاق املدعي ليمن خصمه على نفي الدعوى متى","document_number":"34261913","case_number":"410","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بخميس مشيط","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/8","year":"1434","subject":"رد مختلس -اختاس مبالغ مالية عن طريق خيانة األمانة -بينات غير موصلة -إثبات الدفع بالبراءة -ضمان األجير اخلاص -احلكم برد دعوى -استحقاق املدعي ليمن خصمه على نفي الدعوى متى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/7/8 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34261913 :‬‬\n                              ‫َر ْق ُم الدعوى‪410 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34313612‬تاريخه‪1434/9/7:‬هـ‬\n\n\n      ‫رد مختلــس‪ -‬اختــاس مبالــغ ماليــة عــن طريــق خيانــة األمانــة ‪ -‬بينات‬\n      ‫غيــر موصلــة ‪ -‬إثبــات الدفــع بالبــراءة ‪ -‬ضمــان األجير اخلاص‪ -‬احلكم‬\n      ‫بــرد دعــوى‪ -‬اســتحقاق املدعــي ليمــن خصمــه علــى نفــي الدعــوى متــى‬\n                                                                     ‫طلبها‪.‬‬\n\n\n\n\n                                                               ‫األصل براءة الذمة‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل الشــركة املدعيــة علــى احلاضــر معــه بأنــه َّإبــان عملــه لدى‬\n      ‫موكلتــه كمديــر ألحــد فروعهــا قــام باختــاس مبالــغ ماليــة والتفريــط‬\n      ‫يف حتصيــل مســتحقات للشــركة املدعيــة‪ ،‬وطلــب إلزامــه بتســليم‬\n      ‫املبالــغ املترتبــة علــى ذلــك إلــى الشــركة موكلتــه‪ -‬أنكــر املدعــى‬\n      ‫عليــه الدعــوى جملــة وتفصيــا ودفــع بــأن جــزء مــن املبالــغ املدعــى بهــا‬\n      ‫هــي حتــت مســؤولية مندوبــي املبيعــات وال عالقــة لــه بهــا‪ -‬قــدم وكيــل‬\n      ‫املدعيــة عــددا مــن البينــات إلــى احملكمــة إال أنهــا غيــر موصلــة إلثبــات‬\n      ‫دعواه‪-‬كمــا أحضــر املدعــى عليــه شــاهدين إلثبــات مــا دفــع بــه فشــهدا‬\n      ‫مبــا يثبــت ذلــك وعــدال التعديــل الشــرعي‪ -‬ألن املدعــى عليــه يــده يــد‬\n      ‫أمانــة فــا يضمــن إال إذا تعــدى أو فــرط واألصــل بــراءة الذمــة‪ -‬لــذا‬\n\n‫‪281‬‬\n\f‫انتهــت جهــة التحقيــق إلــى عــدم اتهــام املدعــى عليــه مبــا نســب إليــه‪-‬‬\n‫وقضــت احملكمــة بصــرف النظــر عــن دعــوى املدعيــة وأفهمــت وكيلهــا‬\n‫بــأن لــه ميــن املدعــى عليــه علــى نفــي مــا أدعــى بــه متــى طلبهــا‪ -‬قنــع‬\n‫املدعــى عليــه باحلكــم وعــارض عليــه وكيــل املدعيــة‪ -‬قــررت محكمــة‬\n                                          ‫االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة بخميــس‬\n‫مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بخميــس مشــيط برقــم ‪ 410‬وتاريــخ ‪ 1431/07/02‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 312217‬وتاريــخ ‪ 1431/07/02‬ه ـ ففــي يــوم الثالثــاء‬\n‫املوافــق‪ 1432/06/28‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 :40‬وفيهــا حضر‬\n‫‪ ......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ......‬حــال كونــه‬\n‫وكيــا عــن ‪ ......‬الوكيــل الشــرعي عــن بصفتهــم مديريــن لشــركة‬\n‫مجموعــة ‪ ......‬الصناعيــة مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل‬\n‫ا إن هــذا‬   ‫شــمال جــدة الثانيــة برقــم ‪ 99351‬يف ‪1431/12/3‬ه ـ قائ ـ ً‬\n‫احلاضــر معــي كان يعمــل لــدي الشــركة موكلتــي بصفتــه مديــر ًا لفرع‬\n‫الشــركة يف املنطقــة اجلنوبيــة منــذ مــا يقــارب ســبعة عشــر عام ـ ًا وقــد‬\n‫حصــل منــه خلــل يف عملــه يف الســنوات اخلمــس األخيــرة وترتــب علــى‬\n‫ذلــك عــدة مطالبــات للشــركة جتاهــه وحينهــا قامــت الشــركة بفصلــه‬\n‫مــن الشــركة وذلــك قبــل ســنة ونصــف تقريبـ ًا واملطالبــات التــي تطالــب‬\n‫بهــا الشــركة موكلتــي علــى النحــو التالــي‪ :‬أوالً‪ :‬قيمــة واحــد وخمســون‬\n‫ثالجــة قــام املدعــى عليــه بالتصــرف فيهــا وهــي عهــدة عليــه لــم يقــم‬\n\n                                                                                     ‫‪282‬‬\n\f      ‫بإرجاعهــا للشــركة حــن فصلــه وقيمــة هــذه الثالجــات خمســون ألــف‬\n      ‫وثمامنائــة وخمســة وأربعــون ( ‪ ) 50845‬ريــال فنطلــب إرجاعهــا أو قيمتها‪.‬‬\n      ‫ثاني ـاً‪ :‬فواتيــر صيانــة مصطنعــة مببلــغ قــدره ثالثــون ألــف وســتمائة‬\n      ‫وواحــد وتســعون ( ‪ ) 30691‬ريــال قــام املدعــى عليه باصطناعها وليســت‬\n      ‫صحيحــة‪ .‬ثالثـاً‪ :‬ديــون غيــر محصلــة مســتحقة للشــركة علــى اآلخريــن‬\n      ‫لــم يقــم املدعــى عليــه بتحصيلهــا وقدرهــا مائــة وواحــد وســبعون ألــف‬\n      ‫واثنــان وثالثــون (‪ )171032‬ريــا ًال وقــد نصــت املــادة اخلامســة مــن عقــد‬\n      ‫العمــل املبــرم بينهمــا علــى أن املدعــى عليــه مســئول عــن جميــع املبالــغ‬\n      ‫احلاصلــة واآلجلــة علــى اآلخريــن لــذا فــإن الشــركة موكلتــي تطالــب‬\n      ‫املدعــى عليــه بجميــع هــذه املطالبــات وقدرهــا مائتــان وواحــد وســتون‬\n      ‫ألفـ ًا وخمســمائة وثمانيــة وســتون (‪ )261568‬ريــا ًال هــذه دعــواي وبعــرض‬\n      ‫ذلــك علــى املدعــى عليــه أجــاب قائ ـاً‪ :‬مــا ذكــره املدعــي وكالــة يف‬\n      ‫دعــواه مــن أنــي كنــت موظف ـ ًا لــدى شــركة موكلتــه بصفتــي مديــر ًا‬\n      ‫لفــرع اجلنــوب فهــذا صحيــح ومــا ذكــره مــن املطالبــات املاليــة التــي‬\n      ‫يدعيهــا وأنــي مختلــس لهــا فهــذا غيــر صحيــح وقــد حققــت الشــرطة‬\n      ‫واالدعــاء العــام يف املعاملــة وليــس فيهــا مــا يثبــت ذلــك فأما‪.‬بالنســبة‬\n      ‫للثالجــات والتــي ذكرهــا يف دعواهــا فــكان دوري يف الفــرع هــو‬\n      ‫اســتالم الثالجــات مــن املصنــع وتســليمها للمندوبــن وهــم بدورهــم‬\n      ‫يقومــون بتوزيعهــا علــى احملــات ويتــم اســتالم الثالجــة مــن قبــل املنــدوب‬\n      ‫والتوقيــع علــى االســتالم وتكــون بذلــك يف عهــده املندوبــن وقــد مت‬\n      ‫تســليم املندوبــن جميــع الثالجــات التــي اســتلمتها وقــام أحــد املندوبــن‬\n      ‫وهــو املدعــو‪ ....../‬هنــدي اجلنســية بســحب مائــة وســبعني ثالجــة وقــام‬\n      ‫بعدهــا بالهــروب ومت التبليــغ عنــه ومت حتصيــل مائــة وأربعــة وخمســن‬\n\n\n‫‪283‬‬\n\f‫ثالجــة بعــد البحــث عنهــا وإجــراء املســح الــازم وبقــي منهــا ســتة عشــر‬\n‫ثالجــة وهــي لــدى بعــض احملــات وبالبحــث عنهــا تبــن أن هــذه احملــات‬\n‫قامــت باالنتقــال مــن أماكنهــا دون إشــعار الشــركة ومــع ذلــك فهــي‬\n‫ليســت عهــدة علـ ّـي وإمنــا هــي علــى املنــدوب الهــارب وكذلــك عــدد عشــر‬\n‫ثالجــات عنــد الغيــر وأمــا بالنســبة لفواتيــر الصيانــة التــي ذكرهــا فهــذا‬\n‫غيــر صحيــح بــل إن الصيانــة الفعليــة كانــت يجــب أن تكــون أكبــر‬\n‫مــن هــذا املبلــغ وقــد ُذكــر ذلــك لــدى جهــة التحقيــق بعــد اســتدعاء بعض‬\n‫املناديــب وإقرارهــم بــأن مــا كان يتــم صيانتــه مــن ثالجــة تقــدر صيانتهــا‬\n‫بأكثــر مــن ذلــك وأمــا بالنســبة للديــون غيــر احملصلــة فاجلــواب عنهــا‬\n‫كاجلــواب عــن الثالجــات الــواردة يف البنــد أو ًال مــن حيــث كــون مهمتــي‬\n‫توزيــع املســئوليات وأمــا الديــون فتكــون علــى املناديــب وهــم مســئولون‬\n‫مســئولية تامــة عــن حتصيلهــا مــن اآلخريــن وهــذا الهنــدي املذكــور أنفـ ًا‬\n‫عندمــا هــرب كان مطلوبـ ًا مببلــغ مائة وواحد وســبعون ألف (‪)171000‬‬\n‫ريــال عبــارة عــن ديــون لــدى اآلخريــن لــم يحصلهــا فقمــت أنــا ومنــدوب‬\n‫مــن الشــركة مصــري اجلنســية اســمه ‪ .....‬باملــرور علــى احملــات وتســليم‬\n‫هــذه الديــون وقــد مت اســتالم املدعــو‪ ....... /‬منهــا مبلــغ مائــة وســتة عشــر‬\n‫ألفـ ًا ومائتــان وســبعة وثالثــون (‪ )116237‬ريــا ًال وبقــي منهــا مبلــغ أربعــة‬\n‫وخمســون ألــف وســبعمائة وخمســة وتســعون (‪ )54795‬ريــا ًال وقــد أثبــت‬\n‫هــذا لــدى الشــرطة ومــا ذكــره يف العقــد املبــرم بينــي وبــن الشــركة‬\n‫مــن حتميلــي مســئولية هــذه الديــون غيــر محصلــه فقــد صــدر بعــده عقــد‬\n‫أخــر بتاريــخ أحــدث ينســخ ذلــك وأطلــب االطــاع عليهــا هكــذا أجــاب‬\n‫ويف جلســة أخــرى حضــر الطرفــان وجــرى عــرض جــواب املدعــى عليــه‬\n‫ا بالنســبة ملــا ذكــره املدعــى عليــه من‬  ‫علــى املدعــي وكالــة فأجــاب قائـ ً‬\n\n\n                                                                                       ‫‪284‬‬\n\f      ‫أن القضيــة حقــق فيهــا مــن قبــل الشــرطة واالدعــاء العــام وأنــه ليــس فيهــا‬\n      ‫مــا يثبــت الدعــوى فهــذا غيــر صحيــح بــل يوجــد عليــه إقــرارات تثبــت‬\n      ‫ذلــك مرفقــة بــأوراق املعاملــة ومــا ذكــره مــن أن دوره يف الفــرع هــو‬\n      ‫اســتالم الثالجــات وتوزيعهــا علــى املندوبــن وأنهــا عهــدة علــى املندوبــن‬\n      ‫فغيــر صحيــح بــل هــي عهــدة عليــه وعلــى املنــدوب وهــو ضامــن للمنــدوب‬\n      ‫كمــا نــص عليــه العقــد ومــا ذكــره مــن أن املنــدوب ‪ ......‬قــام بســحب‬\n      ‫مائــة وســبعني ثالجــة وهــرب بعــد ذلــك فهــذا صحيــح ومــا ذكــره مــن أنــه‬\n      ‫مت إرجــاع مائــة وأربعــة وخمســن (‪ )154‬ثالجــة وبقــي ســتة عشــر (‪)16‬‬\n      ‫ثالجــة فهــذا غيــر صحيــح بــل بقــي عشــرين (‪ )20‬ثالجــة وهــى علــى‬\n      ‫املنــدوب الهــارب ولكــن املدعــى عليــه ضامــن لهــا باإلضافــة إلــى أن‬\n      ‫عنــده ثمــان ( ‪ )8‬ثالجــات عهــدة شــخصية عليــه ومــا ذكرهــن مــن أن‬\n      ‫فواتيــر الصيانــة صحيحــة وأن الصيانــة الفعليــة كان يجــب أن تكــون‬\n      ‫قيمتهــا أكثــر مــن ذلــك فغيــر صحيــح ويــدل علــى ذلــك أن الفواتيــر‬\n      ‫متسلســلة وغيــر مطابقــة للفواتيــر الصــادرة مــن الورشــة املذكــورة‬\n      ‫كمــا أن صاحــب الورشــة أفادنــا بــأن الورشــة مغلقــة منــذ ثــاث ســنوات‬\n      ‫وهنــاك تقريــر صــادر مــن محاســب قانونــي يبــن اخللــل يف ذلــك ومــا‬\n      ‫ذكــره مــن الديــون غيــر احملصلــة مت اســتالم مائــة وســتة عشــر ألــف‬\n      ‫(‪ )116000‬ريــال منهــا فهــذا صحيــح ومــا ذكــره مــن أنــه بقــي منهــا مبلــغ‬\n      ‫أربعــة وخمســون وســبعمائة وخمســة وتســعون (‪ )54795‬ريــا ًال فصحيــح‬\n      ‫وهــو مســئول عنهــا مســئولية تامــة كمــا هــو مبــن يف العقــد املبــرم بينــه‬\n      ‫وبــن الشــركة هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليــه أجــاب‬\n      ‫قائـاً‪ :‬بالنســبة ملــا ذكــره املدعــي مــن كونــي ضامــن للمنــدوب الهــارب‬\n      ‫فهــذا غيــر صحيــح وليــس يف العقــد مــا يثبــت ذلــك ومــا ذكــره مــن أنــه‬\n\n\n‫‪285‬‬\n\f‫مت اســتالم مائــة وأربعــة وخمســن (‪ )154‬ثالجــة فصحيــح وقــد ذكرتــه‬\n‫ســابق ًا واملتبقــي منهــا ســتة عشــر (‪ )16‬ثالجــة وليســت عشــرين (‪)20‬‬\n‫كمــا ذكــر وأمــا بالنســبة لثمــان (‪ ) 8‬الثالجــات التــي ذكروهــا بأنهــا‬\n‫عهــدة عنــدي فهــي لــدى التاجــر ‪ ....‬يف أحــد املســارحة مت تســلمه إياهــا‬\n‫بطريقــة رســمية وهــي بذلــك يف عهدتــه فــإذا كان للشــركة مطالبــة‬\n‫فاملطالبــة عليــه علمـ ًا بأنــه قــد كتــب خطابـ ًا للشــركة ذكر بــأن هناك‬\n‫خمــس ثالجــات منهــا قــد فقــدت يف ظــل األحــداث األخيــرة يف احلــدود‬\n‫اجلنوبيــة وبقــي عنــده ثــاث ثالجــات ومســتعد بتســليم هــذه الثالجــات‬\n‫وأمــا التــي فقــدت فطلــب ســماحه منهــا أو التفاهــم معــه حيالها وبالنســبة‬\n‫ملــا ذكــره مــن الصيانــة فالصحيــح مــا ذكرتــه ســابق ًا ومــا ذكــره مــن‬\n‫كــون الفواتيــر متسلســلة فاجلــواب عنــه أن الورشــة قــد خصصــت لنــا‬\n‫فواتيــر معينــة إلصدارهــا نظــر ًا لكوننــا متعاملــن معهــم دائم ـ ًا وقــد‬\n‫حضــر صاحــب الورشــة لــدي الشــرطة وقــرر بــأن هــذه الفواتيــر صحيحــة‬\n‫وقــد اســتلم حقهــا وبالنســبة ملــا ذكــره مــن الديــون غيــر احملصلــة وأنــي‬\n‫ضامــن للمنــدوب الهــارب فغيــر صحيــح ذلــك أن البنــد اخلامــس يف العقــد‬\n‫الســابق نــص علــى أننــي أنــا واملنــدوب متضامنــان يف متابعــة هــذه الديــون‬\n‫عنــد العمــاء واملنــدوب هــو املســئول عــن حتصيــل هــذه ا لديــون وأن‬\n‫مســئولتي مــع املنــدوب عــن هــذه الديــون مــا دامــت عنــد العمــاء أمــا إذا‬\n‫حتصــل عليهــا املنــدوب فهــو املســئول عنهــا وهــو مــا حصــل يف قضيتنــا‬\n‫هــذه وهــذا فيمــا يتعلــق بالعقــد الســابق وأمــا يف العقــد اجلديــد املبــرم يف‬\n‫عــام ‪2001‬م وقــد أحضرتــه الشــركة املدعيــة وأرفقته باألوراق مســتدلة‬\n‫بــه رغــم عــدم توقيعــه مــن قبلهــم وقــد نــص يف هــذا العقــد يف الفقــرة (‬\n‫‪ ) 13‬علــى أن الطــرف الثانــي وهــو املنــدوب بأنــه مســئول عــن جميــع‬\n\n\n                                                                                       ‫‪286‬‬\n\f      ‫املبيعــات اآلجلــة التــي تتــم عــن طريقــة وهــذه الفواتيــر التــي يطالبوننــي‬\n      ‫بهــا لــم تتــم عــن طريقــي وإمنــا متــت عــن طريــق املنــدوب الهــارب ‪ ......‬وأنــا‬\n      ‫لــم أبــع بريــال واحــد عــن طريقــي وإمنــا صفتــي يف هــذا العقــد مديــر‬\n      ‫مبيعــات هكــذا أجــاب ويف جلســة أخــرى حضــر الطرفــان فجــرى منــي‬\n      ‫ا بينتــي العقــود املبرمــة‬‫ســؤال املدعــي البينــة علــى دعــواه فأجــاب قائ ـ ً‬\n      ‫بــن الشــركة موكلتــي وبــن املدعــى عليــه ثــم أبــرز العقــد املــدون علــى‬\n      ‫مطبوعــات مؤسســة ‪ ......‬برقــم بــدون يف ‪1992/11/11‬م واملتضمــن مــا‬\n      ‫نصــه‪ « :‬بســم اهلل الرحمــن الرحيــم عقــد عمــل حــرر هــذا العقــد بــن‬\n      ‫كال مــن‪ :‬أوال‪ /‬مؤسســة ‪ ......‬للتجــارة والصناعــة واخلدمــات الطبيــة‬\n      ‫لصاحبهــا ‪ /‬وميثلهــا يف هــذا العقــد ‪ /‬طــرف أولــف ثاني ـاً‪ /‬الســيد ‪/‬‬\n      ‫أردنــي اجلنســية رقــم ا جلــواز ‪ /‬مصــدره‪ /‬الريــاض عنوانــه يف بلــده ‪/‬‬\n      ‫فلســطني ت‪ /‬طــرف ثانــي كمــا أبــرز العقــد املــدون علــى مطبوعــات‬\n      ‫مجموعــة ‪ ......‬رقــم بــدون يف ‪1416/8/10‬ه ـ املوافــق ‪1996/1/1‬م‬\n      ‫واملتضمــن مــا نصــه‪ « :‬بســم اهلل الرحمــن الرحيــم عقــد عمــل حــرر هــذا‬\n      ‫العقــد بــن كال مــن‪ :‬أوالً‪ :‬مؤسســة ‪ ......‬للتجــارة والصناعــة واخلدمــات‬\n      ‫الطبيــة لصاحبهــا ‪...... /‬وميثلهــا يف هــذا العقــد ‪ ...... /‬طــرف أول ثاني ـاً‪:‬‬\n      ‫الســيد ‪ ...... /‬اجلنســية أردنــي جــواز ســفر رقــم ‪ ...... /‬مصــدره الريــاض‬\n      ‫العنــوان ‪ ......‬ت ‪ ......‬طــرف ثانــي كمــا أبــرز ســندات صــرف مــن حســاب‬\n      ‫مصنــع ‪ ......‬لأليــس كــرمي تبــدأ مــن الرقــم ‪ 13840‬يف ‪2007/7/1‬م‬\n      ‫وتنتهــي بالســند رقــم ‪ 13847‬يف ‪2007/7/1‬م مببالــغ مختلفــة ومرفق ـ ًا‬\n      ‫بهــذه الســندات فواتيــر نقديــة مــن مؤسســة ‪ ......‬للتبريــد والتكييــف‬\n      ‫تبــدأ مــن الرقــم ‪ 29582‬يف ‪1417/5/1‬ه ـ وتنهــي بالرقــم ‪ 29589‬يف‬\n      ‫‪2007/5/1‬م بنفــس املبالــغ الســابقة وهــذه الفواتيــر مبوجبهــا مت‬\n\n\n‫‪287‬‬\n\f‫الســحب مــن حســاب الشــركة املدعيــة مــن خــال ســندات الصــرف‬\n‫املذكــورة بعاليــة وبســؤال املدعــي عــن وجــه اســتدالله بهذيــن العقديــن‬\n‫ا إنــه ورد يف البنــد رقــم (‪)5‬‬  ‫وســندات الصــرف املذكــورة فأجــاب قائـ ً‬\n‫يف العقديــن بــأن املنــدوب أو مديــر الفــرع مســئول مســئولية تامــة عــن‬\n‫الديــون التــي للشــركة علــى اآلخريــن وبذلــك يكــون املدعــى عليــه‬\n‫مســئول عــن هــذه الديــون التــي اختلســها العامــل ‪ ......‬وبالنســبة للســندات‬\n‫فــإن هــذه الســندات قــد أخــذت أرقــام متسلســلة ممــا يثيــر الشــك لدينــا‬\n‫يف صحــة هــذا الســندات هكــذا أجــاب وبعــرض ذلــك علــى املدعــى‬\n‫ا بالنســبة ملــا ورد يف هــذا البنــد فــإن هــذا خــاص‬    ‫عليــه أجــاب قائ ـ ً‬\n‫بالديــون التــي لــدى اآلخريــن ولــم يتــم حتصيلهــا فــإن مديــر الفــرع يكون‬\n‫متضامــن مــع املنــدوب فيهــا أمــا إذا مت حتصيلهــا مــن قبــل املنــدوب فإنــه‬\n‫يكــون مســئو ًال عنهــا وال يعــد علــى املتضامــن معــه أي مســئولية حينهــا‬\n‫وهــو مــا حصــل يف قضيتنــا هــذه حيــث إن العامــل الهــارب ‪ ......‬قــد حصــل‬\n‫هــذه الديــون مــن العمــاء ولــم يقــم بتســليمها للشــركة وعليــه فــإن‬\n‫املطالبــة تتوجــه ضــده ثــم إن هذيــن العقديــن صادريــن منــذ تاريــخ قــدمي‬\n‫أحدهــا قبــل عشــرين ســنة واألخــر قبــل خمســة عشــر ســنة وقــد صــدر‬\n‫بعدهــا عقــد ًا أخــر بتاريــخ ‪2001/12/9‬م وقــد تضمــن هــذا العقــد بــأن‬\n‫املنــدوب هــو املســئول عــن الديــون اآلجلــة التــي تتــم عــن طريقــه هكــذا‬\n‫أجــاب ثــم أبــرز عقــد العمــل املــدون علــى مطبوعــات مجموعــة ‪......‬‬\n‫الصناعيــة واملــؤرخ يف ‪2001/12/6‬م واملتضمــن مــا نصــه‪ »:‬عقــد عمــل‬\n‫حــرر هــذا العقــد بــن كال مــن‪ :‬أوال ‪ /‬شــركة مجموعــة ‪ ......‬الصناعيــة‬\n‫وميثلهــا يف هــذا العقــد الشــيخ مــا طــرف أول ثانيــا الســيد ‪ /‬اجلنســية‬\n‫أردنــي طــرف ثانــي وبســؤال املدعــى عليــه عــن وجــه االســتدالل مــن هــذا‬\n\n\n                                                                                    ‫‪288‬‬\n\f      ‫ا لقــد ورد يف البنــد رقــم ( ‪ ) 13‬أن الطــرف الثانــي‬     ‫العقــد أجــاب قائ ـ ً‬\n      ‫املنــدوب مســئول عــن جميــع املبيعــات اآلجلــة التــي تتــم عــن طريقــه‬\n      ‫ويتعهــد بتحصيلهــا وتســديدها ويف حالــة عــدم حتصيلهــا ألي ســبب يحق‬\n      ‫للطــرف األول خصمهــا مــن راتبــه وحقوقــه وال يتــم إخــاء طرفــه إال بعــد‬\n      ‫ســداده وأنــا يف هــذا العقــد صفتــي مديــر مبيعــات ولســت مندوبـ ًا كمــا‬\n      ‫أن هــذا البنــد نــص علــى أن مســئولية املنــدوب هــو يف جميــع املبيعــات‬\n      ‫اآلجلــة التــي تتــم عــن طريقــه وأنــا لــم يتــم بيــع أي شــيء عــن طريقــي ولــو‬\n      ‫بريــال واحــد هكــذا أجــاب كمــا أضــاف بأنــه فيمــا يتعلــق بالتسلســل‬\n      ‫يف أرقــام الســندات والفواتيــر فقــد أجبــت عنــه يف اجللســة املاضيــة حيــث‬\n      ‫خصصــت لنــا املؤسســة التــي نتعامــل معهــا دفاتــر خاصــة للفواتيــر‬\n      ‫لكوننــا نتعامــل معهــا دائمـ ًا ومــن الطبيعــي أن تصــدر الفواتيــر بأرقــام‬\n      ‫متسلســل ًة وهــذا بشــهادة صحــاب الورشــة هكــذا أجــاب وبعــرض ذلــك‬\n      ‫ا بالنســبة ملــا ذكــره املدعــى عليــه مــن‬‫علــى املدعــي وكالــة أجــاب قائـ ً‬\n      ‫أن املنــدوب الهــارب قــام بتحصيــل هــذه الديــون مــن اآلخريــن وهــرب بهــا‬\n      ‫فهــذا غيــر صحيــح بــل إن الديــون ال زالــت عنــد اآلخريــن ونطلــب مــا‬\n      ‫يثبــت مــن أن املنــدوب الهــارب قــام بتحصيــل هــذه الديــون مــن اآلخريــن‬\n      ‫وأمــا فيمــا يتعلــق بالعقــد الــذي اســتدل بهــا املدعــى عليــه فهــو عقــد غيــر‬\n      ‫صحيــح حيــث خــا مــن توقيــع الشــركة موكلتــي وعليــه فمــا يســتدل‬\n      ‫بــه منــه غيــر صحيــح ومــا ذكــره مــن أن الورشــة التــي يتعاملــون معهــا‬\n      ‫خصصــت دفاتــر فواتيــر وســندات خاصــة فهــذا ال نعلــم عنــه ثــم إن هــذه‬\n      ‫الفواتيــر تختلــف عــن الفواتيــر التــي تصــدر عــن املؤسســة التــي تتعامــل‬\n      ‫معهــا الشــركة موكلتــي كمــا أن هــذه الســندات يالحــظ عليهــا بــأن‬\n      ‫املدعــى عليــه هــو املســلم واملســتلم يف نفــس الوقــت هكــذا أجــاب‬\n\n\n‫‪289‬‬\n\f‫ا بالنســبة ملــا ذكــروه مــن‬  ‫وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائـ ً‬\n‫أن العامــل الهــارب لــم يقــم بتحصيــل الديــون التــي علــى اآلخريــن فأنــا‬\n‫أطلــب مــا يثبــت ذلــك ولــو كان مــا ذكــروه صحيح ـ ًا ملــاذا لــم يقومــوا‬\n‫بتحصيــل هــذه الديــون مباشــرة مــن العمــاء وملــاذا قامــوا بالتبليــغ عــن‬\n‫العامــل الهــارب ومطالبتــه باملبالــغ التــي اختلســها وأمــا العقــد الــذي‬\n‫يقولــون بأنــه غيــر نظامــي فأجيــب عنــه بأنهــم قــد قامــوا باالســتدالل‬\n‫بهــذا العقــد حــن قدمــوا الشــكوى لــدى الشــرطة ولــو كان العقــد غيــر‬\n‫صحيــح فلمــاذا يســتدلون بــه ثــم إن الطريقــة التــي تســير الشــركة عليــه‬\n‫يف التعاقــد مــع اآلخريــن أنهــا متلــي مــا تريــد إمالئــه ثــم تقــوم بإرســال‬\n‫العقــد للطــرف اآلخــر للتوقيــع عليــه وبعــد ذلــك يعــاد للشــركة وحتتفــظ‬\n‫بــه وال تعطــي للطــرف اآلخــر نســخة منــه وقــد توقــع هــذا العقــود وقــد ال‬\n‫توقعــه ومــا ذكــره مــن أن الفواتيــر غيــر مطابقــة للفواتيــر الصــادرة مــن‬\n‫الشــركة وأن املؤسســة مت إغالقهــا مــن قبــل ثــاث ســنوات فهــذا غيــر‬\n‫صحيــح بــل إن املؤسســة اســمها مؤسســة ‪ ......‬للتبريــد والتكييــف كمــا‬\n‫هــو مــدون يف الفواتيــر النقديــة وكمــا هــو مــدون يف إقــرار املؤسســة‬\n‫لــدى الشــرطة واملــدون علــى مطبوعــات املؤسســة وهــو مــؤرخ يف‬\n‫‪2010/6/23‬م وهــو كذلــك يــرد مــا زعمــوه مــن أن املؤسســة مغلقــة منــذ‬\n‫ثــاث ســنوات هكــذا أجــاب ثــم أبــرز اخلطــاب املــدون علــى مطبوعــات‬\n‫مؤسســة ‪ ......‬للتبريــد والتكييــف واملضمــن مــا نصــه‪ ( :‬بســم اهلل‬\n‫الرحمــن الرحيــم إلــى مــن يهمــه األمــر نفيــد نحــن مؤسســة ‪ ......‬للتبريــد‬\n‫والتكييــف بخميــس مشــيط أن جميــع الفواتيــر الصــادرة منــا ســواء‬\n‫كانــت فواتيــر قطــع غيــار أو فواتيــر ورشــة لشــركة أيــس كــرمي جمبــو‬\n‫طيلــة فتــرة تعاملهــم معنــا حلوالــي األربعــة عشــر ســنة املاضيــة أو أكثــر‬\n\n\n                                                                                      ‫‪290‬‬\n\f      ‫أثنــاء إدارة الســيد‪ / ....../‬لفــرع املنطقــة اجلنوبيــة كلهــا فواتير صحيحة‬\n      ‫ســواء كانــت بخــط يــده أو بحطنــا وذلــك حتــى نهايــة عملــة بالفــرع يف‬\n      ‫‪2010/10/24‬م ونفيــد أنــه قــد مت إغــاق وتصفيــة حســابنا معــه وال‬\n      ‫نطالبــه بشــيء كمــا أننــا نشــهد أن الســيد ‪ ...... /‬كان مثــا ًال لألمانــة‬\n      ‫والنزاهــة واألخــاق طيلــة تعاملــه معنــا‪ .‬واهلل ولــي التوفيــق مؤسســة ‪......‬‬\n      ‫للتبريــد والتكييــف اســم املســئول ‪ ......‬التوقيــع التاريــخ ‪2010/6/24‬م‬\n      ‫ا بــأن هــذا اخلطــاب يثبــت بــأن‬    ‫اخلتــم والبصمــة )‪.‬أ‪.‬ه ـ وأضــاف قائ ـ ً‬\n      ‫الفواتيــر التــي كانــت تصــدر منهــم صحيحــة وأنــه مت إغــاق احلســاب‬\n      ‫معــي علم ـ ًا بــأن مديــر الفــرع الــذي اســتلم اإلدارة منــي قــد حضــر لــدى‬\n      ‫مســئول الورشــة وهــو شــخص باكســتاني وال يحســن اللغــة العربيــة‬\n      ‫وكتــب خطاب ـ ًا بخــط يــده وجعــل املســئول بوقــع عليــه ويختــم بختــم‬\n      ‫الشــركة وقــد تضمــن هــذا اخلطــاب انــكار الفواتيــر الصــادرة منهــم‬\n      ‫وعنــد مقابلتــي بذلــك لــدى الشــرطة طلبــت منهــم إحضــار املســئول الــذي‬\n      ‫وقــع وســماع مــا لديــه وعنــد حضــوره أنكــر ذلــك وقــرر بــأن املديــر الــذي‬\n      ‫حضــر لديــة أفهمــه بــأن هــذا اخلطــاب بقــد تصفيــة حســابات املديــر‬\n      ‫الســابق مــع الشــركة وأنــه لــم يعــد لهــم أي مطالبــة جتاهــه ووقــع بنــا ء‬\n      ‫علــى ذلــك هكــذا أجــاب ثــم أبــرز اخلطــاب املــدون علــى مطبوعــات‬\n      ‫مؤسســة ‪ ......‬للتبريــد والتكييــف لبيــع قطــع الغيــار واملتضمــن‪( :‬الســادة‬\n      ‫‪ /‬مصنــع ‪ ......‬لآليســكرمي والعصيــر الســام عليكــم ورحمــه اهلل‬\n      ‫وبركاتــه نفيدكــم بــأن حســابنا الســابق مــع األخ ‪ /‬كان بــدون فواتيــر‬\n      ‫ومــن الواضــح مــن الفاتــورة أنــه قــام بأخــذ االســم اخلــاص بنــا للمحــل‬\n      ‫األخــر لنــا وقــام بتصويرهــا وعمــل كشــف حتــى يقــوم بكتابــة املبالــغ‬\n      ‫بنفســه وهــذه الفواتيــر ليســت لنــا كورشــة إصالح ومرفق طيــه الفاتورة‬\n\n\n‫‪291‬‬\n\f‫الــذي نحاســب بهــا وشــكر ًا مســئول الورشــة االســم ‪ ......‬التوقيــع‬\n‫البصمة)‪.‬أ‪.‬ه ـ وقــد كان حاضــر ًا يف أثنــاء اجللســة املديــر املســتلم إلدارة‬\n‫مــن املدعــى عليــه وهــو املدعــو ‪ /‬مصــري اجلنســية حامــل رخصــة اإلقامــة‬\n‫رقــم () وبعــرض ذلــك عليــه أجــا ب قائـاً‪ :‬صحيــح مــا أنــي كتبــت هــذا‬\n‫اخلطــاب بخــط يــدي لكــون العامــل ال يحســن اللغــة العربيــة وقــد كتــب‬\n‫مــا ذكــره لــي ثــم حضــر هــذا العامــل للشــرطة وأنكــر ذلــك وقــرر بأنــه‬\n‫وقــع علــى هــذا اخلطــاب بنــاء علــى أن هــذا اخلطــاب مخالصــة بــن‬\n‫الشــركة وبــن املديــر الســابق املدعــى عليــه وليــس علــى إنــكار تعامــل‬\n‫املدعــى عليــه مــع الشــركة وصحــة تعاملــه معهــا هكــذا أجــاب ثــم‬\n‫ا لــدي بينــة وهــي‬‫جــرى ســؤال املدعــي هــل لديــه مزيــد بينــة فأجــاب قائـ ً‬\n‫شــهادة هــذا احلاضــر معنــا ‪ /‬حامــل رخصــة اإلقامة الصــادرة من جوازات‬\n‫جــدة املديــر املســتلم لــإدارة مــن املدعــى عليــه وأطلــب ســماع مــا لديهــم‬\n‫وبســؤال املذكــور عمــا لديــه مــن شــهادة أجــاب أشــهد هلل بأنــي حــن‬\n‫اســتلمت اإلدارة مــن املدعــى عليــه يبــن لــي بــأن الفواتيــر التــي مت‬\n‫الصــرف مبوجبهــا مــن حســاب الشــركة تختلــف فيهــا اســم املؤسســة‬\n‫مــن اســم املؤسســة التــي تتعامــل معهــا الشــركة املدعيــة هــذا مــا لــدي‬\n‫مــن شــهادة ويف جلســة أخــرى حضــر حامــل بطاقــة الهويــة الوطنيــة رقــم‬\n‫ا عــن الوكيــل الشــرعي عــن بصفتهــم مديريــن‬            ‫حــال كونــه وكي ـ ً‬\n‫لشــركة مجموعــة ‪ ......‬الصناعيــة مبوجــب الوكالــة الصــادرة مــن‬\n‫كتابــة العــدل الثانيــة شــمال محافظــة جــدة برقــم ‪ 99351‬يف‬\n‫‪1431/12/3‬ه ـ املخــول لــه فيهــا حضــور اجللســات واملرافعــة واملدافعــة‬\n‫وتقــدمي املذكــرات واللوائــح االعتراضيــة وتقــدمي البينــات وســماع‬\n‫اخلصــوم والشــهود وردهــم ومناقشــتهم وتســميتهم ويف طلــب اليمــن‬\n\n\n                                                                                     ‫‪292‬‬\n\f      ‫وردهــا والقناعــة مــن عدمــه واإلقــرار واإلنــكار والصلــح ومتييــز‬\n      ‫األحــكام واســتئنافها وكالــة خاصــة وحضــر حلضــوره املدعــى عليــه ثــم‬\n      ‫جــرى عــرض الشــاهد وشــهادته املرصــودة يف اجللســة الســابقة علــى‬\n      ‫ا بــأن الشــاهد املذكــور قــد قــرر يف اجللســة‬   ‫املدعــى عليــه فأجــاب قائـ ً‬\n      ‫املاضيــة قبــل إدالئــه بشــهادته بأنــه قــد كتــب خطابـ ًا علــى لســان العامــل‬\n      ‫بالورشــة يديننــي فيــه ثــم حضــر العامــل للشــرطة وأنكــر ذلــك وهــذا‬\n      ‫قــادح يف قبــول شــهادته إذ كتــب عــن العامــل املذكــور مــا لــم يقلــه‬\n      ‫وبالنســبة لشــهادته فمــا ورد فيهــا غيــر صحيــح بــل إن الورشــة التــي‬\n      ‫تتعامل معها الشــركة املدعية أســمها مؤسســة ‪ ......‬للتبريد والتكييف‬\n      ‫والعامــل بهــذه الورشــة أقــر بــأن هــذه الفواتيــر صــادرة مــن ورشــتهم كما‬\n      ‫هــو موجــود يف أوراق املعاملــة هكــذا أجــاب ثــم جــرى ســؤال املدعــي‬\n      ‫ا اكتفــي مبــا يف أوراق‬       ‫وكالــة هــل لديــة مزيــد بينــه فأجــاب قائ ـ ً‬\n      ‫املعاملــة هكــذا أجــاب ثــم جــرى ســؤال املدعــى عليــه هــل لديــه مــا يريــد‬\n      ‫ا نعــم أوالً‪ :‬إن كفيلــي هــو شــركة مجموعــة ‪......‬‬     ‫إضافتــه فأجــاب قائـ ً‬\n      ‫للصناعــة كمــا هــو مبــن يف بطاقــة اإلقامــة اخلاصــة بــي وهــذا االســم‬\n      ‫للشــركة ذكــر كطــرف أول يف العقــد املبــرم بينــي وبــن هــذه‬\n      ‫الشــركة يف العقــد املبــرم يف عــام ‪2001‬م وهــذا يقــوى قولــي بــأن هــذا‬\n      ‫العقــد صحيــح بينمــا ذكــر يف العقــد املبــرم يف عــام ‪1996‬م بــأن الطــرف‬\n      ‫األول هــو مؤسســة ‪.....‬وذلــك قبــل حتويــل مســمى املؤسســة إلــى شــركة‬\n      ‫وبعــد التحويــل مت تغييــر كل شــيء حتــى االقامــات مت تغييرهــا وهــذا‬\n      ‫يؤكــد مــا ذكــرت بــأن هــذا العقــد األخيــر صحيــح إضافــة إلــى قــدم‬\n      ‫تاريــخ العقــد املبــرم يف عــام ‪1996‬م ثاني ـاً‪ :‬ورد يف تقريــر احملاســب‬\n      ‫القانونــي املرفــق عبــارة ( هــذه الديــون حتــت مســئولية املنــدوب ) ثالثــا‪:‬‬\n\n\n‫‪293‬‬\n\f‫يوجــد يف أورق املعاملــة العقــد املبــرم بــن الشــركة وبــن املنــدوب ‪......‬‬\n‫وقــد تضمــن البنــد (‪ )13‬بــأن املنــدوب مســئول عــن جميــع الديــون ويتعهــد‬\n‫بتســديدها‪ .‬رابعــا‪ :‬أن العقــد املبــرم بينــي وبــن الشــركة ال يوجــد فيــه‬\n‫مــا ينــص علــى أننــي مســئول عــن الثالجــات خامســا‪ :‬يوجــد يف أوراق‬\n‫املعاملــة قائمــة باســتالم املنــدوب الهــارب للثالجــات املذكــورة وعددهــا‬\n‫(‪ )172‬ثالجــة وقــد ذيــل عليهــا إقــرار املنــدوب مبســئوليته عنهــا مســئولية‬\n‫تامــة عــن هــذه الثالجــات وأنهــا يف عهدتــه ويتحمــل مســئولية أي ثالجــة‬\n‫مفقــودة سادســا‪ :‬بالنســبة لثالجــات (‪ )16‬التــي لــم تســتلمها الشــركة‬\n‫مــن عهــدة املنــدوب الهــارب هنــاك عقــود مرفقــة بــأوراق املعاملــة تثبــت‬\n‫بــأن املنــدوب الهــارب قــام بتســليم هــذه الثالجــات للعميــل ومت توقيــع‬\n‫العقــد بــن الطرفــن وســلم املنــدوب للشــركة العقــد مبينــا فيــه محــل‬\n‫وجــود الثالجــة وإذا قــام العميــل بنقــل احملــل أو بيعــه ونحــوه فــإن‬\n‫الشــركة تطالــب العميــل وال تعــود علــى املنــدوب أو املديــر إذ مهمــة‬\n‫املنــدوب واملديــر تنتهــي بتوقيــع العقــد وتســليمه للشــركة ســابعا‪ :‬إن‬\n‫العقــود تبــرم بــن الشــركة املدعيــة كطرف أول وبــن العميل كطرف‬\n‫ثانــي يقــوم املنــدوب بالتوقيــع عــن الشــركة وبــه تكــون الشــركة هــي‬\n‫املســئولة عــن هــذه الثالجــات فهــي التــي تتابعهــا ولهــا حــق التصــرف‬\n‫فيهــا ومطالبــة العميــل بهــا مبــا يترتــب علــى ذلــك مــن حقــوق ثامنــا‪:‬‬\n‫ثالجــات املنــدوب ‪ ......‬لــم تســتلم جديــد وإمنــا ‪ %90‬منهــا لهــا عــدت‬\n‫ســنوات تاســعا‪ :‬ثالجــات العصيــر الثمانيــة هــي ثالجــات اســكر مي‬\n‫مســتهلكه جــدا يتــم أعطاهــا لعميــل العصيــر بعــد إصالحهــا علــى‬\n‫حســابه اخلــاص ليســتخدمها يف تبريــد العصيــر يف املقاصــف ويوجــد يف‬\n‫املعاملــة عقــد مختــوم مبســؤولية العميــل عــن هــذه الثالجــات وعلــى‬\n\n\n                                                                                   ‫‪294‬‬\n\f      ‫الشــركة مطالبتــه بهــا‪ .‬عاشــرا‪ :‬الشــركة هــي كفيلــة للمندوبــن وهي‬\n      ‫التــي أرســلتهم للعمــل لــدي الفــرع وهــي املســؤولة عنهــم وصفتــي يف‬\n      ‫الفــرع اإلشــراف علــى أعمالهــم وتوزيــع املهــام بينهــم ومتابعــة ذلــك فقــط‬\n      ‫احلــادي عشــر‪ :‬أود اخــذ االعتبــار بتحقيــق الشــرطة مــع منســوبي الفــرع‬\n      ‫بخصــوص عــدد الثالجــات التــي كانــت ترســل إلــى الورشــة لإلصــاح‬\n      ‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــي وكالــة أجــاب قائــا بــان مــا‬\n      ‫ذكــره املدعــى عليــه كالم مرســل وليــس يف صلــب القضيــة هكــذا‬\n      ‫أجــاب ويف جلســة أخــرى فيهــا حضــر الطرفــان فجــرى ســؤال املدعــى‬\n      ‫عليــه هــل أحضــر مــا يريــد إضافتــه كمــا قــرر يف اجللســة املاضيــة‬\n      ‫فأجــاب قائــا نعــم قــد أحضرتــه معــي ثــم أبــرز مذكــرة مكونــة مــن‬\n      ‫(‪ )26‬صفحــة مقيــدة يف هــذه احملكمــة برقــم ( ‪ ) 321284138‬يف‬\n      ‫‪1432/10/15‬ه ـ وأضــاف بــأن لــدي شــاهد يشــهد بــأن الشــركة تطلب‬\n      ‫مــن العاملــن توقيــع العقــود ثــم بعثهــا لهــم دون توقيــع مــن قبــل الشــركة‬\n      ‫وأن املنــدوب هــو املســئول عــن حتصيــل الديــون التــي لــدى اآلخريــن‬\n      ‫كمــا أن لــدي شــاهد آخــر وهــو ضابــط يف شــرطة خميــس مشــيط‬\n      ‫يشــهد بــأن املدعــو قــد أقــر لديــه بأنــي مظلــوم يف هــذه القضيــة وأنــه‬\n      ‫مضغــوط عليــه مــن قبــل الشــركة لــإدالء بالشــهادة هكــذا قــرر‪،‬‬\n      ‫كمــا جــرى ســؤال املدعــي وكالــة هــل لديــه مــا يرغــب يف إضافتــه‬\n      ‫فأجــاب قائــا أكتفــي مبــا قدمتــه ومت رصــده ســابقا وبالنســبة ملــا قدمه‬\n      ‫املدعــى عليــه فهــو شــيء مكــرر وأطلــب إنهــاء القضيــة واحلكــم فيهــا‬\n      ‫هكــذا أجــاب ويف جلســة أخــرى فيهــا حضــر املدعــي وكالــه واملدعــى‬\n      ‫عليــه وأحضــر املدعــى عليــه شــاهدين معــه وطلــب ســماع مــا لديهمــا مــن‬\n      ‫شــهادة وهــم كل مــن ‪ /‬حامــل بطاقــة الهويــة الوطنيــة رقــم ســجل أبهــا و‬\n\n\n‫‪295‬‬\n\f‫املدعــو ‪ /‬مصــري اجلنســية حامــل اإلقامــة رقــم وبســؤال كل واحــد‬\n‫منهمــا عــن عمــره وعملــه ومقــر إقامتــه وقرابتــه باملدعــى عليــه ومــا لديــه‬\n‫مــن شــهادة أجــاب األول عمــري ثالثــون عامــا وأعمــل مديــرا ملخفــر‬\n‫احلفائــر التابــع حملافظــة خميــس مشــيط وأســكن يف مدينــة أبهــا وليــس‬\n‫هنــاك بينــي وبــن املدعــى عليــه قرابــة ومــا لــدي مــن شــهادة فأشــهد أنــي‬\n‫كنــت محققــا يف هــذه القضيــة أثنــاء عملي يف مركز شــرطة الشــمالية‬\n‫وكان يحضــر لــدي يف املركــز ثالثــة أشــخاص مــن قبــل املدعــي أولهما‬\n‫اســمه وكان مديــرا لفــرع الشــركة املدعيــة يف اجلنــوب آنــذاك والثانــي‬\n‫الوكيــل الشــرعي للشــركة واســمه والثالــث شــخص أســمه وال أعــرف‬\n‫عالقتــه بالشــركة إال أن الوكيــل الشــرعي مــا كان يتكلــم يف هــذه‬\n‫القضيــة إال بعــد أن يتكلــم املدعــو‪ ...... /‬واملدعــو‪ ...... /‬ويف يــوم مــن‬\n‫األيــام تقــدم ‪ ......‬يف احلضــور وقــرر أمامــي بــأن دعــوى الشــركة املدعيــة‬\n‫ليســت صحيحــة وأن املدعــى عليــه ‪ ......‬مظلــوم وإمنــا يريــد صاحــب‬\n‫الشــركة املدعيــة أهانتــه وإذاللــه حتــى يقــدم اعتــذاره لديــه إال أن‬\n‫املدعــى عليــه رفــض ذلــك وأن هــذه ليســت املــرة األولــى التــي يفعــل‬\n‫صاحــب الشــركة مبوظفيــه هــذه الفعلــة هكــذا قــرر املدعــو ‪...... /‬‬\n‫أمامــي هــذا مــا لــدي مــن شــهادة كمــا أجــاب الشــاهد الثانــي قائــا‬\n‫عمــري ســتة وأربعــون عامــا تقريبــا وأعمــل حاليــا يف مؤسســة ‪......‬‬\n‫للتجــارة وأســكن يف ‪ ......‬وال يوجــد بينــي وبــن املدعــى عليــه قرابــة ومــا‬\n‫لــدي مــن شــهادة فأنــا أشــهد أنــي كنــت أعمــل لــدي الشــركة املدعيــة‬\n‫مــن عــام ‪1414‬ه ـ وحتــى عــام ‪1427‬ه ـ مبســمى منــدوب مبيعــات وكان‬\n‫طريقــة الشــركة يف إبــرام العقــود مــع موظفيهــا أنهــا جتعــل املوظــف‬\n‫يوقــع علــى عقــد العمــل قبــل توقيــع صاحــب الشــركة ومــن ثــم يرســل‬\n\n\n                                                                                      ‫‪296‬‬\n\f      ‫العقــد للشــركة يف جــدة وال يعــود لنــا بعــد ذلــك هــذه النقطــة األولــى‬\n      ‫والنقطــة الثانيــة أن منــدوب املبيعــات للشــركة هــو املســئول عن املبيعات‬\n      ‫وعــن حتصيــل الديــون التــي للشــركة علــى اآلخريــن والنقطــة الثالثــة أن‬\n      ‫املنــدوب يقــوم بعــد حتصيــل الديــون بتســليم مــا لديــة من نقود للمحاســب‬\n      ‫ومــن ثــم يأخــذ املنــدوب ســندا بذلــك مــن احملاســب ويخصــم ذلــك مــن‬\n      ‫العهــد التــي علــى املنــدوب للشــركة وليــس ملديــر الفــرع أي عالقــة بذلــك‬\n      ‫وإمنــا دورة تنظيــم العمــل وإدارتــه بــن منســوبي الفــرع وليــس مســئوال عــن‬\n      ‫الديــون التــي للشــركة علــى اآلخريــن وإمنــا املســئول عنهــا منــدوب‬\n      ‫املبيعــات هــذا مــا لــدي مــن شــهادة وبعــرض الشــاهدين وشــهادتهم علــى‬\n      ‫املدعــي وكالــة أجــاب قائــا بالنســبة للشــاهدين فــا أعلــم عنهمــا شــيئا‬\n      ‫وبالنســبة للشــهادة فأطلــب مهلــة للــرد عليــه ويف جلســة أخــرى لــدي أنــا‬\n      ‫‪ ......‬القاضــي املنتــدب باحملكمــة العامــة بخميــس مشــيط مبوجــب‬\n      ‫قــرار رئيــس مجلــس القضــاء األعلــى رقــم ( ‪ )22536‬يف ‪1433/12/29‬‬\n      ‫ه ـ واملكلــف بعمــل املكتــب القضائــي الرابــع مبوجــب خطــاب رئيــس‬\n      ‫هــذه احملكمــة رقــم (‪ ) 3433830‬يف ‪1434/1/5‬ه ـ حضــر الطرفــان ثم‬\n      ‫جــرى عــرض مــا جــاء يف شــهادة الشــاهد األول ‪ /‬علــى املدعــي وكالــة‬\n      ‫أجــاب مــا جــاء يف شــهادته ال أعلــم صحتــه وال أعــرف حــال الشــاهد‪ ،‬ثــم‬\n      ‫جــرى عــرض شــهادة الشــاهد الثانــي علــى املدعي وكالة أجاب شــهادته‬\n      ‫غيــر صحيحــة وأطلــب مواجهــة الشــاهد مــرة ثانيــة لســؤاله أمــا الشــاهد‬\n      ‫فــا أعرفــه‪ ،‬ومبــا أنــه كان موظــف يف الشــركة فرمبــا كان بينــه‬\n      ‫وبــن الشــركة مشــاكل ولذلــك شــهد ضدهــا‪ ،‬هــذه إجابتــي ويف‬\n      ‫جلســة أخــرى لــدي أنــا القاضــي باحملكمــة العامــة بخميــس مشــيط‬\n      ‫القائــم بعمــل املكتــب القضائــي الرابــع فيهــا حضــر ســعودي اجلنســية‬\n\n\n‫‪297‬‬\n\f‫ا عــن املدعــي‬ ‫مبوجــب بطاقــة الهويــة الوطنيــة رقــم ( ‪ ) ...‬بصفتــه وكيـ ً‬\n‫أصالــة عــن نفســه وبصفتــه شــريك يف شــركة مجموعــة ‪ ......‬الصناعيــة‬\n‫مبوجــب الوكالــة الصــادرة مــن كاتــب العــدل املكلــف يف الغرفــة‬\n‫التجاريــة الصناعيــة بجــدة رقــم ( ‪ ) ...‬وتاريــخ ‪1434/6/24‬ه ـ والــذي لــه‬\n‫فيهــا حــق املطالبــة وإقامــة الدعــاوي واملرافعــة واملدافعــة وســماع‬\n‫الدعــاوي والــرد عليهــا طلــب اليمــن ورده واالمتنــاع عنــه وحضــر حلضوره‬\n‫املدعــى عليــه ثــم مت تــاوة مــا مت رصــده فصادقــا عليــه واحضــر املدعــى‬\n‫عليــه الشــاهد مصــر اجلنســية باإلقامــة رقــم(‪ )...‬كمــا أحضــر الشــاهد‬\n‫الثانــي مصــري اجلنســية باإلقامــة رقــم (‪ )...‬وبســؤالهما عمــا لديهمــا مــن‬\n‫شــهادة شــهد األول قــال أشــهد بــاهلل العظيــم قــال كنــت أعمــل مندوبـ ًا‬\n‫يف الشــركة املدعيــة مــن عــام ‪1994‬م إلــى عــام ‪2004‬م وكان أخــر‬\n‫عقــد وقعنــا عليــه باســم شــركة مجموعــة ‪ ......‬الصناعيــة وكنــت‬\n‫مســئو ًال عــن جميــع العهــد التــي كانــت أســلمها واســتلمها ومســئوال عــن‬\n‫حتصيــل الديــون وليــس ملديــر الفــرع يف ذلــك إي مســؤولية يف حتصيــل‬\n‫الديــون يف جلســة أخــرى وفيهــا حضــر ســعودي اجلنســية مبوجــب الســجل‬\n‫ا عــن أصالــة عــن نفســه وبصفتــه مديــر‬  ‫املدنــي رقــم (‪ )...‬بصفتــه وكيـ ً‬\n‫الشــركة يف شــركة مجموعــة ‪ ......‬الصناعيــة وذلــك بصفتــه شــريكا‬\n‫يف الشــركة مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل املكلــف‬\n‫يف الغرفــة التجاريــة الصناعيــة بجــدة برقــم() وتاريــخ ‪1434/7/3‬ه ـ‬\n‫كمــا حضــر املدعــى عليــه وبســؤال املدعــي وكالــة عــن الشــهود ومــا‬\n‫جــاء يف شــاهدتهم قــال أمــا الشــهود فــا اعرفهــم وبعــد مراجعــة شــؤون‬\n‫املوظفــن تبــن أنهــم يعملــون يف مســتحضرات التجميــل وليــس يف مصنع‬\n‫اآليــس كــرمي والعصيــر ‪ ....‬وهــو مختلــف متامــا هــذه إجابتــي عــن الشــهود‬\n\n\n                                                                                   ‫‪298‬‬\n\f      ‫وبســؤاله عــن البينــة عــن أن الثالجــات ال حتتــاج إلــى صيانــة يف الفواتيــر‬\n      ‫التــي ذكــرت يف اجللســات الســابقة قــال أمــا الثالجــات فيــه حتتــاج إلــى‬\n      ‫صيانــة دوريــة ثــم جــرى ســؤال املدعــى عليــه هــل احضر مزكني للشــهود‬\n      ‫قــال نعــم فاحضــر ســوري اجلنســية مبوجــب اإلقامــة رقــم (‪ )......‬و‪......‬‬\n      ‫فلســطيني اجلنســية مبوجــب اإلقامــة رقــم (‪ )......‬وبســؤالهما عــن الشــهود‬\n      ‫قــاال نزكيهــم وهــم عــدول ثــم جــرى ســؤال املدعــي وكالــة هــل مزيــد‬\n      ‫بينــات قــال ليــس لــدي إال مــا جــاء يف أوراق املعاملــة وبســؤال املدعــى‬\n      ‫عليــه هــل لديــة مــا يريــد إضافتــه قــال اكتفــي مبــا جــاء يف الــوراق‬\n      ‫املعاملــة ‪.‬أ‪.‬ه ـ فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وملصادقــة‬\n      ‫الوكيــل الشــرعي علــى أن املدعــى عليــه هــو مديــر الفــرع وقــد عمــل مــا‬\n      ‫يقــارب عشــرين ســنة فيــده يــد أمــن ألنــه يتصــرف بــإذن مــن املالــك فــا‬\n      ‫يضمــن إال إذا تعــدى أو فــرط واألصــل بــراءة الذمــة حتــى يأتــي مــا ينقــل‬\n      ‫هــذا األصــل ولكــون جهــة التحقيــق قــد انتهــت مــن هــذه القضيــة‬\n      ‫وبنتيجــة ونــص احلاجــة منهــا كمــا جــاء علــى لفــه رقــم(‪ )95‬أو ًال ‪ /‬وجــود‬\n      ‫تناقــض يف تقريــر احملاســب القانونــي والــذي مت إرفاقــه مــن قبــل مصنــع‬\n      ‫‪ ......‬وذلــك ملــا جــاء يف أقــوال الوكيــل الشــرعي أن املنــدوب الهــارب هــو‬\n      ‫املســئول عــن تلــك املبالــغ بدايــة لكــن أهمــل يف حتصيلهــا بصفتــه مديــر‬\n      ‫للفــرع وبالتالــي هــو املســئول عنهــا كمــا تضمنــه التقريــر وكذلــك مــا‬\n      ‫جــاء يف أقــوال املدعــى عليــه أنــه مت حتصيــل أكثــر املبلــغ املوجــود‬\n      ‫بالتقريــر ويقــدر بحوالــي مائــة وســتة عشــر ألــف (‪ )116000‬ريــال مــن‬\n      ‫أصــل مائــة وواحــد وســبعون ألــف (‪ )171000‬ريــال وكذلــك العثــور‬\n      ‫علــى معظــم الثالجــات يف الســوق مــن عهــده املتهــم الهــارب ‪ ......‬وعددها‬\n      ‫(‪ )154‬ثالجــة مــن أصــل (‪ )170‬ثالجــة وهــذا مــا قــرره مديــر الفــرع‬\n\n\n‫‪299‬‬\n\f‫احلالــي ومحاســب الشــركة ومندوبهــا وجيــه وكذلــك وجــود الورقــة‬\n‫مكتوبــة بخــط املديــر احلالــي للفــرع علــى الورقــة اخلاصــة بــورش ‪......‬‬\n‫وهــي بتاريــخ متأخــر عــن تاريــخ إعــداد احملاســب القانونــي وكذلــك‬\n‫العقــد املرفــق واملســتند عليــه يف املــادة (‪ )13‬يخــص املنــدوب وليــس مدير‬\n‫الفــرع كمــا أن األوراق التــي مت إرفاقهــا بالتقريــر القانونــي بخصــوص‬\n‫هــذه الدعــوى هــي نفــس األوراق املوجــودة لدينــا مــن قبــل بخصــوص‬\n‫الدعــوى ضــد هــروب املنــدوب هنــدي اجلنســية‪ .‬ثاني ـاً‪ /‬عــدم توجيــه‬\n‫االتهــام للمدعــو ‪ ....../‬مبــا ينســب إليــه ســواء يف املبالــغ املاليــة أو‬\n‫الثالجــات أو التزويــر يف الفواتيــر رغــم إصــرار املدعــي بــأن هــو املســئول‬\n‫كونــه كان املديــر للفــرع وذلــك ملــا جــاء يف أقــوال الوكيــل الشــرعي‬\n‫أن هــذه الدعــوى تخــص املنــدوب الهــارب ‪ ......‬وأن تلــك الديــون يف ذمتــه‬\n‫وإلنــكار املدعــى عليــه ‪ ......‬أن كل مــا ورد غيــر صحيــح كمــا أنــه‬\n‫ليــس املســئول عمــا ورد جتــاه ذلــك املنــدوب الهــارب والــذي ســبق وأن مت‬\n‫اإلبــاغ عنــه رســمي ًا ولعــدم صحــة مــا اســتند عليــه املصنــع يف التقريــر‬\n‫بخصــوص املــادة (‪ )13‬ألنهــا تخــص املنــدوب الهــارب وكان مديــر للفــرع‬\n‫وكذلــك مــا ذكــره املدعــو للمحقــق داخــل مكتبــه بــأن الدعــوى ضــده‬\n‫غيــر صحيحــة وان الشــركة فقــط تريــد إذاللــه وإهانتــه ‪.‬أ‪.‬ه ـ ولكــون‬\n‫العقــد الــذي اســتدلوا بــه يف تقريــر احملاســب القانونــي الــذي قدمتــه‬\n‫الشــركة املدعيــة علــى لفــة رقــم (‪ )13‬هــو عقــد متأخــر عــن العقــود‬\n‫الــذي تســتدل بــه الشــركة علــى أن مديــر الفــرع متضامــن مــع املناديــب‬\n‫وجــاء يف هــذا العقــد املتأخــر باســم شــركة مجموعــة ‪ ......‬الفقــرة (‪)13‬‬\n‫ونصهــا يف العقــد‪ ( :‬منــه الطــرف الثانــي املنــدوب مســئول عــن جميــع‬\n‫املبيعــات اآلجلــة التــي تتــم عــن طريقــه ويتعهــد بتحصيلهــا وتســديدها‬\n\n\n                                                                                    ‫‪300‬‬\n\f      ‫ويف حالــة عــدم حتصيلهــا ألي ســبب كان يحــق للطــرف األول خصمهــا‬\n      ‫مــن راتبــه وحقوقــه وال يتــم إخــاء طرفــه إال بعــد ســداده)‪.‬أ‪.‬هـ ال حجــة‬\n      ‫للشــركة بعــدم توقيعهــا حيــث أنهــا قدمتــه حجــة لهــا يف الدعــوى‪.‬‬\n      ‫فيكــون ال حجــة لهــا علــى تضمــن مديــر الفــرع يف الديــون غير احملصلة‬\n      ‫وكــذا يف الثالجــات وأمــا الفواتيــر فــا بينــة لهــم علــى أنهــا غيــر‬\n      ‫صحيحــة بــل مــا جــاء يف تقريــر التحقيــق علــى لفــه (‪ )99‬أن قيمتهــا‬\n      ‫صحيحــة وجــاء فيهــا أنهــا مــن نفــس املؤسســة التــي تتعامــل املدعيــة معهــا‬\n      ‫كمــا يف الفواتيــر ولكــون املدعــى عليــه قــد أقــر بتســليم ثمــان ثالجــات‬\n      ‫وهــي لــدى التاجــر وهــي مســلمة لــه بعهــد وتواقيــع واملهمــة يف ذلــك عنــد‬\n      ‫الشــركة تنتهــي بتوقيــع العهــد وبتســليمه للشــركة وهــي مســؤولة بعــد‬\n      ‫ذلــك عــن املطالبــة بهــا ولكــون املدعــى عليــه قــد أحضــر البينــة املعدلــة‬\n      ‫شــرع ًا علــى أن املناديــب هــم املســئولون يف الشــركة عــن حتصيــل‬\n      ‫الديــون وعهدهــم وهــم مســئولون عنهــا وال مســؤولية ملديــر الفــرع وإمنــا‬\n      ‫مهمتــه اإلشــراف وتوزيــع املهــام لهــذا كلــه فقــد صرفــت النظــر عــن‬\n      ‫دعــوى املدعيــة وأفهمــت املدعــي وكالــة بــأن ليــس لــه إال ميــن املدعــى‬\n      ‫عليــه لنفــي مــا أدعــى بــه متــى طلبهــا وبــه حكمــت وبعرضــه علــى‬\n      ‫الطرفــن واملدعــى عليــه قــرر القناعــة وقــرر املدعــي وكالــة عــدم‬\n      ‫القناعــة وســيتقدم بالئحــة اعتراضيــة وأفهمتــه مبراجعــة احملكمــة يــوم‬\n      ‫الســبت ‪1434/7/8‬ه ـ الســتالم نســخة مــن احلكــم لتقــدمي الئحتــه‬\n      ‫االعتراضيــة خــال ثالثــن يــوم مــن تاريــخ صــدور الصــك يف حــال انتهــاء‬\n      ‫املــدة ولــم يتقــدم يكتســب القطعيــة‪ .‬وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n                                            ‫على نبينا محمد حرر يف ‪1434/7/8‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق ‪1434/10/18‬ه ـ‬\n\n\n‫‪301‬‬\n\f‫افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف مبنطقــة‬\n‫عســير برقــم ‪ 342052378‬وتاريــخ ‪1434/9/21‬ه ـ وبرفقهــا القــرار‬\n‫ذي الرقــم ‪ 34313612‬وتاريــخ ‪1434/9/7‬ه واملتضمــن‪ :‬احلمــد هلل‬\n‫وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة لتدقيــق القضايــا‬\n‫واجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة الــواردة‬\n‫مــن فضيلــة مســاعد رئيــس احملكمــة العامــة بخميــس مشــيط برقــم‬\n‫‪ 3213003‬وتاريــخ ‪1434/8/9‬ه ـ املرفــق بهــا الصــك الصــادر من فضيلة‬\n‫القاضــي باحملكمــة الشــيخ ‪ /‬برقــم ‪ 34261913‬وتاريــخ ‪1434/7/8‬ه‬\n‫اخلــاص بدعــوى ‪ /‬شــركة مجموعــة ‪ ......‬الصناعيــة ضــد ‪ /‬يف قضيــة (‬\n‫اختــاس) علــى الصفــة املوضحــة يف الصــك املتضمــن حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل فيــه وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم واهلل املوفــق‬\n‫صلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬قاضــي اســتئناف‬\n‫توقيعــه وختمــه وقاضــي اســتئناف توقيعــه وختمــه ورئيــس الدائــرة‬\n‫توقيعــه وختمــه‪ .‬وللبيــان جــرى إحلاقــه وبــاهلل التوفيــق وصلــى اهلل علــى‬\n                                         ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                   ‫‪302‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":281,"source_page_end":302,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c45bd263d42ce0e42d1c11161cc261aad68983580639ef6f4f9b95cb6fac9f1d","normalized_text_hash":"20faf028cc3722f75a6d967a25f710fb789e4ccfa9216747075356ff488efc7c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p281-34261913"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"124043f2-6d2b-5115-abc8-8289d9cc87a2","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد م س روق -س رقة ذهب ومبالغ مالية من منزل -بينة غير موص لة -رد دع وى -للمدعي مين املدعى عليهما متى","document_number":"34185130","case_number":"34122821","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة باملدينة املنورة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/10","year":"1434","subject":"مطالبة برد م س روق -س رقة ذهب ومبالغ مالية من منزل -بينة غير موص لة -رد دع وى -للمدعي مين املدعى عليهما متى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫تاريخه‪1434/4/10 :‬هـ‬\n                 ‫ُ‬                ‫َر ْق ُم َّ‬\n                    ‫الص ِّك‪34185130 :‬‬\n                   ‫َر ْق ُم الدعوى‪34122821 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34239334‬تاريخه‪1434/6/13:‬هـ‬\n\n\n‫مطالبــة بــرد م ـسـ ــروق ‪ -‬سـ ــرقة ذهــب ومبالــغ ماليــة مــن منــزل ‪ -‬بينــة‬\n‫غيــر موصـ ــلة ‪ -‬رد دعـ ــوى ‪ -‬للمدعــي ميــن املدعــى عليهمــا متــى‬\n                                                              ‫طلبهــا ‪.‬‬\n\n\n\n‫مــا ذكــره القاضــي مــن املبــادئ العامــة وقواعــد العدالــة يف تســبيب‬\n                                                                 ‫حكمــه ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي بــأن املدعــى عليهمــا اشــتركا يف ســرقة ذهــب ومبالــغ‬\n‫ماليــة مــن منزلــه ؛ وطلــب إلزامهمــا بإعــادة قيمــة املســروقات ‪ -‬أنكــر‬\n‫املدعــى عليهمــا دعــوى املدعــي جتاههمــا جملــة وتفصيــا ‪ -‬املدعــي قــدم‬\n‫بينــات غيــر موصلــة ولــم يقبــل ميــن املدعــى عليهمــا علــى نفــي دعــواه‪-‬‬\n‫مــن املقــرر شــرعا أن البينــة علــى املدعــي واليمــن علــى املدعــى عليــه‬\n‫‪ -‬قضــت احملكمــة بصــرف النظــر عــن دعــوى املدعــي وأفهمتــه أن لــه‬\n‫ميــن املدعــى عليهمــا متــى أراد ‪ -‬قنــع املدعــى عليهمــا باحلكــم وعــارض‬\n‫عليــه املدعــي‪ -‬قــررت محكمــة االســتئناف باألكثريــة املوافقــة علــى‬\n                                                                      ‫احلكــم ‪.‬‬\n\n\n\n                                                                                    ‫‪248‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة العامــة‬\n      ‫باملدينــة املنــورة وبنــاء علــى املعاملــة الــواردة مــن مركــز شــرطة قبــاء‬\n      ‫برقــم ‪ 192/13/6‬وتاريــخ‪1434/3/15 :‬ه ـ واحملالــة لنــا مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة باملدينــة املنــورة برقــم ‪ 34122821‬وتاريــخ‬\n      ‫‪1434/03/15‬ه ـ املقيــدة باحملكمــة برقــم ‪ 34648118‬وتاريــخ‬\n      ‫‪1434/03/15‬ه ـ ففــي ي ــوم االثنــن افتتحــت اجللســة وفيهــا حضــر ‪....‬‬\n      ‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وحضــر حلضــوره املدعــى‬\n      ‫عليهــم ‪ ....‬باكســتاني اجلنســية مبوجــب اإلقامــة رقــم ‪ ....‬بنجالديشــي‬\n      ‫اجلنســية مبوجــب اإلقامــة رقــم و‪ ........‬باكســتاني اجلنســية مبوجــب‬\n      ‫اإلقامــة رقــم ‪ 2257460176‬ورفعــت اجللســة لطلــب مترجــم للمدعــى‬\n      ‫عليهــم ويف جلســة أخــرى حضــر الطرفــان املــدون هويتهمــا ســابق ًا‬\n      ‫ا إن املدعــى عليهــم احلاضــرون هــذا املجلــس قــد‬     ‫فادعــى األول قائ ـ ً‬\n      ‫قامــوا بســرقة محتويــات شــقتي بنيــة متلكهــا وقــد اتفــق األول والثانــي‬\n      ‫علــى االســتيالء علــى محتويــات شــقتي وتوجــد مظاهــر خارجيــة ظاهــر‬\n      ‫احلالــة تــدل علــى قيامهــم بســرقة احملتويــات وحيــث قامــا باعتــداء علــى‬\n      ‫ا غيــر مشــروع وهــي كالتالــي ( ‪ /1‬عقــد ذهــب‬    ‫حيــازة ممتلكاتــي نقـ ً‬\n      ‫مطعــم باللؤلــؤ ‪ /2‬اســورة ذهــب جنيهــات عيــار واحــد وعشــرين ‪ /3‬خــامت‬ ‫ّ‬\n      ‫ذهــب ابيــض ‪ /4‬طقــم مكــون مــن حلــق واســورة لؤلــؤ ‪ /5‬عــدد خمــس‬\n      ‫خــوامت لؤلــؤ ‪ /6‬عــدد أربعــون خــامت ذهــب ‪ /7‬طقــم املــاس مكــون مــن‬\n      ‫اســورة وحلــق ‪ /8‬عــدد اثنــان خــامت ‪ /9‬طقــم ذهــب فصــوص بنــي كامــل‬\n      ‫مكــون مــن حلــق واســورة وخــامت ‪ /10‬طقــم ذهــب فصــوص بنــي كامــل‬\n\n‫‪249‬‬\n\f‫مكــون مــن عقــد وحلــق وخــامت ‪ /11‬شــرش ذهــب ‪ /12‬كــف ذهــب‬\n‫وخــوامت عددهــا خمســة ‪ /13‬طقــم فيــروز أزرق مــع حلــق وتعليقــة ‪/14‬‬\n‫طقــم زوقــوم احمــر تعليقــة وخــامت وحلــق ‪ /15‬طقــم ذهــب فصــوص‬\n‫اخضــر حلــق وخــامت واســورة ‪ /16‬طقــم ذهــب اصفــر مــع اســورة تعليقــة‬\n‫وخــامت وحلــق ‪ /17‬مصحــف ذهــب مــع سلســلة ‪ /18‬عــدد عشــرة مــن‬\n‫السالســل الذهبيــة ‪ /19‬تعليقــة مــن الذهــب علــى شــكل ريــال ‪/20‬‬\n‫عــدد ثمانيــة عشــر بناجــر ‪ /21‬عــدد ثمانيــة عشــر مــن األســاور املختلطــة‬\n‫‪ /22‬عــدد عشــر حلــق مختلــف األشــكال واألنــواع ‪ /23‬طقــم علــى‬\n‫شــكل مقــاة مكــون مــن حلــق واســورة وخــامت وعقــد ‪ /24‬ذهــب‬\n‫ابيــض طقمــن ‪ /25‬اســورة مــع عــدد اثنــن خــوامت ذهــب ابيــض ‪/26‬‬\n‫ســاعة يــد ذهــب ‪ /27‬ســاعة لؤلــؤ وســاعة أميجــا ذهــب عيــار ســبع‬\n‫وعشــرين اصفــر ‪ /28‬مبالــغ ماليــة وقــدره خمســة وســتون ألــف ريــال‬\n‫‪ /29‬كيــس مــن النقــود لعمــات ورقيــة غيــر معلومــة املقــدار ) حيــث‬\n‫اتفقــا ســوي ًا علــى االســتيالء علــى ممتلكاتــي دون وجــه حــق أطلــب‬\n‫إلزامهــم بإعــادة املســروقات ومجموعهــا مائتــن وخمســون ألــف ريــال‬\n‫هــذه دعــواي وبســؤال املدعــي عــن املتهــم الثالــث بنجالديشــي اجلنســية‬\n‫باإلقامــة رقــم فقــال هــذا ال أتهمــه بشــيء ودعــواي علــى ‪...../2 ..../1‬‬\n‫‪/3‬وبســؤال املدعــى عليهــم عــن دعــوى املدعــي أجــاب كل واحــد منهمــا‬\n‫بلغــة عربيــة مفهومــة مــا ذكــره املدعــي غيــر صحيــح فلــم أقــم بالســرقة‬\n‫علم ـ ًا أننــي لــم أدخــل بيتــه إال مــرة عندمــا كان معنــا هــذه إجابتــي ثــم‬\n‫جــرى ســؤال املدعــي هــل لديــك بينــة فقــال نعــم ويف هــذه اجللســة حضــر‬\n‫‪ /‬مصــري اجلنســية مبوجــب اإلقامــة رقــم وعمــره ســتة وخمســون عامــا‬\n‫ا أشــهد هلل‬  ‫وعملــه دكتــور وليــس لــه عالقــة بالطرفــن فشــهد قائ ـ ً‬\n\n\n                                                                                      ‫‪250‬‬\n\f      ‫ا املوافــق ‪1433/1/18‬هـ‬       ‫تعالــى أننــي شــاهدت الســاعة الثانيــة عشــر ليـ ً‬\n      ‫وهــو خــارج مــن بــاب العمــارة وقــال لــي ال تقفــل البــاب هــذا مــا لــدي مــن‬\n      ‫شــهادة وبعــرض الشــاهد وشــهادته علــى املدعــى عليــه قــال مــا ذكــره‬\n      ‫الشــاهد غيــر صحيــح وأمــا الشــاهد فــا أعلــم عنــه شــيئا ويف جلســة‬\n      ‫أخــرى حضــر املدعــي هويتــه ســابق ًا وحضــر حلضــوره املدعــى عليهمــا‬\n      ‫املــدون هويتهمــا ســابق ًا وأحضــر املدعــي ‪ /‬مصــري اجلنســية مبوجــب‬\n      ‫اإلقامــة رقــم وعملــه محاســب وعمــره ســبع وأربعــون عام ـ ًا وعالقتــه‬\n      ‫ا أشــهد هلل تعالــى أن‬   ‫بالطرفــن أجنبــي عــن املتداعيــن فشــهد قائ ـ ً‬\n      ‫املدعــى عليــه عمــل يف دورة امليــاه اخلــاص بشــقتي يــوم االثنــن الســاعة‬\n      ‫الثانيــة إال ربــع حتــى الســاعة الثانيــة والنصــف وبعدهــا غــادر املــكان‬\n      ‫ولــم يرجــع إال يــوم اخلميــس هــذا مــا لــدي مــن شــهادة فجــرى عــرض‬\n      ‫الشــاهد وشــهادته عليــه بواســطة مترجــم احملكمــة ‪ .....‬باكســتاني‬\n      ‫اجلنســية مبوجــب اإلقامــة رقــم علــى املدعــى عليــه أجــاب بقولــه مــا‬\n      ‫ذكــره الشــاهد صحيــح ولكنــي تركــت العمــل ألجــل أن يحضــر‬\n      ‫معلــم الســيراميك ليصلــح الســيراميك ثــم أقــوم بتركيــب الســباكة‬\n      ‫هــذا مــا لــدي وأمــا شــهادته فــا تــدل علــى شــيء ممــا ذكــر وجــرى‬\n      ‫تزكيــة الشــاهدين مــن قبــل مصــري اجلنســية مبوجــب اإلقامــة رقــم‬\n      ‫مصــري اجلنســية مبوجــب اإلقامــة رقــم فجــرى ســؤال املدعــي هــل لديــك‬\n      ‫مزيــد بينــة فقــال ليــس لــدي ســوى مــا قدمــت هــذا مــا لــدي فجــرى إفهــام‬\n      ‫املدعــي أن لــه ميــن املدعــى عليهمــا فقــال أرفــض ميــن املدعــى عليهمــا وال‬\n      ‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومــا قــرره الطرفــان‬ ‫أريدهــا فبنـ ً‬\n      ‫وألنــكار املدعــى عليهمــا مــا جــاء يف دعــوى املدعــي ولعــدم البينــة‬\n      ‫املوصلــة مــن املدعــي ولرفضــه ميــن املدعــى عليهمــا وألن اليمــن حــق‬\n\n\n‫‪251‬‬\n\f‫للمدعــي لذلــك كلــه فقــد حكمــت بصــرف النظــر عــن دعــوى املدعــي‬\n‫وأخليــت ســبيل املدعــى عليهمــا وأفهمــت املدعــي أن لــه ميــن املدعــى‬\n‫عليهمــا متــى مــا أراد وبعــرض احلكــم علــى املدعــي واملدعــى عليهما قرر‬\n‫املدعــي عــدم القناعــة باحلكــم وقــرر املدعــى عليهمــا قناعتهمــا باحلكــم‬\n‫فجــرى إفهــام املدعــي باحلضــور غــد ًا الســتالم نســخة مــن احلكــم لتقــدمي‬\n‫اعتراضــه عليــه خــال ثالثــن يومـ ًا مــن تاريــخ االســتالم وإذا لــم يتقــدم‬\n‫خاللهــا فإنــه يســقط حقــه يف االســتئناف ويكتســب احلكــم القطعيــة‬\n‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n                                                     ‫حــرر يف ‪1434/04/09‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد والصــاة والســام علــى مــن ال نبــي بعــده ففــي‬\n‫هــذا اليــوم االثنــن املوافــق ‪1434/7/10‬ه ـ افتتحــت اجللســة وقــد‬\n‫عــادت املعاملــة مــن محكمــة االســتئناف بخطابهــم رقــم ‪34648118‬‬\n‫وتاريــخ ‪1434/06/26‬ه ـ مرفقــا بــه القــرار رقــم ‪ 34239334‬وتاريــخ‬\n‫‪1434/06/13‬هـ الصادر من قضاة الدائرة اجلزائية السابعة مبحكمة‬\n‫االســتئناف مبنطقــة مكــة املكرمــة املتضمــن املوافقــة علــى احلكــم‬\n‫باألكثريــة لــذا جــرى إحلــاق ذلــك وبــاهلل التوفيــق وصلــى اهلل وســلم علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/07/10‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                    ‫‪252‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":248,"source_page_end":252,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"7c910d6463779316e1594176b368702b195be6c1cd9bc1313d81052c61dae427","normalized_text_hash":"00989326f16ca158aa40ce937192ab65964f2c9aa6e9e5acd93bdf9d8964c999","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p248-34185130"},{"id":"36c01daf-32a6-5e33-a4d9-e41ec8cb50be","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة مبلغ مالي عن طريق احتيال مصريف -على اليد ما أخذت حتى تؤديه -اإلقرار باستالم املبالغ -احلكم بإلزام املدعى عليه بدفع املبلغ املدعى به -إفهام بالرجوع على من غره .","document_number":"34227500","case_number":"34148388","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بحائل","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/5/29","year":"1434","subject":"رد مسروق -سرقة مبلغ مالي عن طريق احتيال مصريف -على اليد ما أخذت حتى تؤديه -اإلقرار باستالم املبالغ -احلكم بإلزام املدعى عليه بدفع املبلغ املدعى به -إفهام بالرجوع على من غره .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/5/29 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34227500 :‬‬\n                         ‫َر ْق ُم الدعوى‪34148388 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34280282‬تاريخه‪1434/7/26:‬هـ‬\n\n\n      ‫رد مســروق ‪ -‬ســرقة مبلــغ مالــي عــن طريــق احتيــال مصــريف‪ -‬علــى‬\n      ‫اليــد مــا أخــذت حتــى تؤديــه ‪ -‬اإلقــرار باســتالم املبالــغ ‪ -‬احلكــم بإلــزام‬\n      ‫املدعــى عليــه بدفــع املبلــغ املدعــى بــه ‪ -‬إفهــام بالرجــوع علــى مــن غــره ‪.‬‬\n\n\n\n\n         ‫قول النبي صلى اهلل عليه وسلم‪(:‬على اليد ما أخذت حتى تؤديه) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي بأنــه مت التحايــل عليــه وذلــك باتصــال شــخص يدعــي أنــه‬\n      ‫موظــف يف املصــرف الــذي بــه حســابه املصــريف وطلــب منــه معلومــات‬\n      ‫عــن حســابه ثــم أجريــت ســحوبات وحتويــات ماليــة مــن حســابه إلــى‬\n      ‫عــدة حســابات؛ وقــد تبــن مــن خــال التحقيقــات أن أحــد التحويــات‬\n      ‫كان لصالــح املدعــى عليــه ‪ ،‬ولــذا فقــد طلــب إلزامــه بإعــادة املبلــغ ‪-‬‬\n      ‫أقــر املدعــى عليــه باســتالم املبلــغ املذكــور يف الدعــوى نقــدا بعــد أن‬\n      ‫مت حتويلــه إلــى حســاب أحــد معارفــه‪ ،‬ودفــع بــأن شــخصا آخــر طلــب‬\n      ‫منــه رقــم حســاب ليحــول عليــه مبلغــا يخصــه ‪ ،‬وأنــه قــام بتســليم املبلــغ‬\n      ‫لشــخص مــن طــرف الشــخص املذكــور نقــدا بعــد اســتالمه لــه مــن‬\n      ‫املصــرف‪ ،‬ولــم يكــن يعلــم بتحايلــه علــى املدعــي لســرقة مبلــغ مالــي‬\n\n‫‪253‬‬\n\f‫مــن حســابه ‪ -‬املدعــى عليــه أقــر باســتالم املبلــغ املذكــور يف الدعــوى‬\n‫نقــدا ‪ -‬قضــت احملكمــة بإلــزام املدعــى عليــه بدفــع املبلــغ املدعــى بــه‬\n‫للمدعــي وأفهمتــه بــأن لــه الرجــوع علــى مــن غــره ‪ -‬قنــع املدعــي باحلكــم‬\n‫وعــارض عليــه املدعــى عليــه ‪ -‬قــررت محكمــة االســتئناف املصادقــة‬\n                                                                   ‫علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة العامــة‬\n‫بحائــل وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بحائــل املســاعد برقــم ‪ 34148388‬وتاريــخ ‪ 1434/04/01‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 34719066‬وتاريــخ ‪ 1434/03/22‬ه ـ ففــي‬\n‫يــوم األربعــاء املوافــق‪ 1434/05/29‬ه ـ فتحــت اجللســة الســاعة ‪10 : 00‬‬\n‫وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم وادعــى‬\n‫علــى احلاضــر معــه مينــي اجلنســية مبوجــب اإلقامــة الصــادرة مــن جــدة‬\n‫برقــم قائــا يف دعــواه عليــه أنــه قبــل ســنة تقريب ـ ًا اتصــل علــي شــخص‬\n‫يدعــي أنــه موظــف يف بنــك ‪ ...‬وذكــر أن اســمه‪ ...‬موظف يف قســم التميز‬\n‫بالبنــك وقــال لــي إن حســابي موقــف ويحتــاج الــى تنشــيط وطلــب منــي‬\n‫بعــض املعلومــات مــن أجــل تنشــيط احلســاب فأعطيتــه بعــض املعلومــات‬\n‫وبعــد ثالثــة أيــام مــن مكاملتــه حصلــت ســحوبات مــن حســابي علــى عــدة‬\n‫مــرات ولــم اكتشــف ذلــك إال بعــد مضــي مــدة عندمــا أردت أن اســحب‬\n‫عــن طريــق الصرافــة فدخلــت البطاقــة فيهــا ولــم تخــرج فراجعــت‬\n‫املصــرف يف حينــه فاتضــح أنــه مت ســحب مبالــغ مــن حســابي مجموعهــا‬\n‫مائتــان وخمســون ألــف ريــال ثــم طلبــت كشــف حســاب فظهــر فيــه‬\n\n                                                                                     ‫‪254‬‬\n\f      ‫االختــاس عبــارة عــن حتويــات ماليــة بأســماء أشــخاص آخريــن ال‬\n      ‫أعرفهــم فتقدمــت إلــى اجلهــات األمنيــة وبعــد البحــث والتحقيــق فيــه‬\n      ‫اتضــح أن هــذه املبالــغ وزعــت علــى أربــع حســابات مــن ضمنهــا حســاب‬\n      ‫شــخص اســمه مينــي اجلنســية يســكن يف مدينــة جــدة حيــث دخــل يف‬\n      ‫حســابه مبلــغ ســتني ألــف ريــال وعنــد التحقيــق معــه احضــر شــخصني‬\n      ‫األول مينــي اجلنســية والثانــي هــذا احلاضــر ‪ ...‬واقــروا عنــد التحقيــق أن‬\n      ‫ليــس لــه دخــل بهــذا املبلــغ احملــول مــن حســابي إلــى حســابه وقــد صــدر‬\n      ‫علــى هــذا احلاضــر وكذلــك زميلــه ‪ ....‬حكــم يف احلــق العــام بالســجن‬\n      ‫ملــدة عشــرة أشــهر واجللــد أربعمائــة جلــدة مفرقــة علــى دفعــات مبوجــب‬\n      ‫القــرار الصــادر مــن احملكمــة اجلزائيــة بحائــل برقــم ‪ 33303242‬يف‬\n      ‫‪1433/06/17‬هـ ـ املصــدق مــن محكمــة االســتئناف بالقصيــم برقــم‬\n      ‫‪ 33478025‬يف ‪ 1433/12/26‬هـ ـ وقــد تنازلــت عــن املدعــو بعدمــا دفــع‬\n      ‫لــي مبلــغ ثالثــن ألــف ريــال التــي ســحبها مــن حســابي إلــى حســاب لــذا‬\n      ‫اطلــب ســؤال املدعــى عليــه والزامــه بتســديد املبلــغ املتبقي وقــدره ثالثون‬\n      ‫ألــف ريــال حــاال هــذه دعــواي وبســؤال املدعــى عليــه اجــاب قائــا مــا‬\n      ‫ذكــره املدعــي ال أعلــم عنــه شــيئا وحقيقــة األمــر أنــه قبــل ســنة وعشــرة‬\n      ‫أشــهر بالضبــط اتصــل بــي شــخص وقــال لــي أنــه ابــن خالتــي واســمه‬\n      ‫‪ .......‬وأنــا ال أعرفــه وقــال لــي أنــه قــال كان يشــتغل يف شــركة ‪......‬‬\n      ‫وأن اجلــوازات أمســكته ولــه حقــوق عنــد شــركة ‪ ......‬وطلــب منــي رقــم‬\n      ‫حســاب يحــول لــه مســتحقاته لــدى الشــركة وقــال لــي ســوف يتصــل‬\n      ‫عليــك مديــر العمــال شــخص مينــي اســمه ‪ ........‬تعطيــه رقــم احلســاب‬\n      ‫ويحــول ذلــك مســتحقاتي ثــم اتصــل علــي شــخص يدعــي أن اســمه‬\n      ‫وأنــه مديــر عمــال شــركة ‪ ......‬فأعطيتــه حســاب فقــام بتحويــل مبلــغ‬\n\n\n‫‪255‬‬\n\f‫ســتني الــف ريــال فلــم علمــت بــأن املبلــغ كبيــر اتصلــت علــى ولــد خالتــي‬\n‫فأخبرنــي أنهــا مســتحقات ثمانيــة أشــخاص وطلــب أن اقــوم بتحويلهــا‬\n‫إلــى اليمــن فقــام بســحب نصفهــا مبلــغ ثالثــن ألــف ريــال واعطانــي‬\n‫اياهــا ثــم ذهبــت إلــى احلــواالت بجــده فقالــوا لــي إن املبلــغ كثيــر وطلبــوا‬\n‫ورقــة مــن الكفيــل فاتصلــت علــى مديــر العمــل ‪ .......‬فقــال لــي خلهــا‬\n‫عنــدك أنــا أرســل شــخص اآلن اســمه ‪ .......‬يســتلمها منــك وخــذ منهــا‬\n‫مبلــغ خمســمائة ريــال اشــتر بهــا بطاقــة موبايلــي وارســلها إلــى ولــد خالــك‬\n‫وبعــد ســاعة ونصــف جــاء (‪ )......‬واســتلم مبلــع تســعة وعشــرين ألفــا‬\n‫وخمســمائة ريــال ثــم طلــب منــي أن اقــوم بتحويل املبلغ املتبقي يف حســاب‬\n‫وقــدره ثالثــون ألــف ريــال إلــى حســاب شــخص اســمه ســوري اجلنســية‬\n‫فقــام بتحويلهــا حســب طلبــي وبعــد ســبعة أشــهر قامــت اجلهــات األمنيــة‬\n‫بالقبــض علــى بســبب هــذه املبالــغ فقمــت بتبرئتــه مــن هــذه املشــكلة‬\n‫ألنــه ليــس لــه دخــل فيهــا واتضــح أن هــذه املبالــغ اختالســات مــن عصابــة‬\n‫فقمــت باالتصــال علــى فلــم يــرد علــى واتصلــت علــى اليمــن فأتضــح أننــي‬\n‫غــرر بــي مــن أشــخاص ال أعرفهــم واســتغلوني يف ذلــك فقمــت بتســليم‬\n‫نفســي إلــى اجلهــات الرســمية واخبرتهــم بكامــل القصــة وأنــه غــرر بــي‬\n‫مــن هــؤالء االشــخاص وأنــا لــم اســرق ولــم اشــارك يف هــذه االختالســات‬\n‫كمــا اتضــح أن الــذي دفــع مبلــغ ثالثــن ألــف ريــال للمدعــي وتنــازل عنــه‬\n‫املدعــي لــه صلــة بهــذه القضيــة ولــذا فليــس للمدعــي عنــدي أي شــيء‬\n‫هــذه اجابتــي ثــم جــرى عــرض الصلــح علــى الطرفــن فقــرر املدعــى عليــه‬\n‫قائــا ال مانــع لــدي مــن دفــع املبلــغ بشــرط ضمــان عــدم ترحيلــي مــن‬\n‫الســعودية ألنــه صــدر علــي أمــر ترحيــل فأفهمنــاه أن اجــراءات الترحيــل‬\n‫ليســت مــن اختصــاص احملكمــة فقــرر قائــا أننــي مســتعد بدفــع املبلــغ‬\n\n\n                                                                                        ‫‪256‬‬\n\f      ‫بشــرط عــدم الترحيــل وأمــا غيــر ذلــك فــا أوافــق عليهــا فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واالجابــة واالطــاع علــى املعاملــة ومــن ضمنهــا‬\n      ‫احلكــم يف احلــق العــام املصــدق مــن االســتئناف وحيــث أقــر املدعــى عليــه‬\n      ‫بــأن هــذه االختالســات عبــارة عــن حتويــات ماليــه متــت بالتنســيق معــه‬\n      ‫وأنــه هــو املســؤول عنهــا وأن صاحــب احلســاب احملــول باســمه وهــو ليــس‬\n      ‫لــه دخــل بهــذه القضيــة وأنــه هــو و قــد غــرر بــه مــن أشــخاص يدعــون أنهم‬\n      ‫اقــارب لــه واتضــح أنهــم ســراق وحيــث أقــر املدعــى عليــه بأنــه قــد اســتلم‬\n      ‫الثالثــن الــف ريــال احملولــة بحســاب ولقــول النبــي صلــى اهلل عليــه وســلم‬\n      ‫« علــى اليــد مــا أخــذت حتــى تؤديــه» وحيــث اقتصــر املدعــي يف دعــواه‬\n      ‫ضــد املدعــى عليــه( ‪ ).........‬حســب اقــراره املرفــق لذلــك كلــه فقــد ثبــت‬\n      ‫لــدي صحــة دعــوى املدعــي ضــد املدعــى عليــه وحكمــت بالــزام املدعــى‬\n      ‫عليــه بدفــع املبلــغ املدعــى بــه وقــدره ثالثــون ألــف ريــال حــاال وبذلــك‬\n      ‫حكمــت وافهمــت املدعــى عليــه بــأن لــه الرجــوع علــى مــن غــره وبعــرض‬\n      ‫احلكــم علــى الطرفــن قــرر املدعــي قناعتــه أمــا املدعــى عليــه فقــرر‬\n      ‫عــدم القناعــة وطلــب تقــدمي الئحــة اعتراضيــة فأجبتــه لطلبــه وســوف يتــم‬\n      ‫تســليمه نســخة مــن احلكــم بعــد التوقيــع وافهمتــه بــأن مــدة االعتــراض‬\n      ‫وقدرهــا ثالثــون يومــا ســوف تبــدأ مــن هــذا اليــوم ‪143/5/29‬هـ ـ واذا‬\n      ‫مضــت هــذه املــدة ولــم يتقــدم بالئحتــه فتســقط معارضتــه فهــم ذلــك‬\n      ‫وعليــه جــرى التوقيــع‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                          ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/05/29‬ه ـ‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n      ‫األولــى لتدقيــق القضايــا احلقوقيــة مبحكمــة االســتئناف مبنطقــة حائــل‬\n      ‫علــى املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بحائــل برقــم‬\n\n\n‫‪257‬‬\n\f‫‪ 34719066‬وتاريــخ ‪1434/7/10‬ه ـ واملقيــدة لدينــا برقــم ‪34719066‬‬\n‫بتاريــخ ‪1434/7/15‬ه ـ املرفــق بهــا الصــك رقــم ‪ 34227500‬يف‬\n‫‪1434/05/29‬ه ـ الصــادر مــن فضيلــة القاضي‪......./‬اخلــاص بدعــوى‬\n‫‪ ........‬ضــد ‪ ........‬مينــي اجلنســية بشــأن مبلــغ مالــي علــى الصفــة املوضحــة‬\n‫يف الصــك وبدراســة الصــك وصــورة ضبطــه والالئحــة االعتراضيــة‬\n‫وأوراق املعاملــة ‪ :‬فقــد جــرت املصادقــة علــى مــا حكــم بــه فضيلتــه واهلل‬\n      ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪258‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":253,"source_page_end":258,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6ee1b179d6db14fa439e1e174c0fd341641905e1a1583bf42878cb451e6d9dfe","normalized_text_hash":"0409b1549227e04a9a47357e36407e801b7144eac355331ae890f1d3eee54738","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p253-34227500"},{"id":"0a51b273-bd26-58e4-83c1-a5e9b3c251df","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة مبلغ مالي من سيارة -عجز عن إقامة البينة -اليمن على نفي الدعوى حق للمدعي وله عدم قبولها -احلكم برد دعوى -استحقاق املدعي ليمن املدعى عليه على نفي الدعوى","document_number":"34234369","case_number":"34234420","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بعنيزة بن","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/6/7","year":"1434","subject":"رد مسروق -سرقة مبلغ مالي من سيارة -عجز عن إقامة البينة -اليمن على نفي الدعوى حق للمدعي وله عدم قبولها -احلكم برد دعوى -استحقاق املدعي ليمن املدعى عليه على نفي الدعوى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/6/7 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34234369 :‬‬\n                         ‫َر ْق ُم الدعوى‪34234420 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34259203‬تاريخه‪1434/7/4:‬هـ‬\n\n\n      ‫رد مســروق ‪ -‬ســرقة مبلــغ مالــي مــن ســيارة ‪ -‬عجــز عــن إقامــة البينــة‬\n      ‫‪ -‬اليمــن علــى نفــي الدعــوى حــق للمدعــي ولــه عــدم قبولهــا ‪ -‬احلكــم‬\n      ‫بــرد دعــوى ‪ -‬اســتحقاق املدعــي ليمــن املدعــى عليــه علــى نفــي الدعــوى‬\n                                                                   ‫متــى طلبهــا ‪.‬‬\n\n\n\n\n      ‫قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن علــى‬\n                                                                       ‫مــن أنكــر) ‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل املدعــي علــى احلاضــر معــه بأنــه قــام بســرقة مبلــغ مالــي‬\n      ‫مــن ســيارة موكلــه َّإبــان عملــه كســائق خــاص لديــه‪ ،‬وطلــب إلزامــه‬\n      ‫بإعــادة املبلــغ املســروق إلــى موكلــه ‪ -‬أنكــر املدعــى عليــه مــا جــاء يف‬\n      ‫دعــوى املدعــي جتاهــه ‪ -‬املدعــي لــم يقــدم بينــة تثبــت دعــواه ولــم يقبــل‬\n      ‫ميــن املدعــى عليــه علــى نفيهــا ‪ -‬قضــت احملكمــة بــرد دعــوى املدعــي‬\n      ‫وأخلــت ســبيل املدعــى عليــه منهــا وأفهمــت املدعــي أن لــه ميــن املدعــى‬\n      ‫عليــه علــى نفــي دعــواه متــى مــا طلــب ذلــك ‪ -‬قنــع املدعــى عليــه باحلكــم‬\n      ‫وعــارض عليــه املدعــي‪ -‬قــررت محكمــة االســتئناف املصادقــة علــى‬\n                                                                             ‫احلكــم ‪.‬‬\n‫‪259‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا د‪ .... .‬القاضــي يف احملكمــة العامــة‬\n‫بعنيــزة بنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيس احملكمــة العامة‬\n‫بعنيــزة برقــم ‪ 34234420‬وتاريــخ ‪ 1434/05/21‬ه ـ املقيــدة باحملكمــة‬\n‫برقــم ‪ 341239421‬وتاريــخ ‪ 1434/05/21‬ه ـ ففــي يــوم االثنــن املوافــق‬\n‫‪ 1434/06/05‬هـ افتتحت اجللسة الساعة ‪ 10 : 30‬وفيها حضر سعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي رقــم وكيــا عــن بالوكالــة الصــادرة‬\n‫مــن كتابــة العــدل الثانيــة بحائــل برقــم ‪ 3463265‬يف‪1434/5/19‬ه ـ‬\n‫وحضــر حلضــوره املدعــى عليــه ‪ ...‬هنــدي اجلنســية ال يحمــل إثبــات هويــة‬\n‫واملعــرف بــه مــن قبــل وكيــل املدعــي ‪ ،‬وادعــى املدعــي وكالــة قائــا يف‬\n‫دعــواه عليــه ‪ :‬أن هــذا احلاضــر كان يعمــل ســائق خــاص لــدى موكلــي‬\n‫والــدي ويف شــهر ذي احلجــة مــن عــام ‪1433‬ه ـ قــام بفتــح بــاب ســيارة‬\n‫موكلــي والــدي اخلاصــة بــه مــن أمــام بيــت موكلــي الواقــع يف مدينــة ‪...‬‬\n‫يف حــي ‪ ...‬ولــم تكــن األبــواب مقفلــة وقتهــا وقــام بســرقة مبلــغ وقــدره‬\n‫ســبعة آالف وأربعمائــة ريـ‪ 7400‬ــال وأخــذ جــواز ســفره اخلــاص بــه ثــم‬\n‫هــرب أطلــب إلزامــه بإعــادة املبلــغ املســروق ملوكلــي وقــدره ســبعة آالف‬\n‫وأربعمائــة ريـ‪ 7400‬ــال هــذه دعــواي وبعــرض الدعــوى علــى املدعــى عليه‬\n‫أجــاب قائــا بــأن مــا ذكــره املدعــي وكالــة كلــه غيــر صحيــح فلــم‬\n‫اشــتغل لــدى موكلــه ســائق خــاص و الصحيــح أننــي عملــت لــدى املدعــي‬\n‫أصالــة بالغنــم بالصليبيــة وكنــت اتفقــت معــه يف الهنــد علــى العمــل‬\n‫لديــه يف بقالــة وكان يســيء معاملتــي ويضربنــي وال أعــرف بيتــه الــذي‬\n‫يف ‪ ...‬ولــم أقــم بفتــح بــاب الســيارة ولــم أســرق املبلــغ املذكــور ولــم آخــذ‬\n\n                                                                                        ‫‪260‬‬\n\f      ‫جــواز ســفري هكــذا أجــاب ‪ ،‬وبعــرض إجابتــه علــى املدعــي وكالــة‬\n      ‫قــال ‪ :‬الصحيــح مــا ذكــرت ولــدي بينــة ‪ ،‬وأطلــب إمهالــي إلحضارهــا ‪،‬‬\n      ‫ويف جلســة أخــرى حضــر املدعــي وكالــة وحضــر املدعــى عليــه أصالــة‬\n      ‫هنــدي اجلنســية مبوجــب رقــم احلــدود املذكــور يف خطاب مدير الشــرطة‬\n      ‫رقــم ‪31/3509/1116‬وبســؤال املدعــى وكالــة هــل أحضــر البينــة التــي‬\n      ‫وعــد بإحضارهــا يف اجللســة املاضيــة فقــال لــم أحضــر البينة وال أســتطيع‬\n      ‫إحضارهــا فقــد بحثــت ولــم أجــد فأفهمتــه بــأن لــه ميــن املدعــى عليــه‬\n      ‫فقــال ال أطلــب ميــن املدعــى عليــه وال أقبلهــا وبســؤال املدعــى عليــه هــل‬\n      ‫يحلــف علــى نفــي الدعــوى فقــال نعــم واســتعد ببذلهــا فبنــاء علــى مــا‬\n      ‫تقــدم مــن الدعــوى واإلجابــة وألن املدعــى عليــه أنكــر الســرقة واملدعــي‬\n      ‫لــم يثبتهــا ببينــة وقــرر بأنــه ال يســتطيع إحضارهــا وملــا ورد يف احلديــث‬\n      ‫مــن أن البينــة علــى املدعــي واليمــن علــى مــن أنكــر فقــد رددت دعــوى‬\n      ‫املدعــي وأخليــت ســبيل املدعــى عليــه وافهمــت املدعــي بــأن لــه ميــن‬\n      ‫املدعــي متــى طلبهــا وبــه حكمــت وبعــرض احلكــم علــى الطرفــن قــرر‬\n      ‫املدعــي عــدم القناعــة وطلــب رفعــه حملكمــة االســتئناف بــدون الئحــة‬\n      ‫اعتراضيــة واملدعــى عليــه القناعــة فأمــرت برفعــه حملكمــة االســتئناف‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                ‫وســلم ‪ .‬حــرر يف ‪1434/06/07‬هــ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا‪ ......‬القاضــي يف احملكمــة العامــة‬\n      ‫بعنيــزة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫العامــة بعنيــزة برقــم ‪ 34234420‬وتاريــخ ‪1434/05/21‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 341239421‬وتاريــخ ‪1434/05/21‬ه ـ ففــي‬\n      ‫يــوم االثنــن املوافق‪1434/07/17‬ه ـ افتتحــت اجللســة وفيهــا وردتنــا‬\n\n\n‫‪261‬‬\n\f‫املعاملــة مــن محكمــة االســتئناف بالقصيــم برقــم ‪ 34149550‬وتاريــخ‬\n‫‪1434/7/10‬ه ـ واخلاصــة بدعــوى … ضــد ‪(.........‬هنــدي اجلنســية)‬\n‫وبرفقهــا القــرار رقــم ‪ 34259203‬وتاريــخ ‪1434/7/4‬ه ـ وباالطــاع‬\n‫عليــه وجــد يتضمــن وبدراســة الصــك وصــورة ضبطــه وأوراق املعاملــة‬\n‫لــم يظهــر مــا يوجــب املالحظــة علــى مــا حكــم بــه فضيلتــه ‪ .‬وبــاهلل‬\n‫التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر‬\n                                                        ‫يف ‪1434/07/17‬هــ‪.‬‬\n\n\n\n\n                                                                                  ‫‪262‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":259,"source_page_end":262,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"f253df3ff59fd2bc939f57b34becbae368a4447adb0db53b8fbddc450db43ea6","normalized_text_hash":"236a66d571ab396ebc94a500eafbc80e1ebeabcfd05eb86779a333242df8c50b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p259-34234369"},{"id":"61d74784-e1a3-5871-8e1d-ecd116f48e8b","document_type":"judgment","category":"judicial","subcategory":"general","title":"مطالبة برد مسروق -عدم إقامة الدعوى من املدعي العام لعدم وجود دليل -سرقة ذهب ومبالغ مالية من منزل -بينة غير موصلة -اليمن على نفي الدعوى -رد الدعوى .","document_number":"34293396","case_number":"34248172","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/8/9","year":"1434","subject":"مطالبة برد مسروق -عدم إقامة الدعوى من املدعي العام لعدم وجود دليل -سرقة ذهب ومبالغ مالية من منزل -بينة غير موصلة -اليمن على نفي الدعوى -رد الدعوى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/8/9 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34293396 :‬‬\n                         ‫َر ْق ُم الدعوى‪34248172 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 35122832‬تاريخه‪1435/1/22:‬هـ‬\n\n\n      ‫مطالبــة بــرد مســروق‪ -‬عــدم إقامــة الدعــوى مــن املدعــي العــام لعــدم‬\n      ‫وجــود دليــل ‪ -‬ســرقة ذهــب ومبالــغ ماليــة مــن منــزل ‪ -‬بينــة غيــر‬\n                     ‫موصلــة ‪ -‬اليمــن علــى نفــي الدعــوى ‪ -‬رد الدعــوى ‪.‬‬\n\n\n\n\n      ‫‪( -1‬أن النبــي صلــى اهلل عليــه وســلم قضــى أن اليمــن علــى املدعــى‬\n                                                         ‫عليــه)‪ .‬رواه البخــاري ‪.‬‬\n      ‫‪ -2‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن‬\n                                          ‫علــى املدعــى عليــه)‪ .‬رواه الترمــذي ‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل املدعــي بــأن املدعــى عليــه املمثــل بوكيلــه احلاضــر قــام‬\n      ‫بتحريــض أشــخاص علــى ســرقة أطقــم ذهــب ومبلــغ مالــي مــن منــزل‬\n      ‫موكلــه ؛ وطلــب إلزامــه بإعــادة املســروقات إلــى موكلــه مــع تعويــض‬\n      ‫مــادي واحلكــم عليــه بعقوبــة تعزيريــة ‪ -‬أنكــر وكيــل املدعــى عليــه‬\n      ‫الدعــوى ودفــع بــأن موكلــه موظــف يف الشــركة التــي متلــك املنــزل‬\n      ‫وقــد طلبــت منــه الكتابــة عليــه مبــا يــدل علــى أنــه معــروض للبيــع وال‬\n      ‫رابــط بــن ذلــك ومــا جــاء يف الدعــوى‪ -‬قــدم املدعــي بينــات غيــر موصلــة‬\n      ‫واملدعــى عليــه أصالــة حلــف اليمــن علــى نفــي دعــواه طبــق مــا طلــب‬\n\n‫‪263‬‬\n\f‫منــه‪ -‬مــن املقــرر شــرعا أن البينــة علــى املدعــي واليمــن علــى املدعــى‬\n‫عليــه ‪ -‬لذلــك قضــت احملكمــة بــرد دعــوى املدعــي يف مواجهــة املدعــى‬\n‫عليــه لعــدم ثبــوت صحتهــا ‪ -‬قنــع املدعــى عليــه وعــارض املدعــي علــى‬\n        ‫احلكــم‪ -‬قــررت محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظة جدة وبناء على املعاملة احملالة لنا من فضيلة رئيس احملكمة‬\n‫العامــة مبحافظــة جــدة برقــم ‪ 34248172‬وتاريــخ ‪1434/05/28‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم ‪ 341263432‬وتاريــخ ‪1434/05/25‬ه ـ ففــي‬\n‫يــوم الثالثــاء املوافق‪1434/07/25‬ه ـ افتتحــت اجللســة الســاعة ‪:00‬‬\n‫‪ 01‬وفيهــا حضــر ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬‬\n‫بصفتــه وكيــا عــن‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪...‬‬\n‫بصفتــه وكيــل مبوجــب وكالــة رقــم ‪ 57281‬وتاريــخ ‪1433/6/29‬ه ـ‬\n‫الصــادرة مــن كتابــة العــدل الثانيــة شــمال محافظــة جــدة واملــوكل بهــا‬\n‫مــن املدعــي ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ...‬مبوجــب‬\n‫الوكالــة رقــم ‪ 34558009‬وتاريــخ ‪1434/5/4‬هـ‪،‬وادعــى علــى احلاضــر‬\n‫معــه ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ...‬بصفته وكيال‬\n‫عــن ‪ ...‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم بالوكالــة رقــم‬\n‫‪ 34920445‬وتاريــخ ‪1434/7/15‬ه ـ قائــا‪ :‬تتمثــل دعــواي يف قيــام‬\n‫املدعــى عليــه بتحريــض مجموعــة مــن األشــخاص يف غيابــي باالعتــداء‬\n‫علــى منــزل موكلــي واقتحامــه وســرقة ثالثــة أطقــم ذهــب ومبلــغ مالــي‬\n‫قيمتــه خمســة عشــر ألــف ريــال وقــام بكتابــة عبــارات عليــه تفيــد أنــه‬\n\n\n                                                                                 ‫‪264‬‬\n\f      ‫املالــك ويريــد بيعــه ونصهــا (للبيــع مــن املالــك مباشــرة لالستفســار ‪)....‬‬\n      ‫حيــث أن موكلــي كان يف إجــازة رســمية مــن العمــل تنتهــي بتاريــخ ‪19‬‬\n      ‫شعبان ‪1433‬هـ لعالج مشكلة خلع بالفك ‪ ،‬وعند عودته للمنزل وجد‬\n      ‫األبــواب مفتحــة وغرفــة النــوم مبعثــرة وعلــى الفــور توجــه إلــى مركــز‬\n      ‫شــرطة الســامر لتحريــر محضــر بذلــك وأثنــاء حتريــر احملضــر مبركــز‬\n      ‫شــرطة الســامر قــام النقيــب باالتصــال علــى رقــم اجلــوال املوضــح بعاليــه‬\n      ‫ورد عليــه املدعــى عليــه وقــد حتــدث النقيــب إلــى املدعــى عليــه باجلــوال‬\n      ‫يدعــي بأنــه مشــتر يريــد شــراء الفيــا ‪ ،‬فقــال لــه املدعــى عليــه نعــم أنــا‬\n      ‫املالــك ومســتعد إلنهــاء البيــع واإلفــراغ خــال يومــن ‪ ،‬وذكــر أنــه فعــل‬\n      ‫ذلــك بتوجيهــات شــركة ‪ ..........‬كــون موكلــي مســتأجر منهــا الفيــا‬\n      ‫بعقــد إيجــار مــع الوعــد بالتمليــك ولتأخــر موكلــي عــن دفــع القســط‬\n      ‫الشــهري للفيــا قــام املدعــى عليــه مبباشــرة االعتــداء ‪ ،‬مــع أن العقــد‬\n      ‫بــن موكلــي وبــن الشــركة ال يجيــز لهــا فســخ العقــد إال يف حالــة‬\n      ‫تأخــره عــن دفــع ثالثــة أقســاط متتاليــة ‪ ،‬ولــكل مــا تقــدم ألتمــس مــن‬\n      ‫فضيلتكــم أوال‪ -:‬احلكــم بإدخــال شــركة ‪ .......‬طرف ـ ًا يف الدعــوى‬\n      ‫الرتباطهــا باملوضــوع ارتباط ـ ًا ال يقبــل التجزئــة‪ .‬ثانيــا‪ :‬احلكــم بإلــزام‬\n      ‫املدعــى عليــه بــرد املســروقات مــن ذهــب ومبالــغ ماليــة ‪ .‬ثالثــا‪ -:‬احلكــم‬\n      ‫بتعزيــر املدعــى عليــه مبــا يجــب شــرع ًا نتيجــة العتدائــه علــى حرمــة‬\n      ‫املنــازل ‪ ،‬مــع احلكــم لــي بالتعويــض املــادي نتيجــة كل هــذه األفعــال‬\n      ‫احملرمــة شــرع ًا ‪ .‬هــذه دعــواي‪ ،‬وبعــرض ذلــك علــى املدعــى عليــه‬\n      ‫وكالــة قــدم مذكــرة هــذا نصهــا‪ -1 :‬إن االدعــاء الــذي ذكــره املدعــي‬\n      ‫عــن فعــل التحريــض واقتحــام املنــزل بقصــد الســرقة غيــر صحيــح جملــة‬\n      ‫ا ‪-2.‬موكلــي يعمــل موظــف يف الشــركة التــي متتلــك العقــار‬            ‫وتفصي ـ ً‬\n      ‫املســتأجر مــن املدعــي وقــد طلبــت الشــركة مــن موكلــي عــرض العقــار‬\n\n‫‪265‬‬\n\f‫للبيــع ‪ ،‬حيــث أنهــا متتلــك العقــار ويحــق لهــا التصــرف فيــه تصــرف املالك‬\n‫مبلكــه ‪ ،‬وعلــى إثــر ذلــك قــام موكلــي بتوجيــه فريــق العمــل امليدانــي‬\n‫اخلــاص بالشــركة بكتابــة عبــارة (العقــار للبيــع مــن املالــك مباشــرة‬\n‫‪ ،)....‬وال نــرى أن كتابــة هــذه العبــارة علــى الســور اخلارجــي للمنــزل‬\n‫بغــرض عرضــه للبيــع لهــا رابطــة ســببيه يف واقعــة الســرقة التــي يدعــي‬\n‫بهــا املدعــي‪ -3.‬ســبق وأن تقــدم وكيــل املدعــي ببــاغ لقســم شــرطة‬\n‫الســامر اتهــم فيهــا موكلــي بالســرقة ‪ ،‬حيــث مت اســتدعاء موكلــي‬\n‫وأخــذ أقوالــه أمــام الضابــط احملقــق ومت كذلــك أخــذ بصماتــه‪ ،‬ووفقـ ًا‬\n‫إلفــادة قســم الشــرطة مت إحالــة امللــف إلــى هيئــة التحقيــق واالدعــاء‬\n‫العــام‪ ،‬وأعيــد منهــا لعــدم وجــود أدلــة تثبــت عالقــة موكلــي بالســرقة‪،‬‬\n‫وطلبــت الهيئــة يف مثــل هــذه احلــاالت والتــي ال يوجــد فيهــا لــدى املدعــي‬\n‫أي بينــة ضــد املدعــى عليــه إحالــة امللــف للمحكمــة للنظــر فيهــا باحلــق‬\n‫اخلــاص‪ ،‬وقــد مت إحالــة امللــف للمحكمــة العامــة بالرقــم ‪41/2433‬‬\n‫وتاريــخ ‪1434/05/22‬ه ـ ‪-4.‬طلــب املدعــي إيقــاع العقوبــة ضــد موكلــي‬\n‫ال يقــوم علــى ســند صحيــح بالنظــام ‪ ،‬حيــث أن املدعــي نصــب نفســه‬\n‫ممثـ ًـا عــن االدعــاء العــام‪ .‬وممــا تقــدم فــإن موكلــي يطالــب احلكــم‬\n‫بصــرف النظــر عــن الدعــوى‪ .‬وبعــرض ذلــك علــى املدعــي وكالــة قــال‪:‬‬\n‫أطلــب اإلمهــال إلحضــار بينتــي علــى صحــة الدعــوى‪ .‬ثــم رفعــت اجللســة‬\n‫لذلــك ‪.‬ويف يــوم الثالثــاء املوافــق ‪1434/08/09‬ه ـ افتتحــت اجللســة‬\n‫الســاعة ‪ 02 :30‬وفيهــا حضــر املدعــي وكالــة واملدعــى عليــه وكالــة‬\n‫‪ ،......‬كمــا حضــر املدعــي ‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪ ، ....‬وحضــر املدعــى عليــه ‪ ...‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم‪ ...‬وبســؤال املدعــي وكالــة عمــا طلــب اإلمهــال مــن أجلــه‬\n‫أحضــر للشــهادة وأدائهــا ‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n\n                                                                                    ‫‪266‬‬\n\f      ‫رقــم ‪ .....‬وهــو مــن مواليــد ‪1392‬ه ـ ويعمــل يف حــرس احلــدود ‪ ،‬ويســكن‬\n      ‫يف حــي ‪ ....‬مبحافظــة جــدة ‪ ،‬وليــس بينــه وبــن طــريف الدعــوى قرابــة ‪،‬‬\n      ‫وشــهد قائــا‪ :‬أشــهد هلل تعالــى بأنــه قبــل حوالــي عــام وجــدت شــخصني‬\n      ‫يقومــان بطباعــة عبــارة علــى جــدار منزلــي فأوقفتهمــا ثــم اتضــح أنهمــا‬\n      ‫يريــدان منــزل املدعــي‪ ،‬ثــم انتقــا إلــى منــزل املدعــي وطبعــا عبــارة‬\n      ‫(للبيــع مــن املالــك مباشــرة لالستفســار) ‪ .‬هكــذا شــهد ‪ .‬وبعــرض ذلــك‬\n      ‫علــى املدعــى عليــه وكالــة قــال‪ :‬إن شــهادة الشــاهد غيــر موصلــة إلــى‬\n      ‫مــا يدعــي بــه املدعــي ‪ .‬وبعــرض ذلــك علــى املدعــي وكالــة قــال‪ :‬شــهادة‬\n      ‫الشــاهد تــدل علــى أن املدعــي هــو مــن وجــه الشــخصني بعمــل مــا قامــا‬\n      ‫بعملــه ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه وكالــة قــال‪ :‬شــهادة الشــاهد‬\n      ‫ال تــدل علــى ذلــك إطالقــا ‪ .‬وبســؤال املدعــي علــى دعــواه قــال‪ :‬ليــس‬\n      ‫لــدي بينــة ‪ ،‬وأطلــب ميــن املدعــى عليــه علــى إنــكار مــا ورد يف الدعــوى‬\n      ‫‪ ،‬وأقبــل ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه اســتعد لذلــك ‪ ،‬ثــم حلــف‬\n      ‫قائــا‪ :‬واهلل العظيــم الــذي ال إلــه إال هــو أن مــا ذكــره املدعــي مــن‬\n      ‫قيامــي بتحريــض مجموعــة مــن األشــخاص يف غيــاب املدعــي لالعتــداء‬\n      ‫علــى منزلــه واقتحامــه وســرقة ثالثــة أطقــم ذهــب ومبلــغ مالــي قيمتــه‬\n      ‫خمســة عشــر ألــف ريــال وقيامــي بكتابــة عبــارات عليــه تفيــد أننــي‬\n      ‫املالــك وأننــي أريــد بيعــه ونصهــا (للبيــع مــن املالــك مباشــرة لالستفســار)‬\n      ‫فغيــر صحيــح‪ ،‬وأمــا مــا يخــص االتصــال مــن قبــل النقيــب وأننــي أجبــت‬\n      ‫عليــه فــا أعلــم عــن صحتــه‪ ،‬حيــث أننــي أعمــل لــدى شــركة‪،.......‬‬\n      ‫وهــذا اإلجــراء متبــع لديهــا ‪ ،‬ويتصــل علــي أكثــر مــن شــخص ألكثــر‬\n      ‫مــن عقــار ‪ ،‬وال أســتطيع حتديــد االتصــال محــل الدعــوى هــل هــو مــن‬\n      ‫بينهــا أم ال ‪ .‬هكــذا حلــف ‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n      ‫‪ ،‬وبنــاء علــى إنــكار املدعــى عليــه لدعــوى املدعــي ‪ ،‬وبنــاء علــى أن‬\n\n‫‪267‬‬\n\f‫املدعــي لــم يقــم البينــة علــى صحــة مــا ادعــاه يف مواجهــة املدعــى عليــه ‪،‬‬\n‫وجملــة مــا يف األمــر قيــام أشــخاص مــن قبــل الشــركة بعمــل مــا ذكــره‬\n‫املدعــي علــى جــدار املنــزل محــل الدعــوى ‪ ،‬وبنــاء علــى طلــب املدعــي‬\n‫ميــن املدعــى عليــه علــى إنــكار دعــواه ‪ ،‬وبنــاء علــى ميــن املدعــى عليــه‬\n‫علــى إنــكار دعــوى املدعــي ‪ ،‬وبنــاء علــى أن تصــرف املوظــف ومــن يف‬\n‫حكمــه يقــع ضمــن مســؤوليات مــن اجلهــة التابعــة لــه ‪ ،‬مــا لــم يتعــدى أو‬\n‫يتجاوز الصالحيات السلطات املمنوحة له ‪ ،‬وحيث أن تلك التصرفات‬\n‫تتوجــه الدعــوى فيهــا ابتــداء علــى الشــركة التــي يتبعهــا ذلــك املوظــف ‪،‬‬\n‫وحلديــث (أن النبــي صلــى اهلل عليــه وســلم قضــى أن اليمــن علــى املدعــى‬\n‫عليــه) رواه البخــاري ‪ ،‬وحلديــث (البينــة علــى املدعــي واليمــن علــى‬\n‫املدعــى عليــه) رواه الترمــذي ‪ ،‬قــال العمــل عنــد أهــل العلــم مــن أصحــاب‬\n‫النبــي صلــى اهلل عليــه وســلم وغيرهــم أن البينــة علــى املدعــي واليمــن‬\n‫علــى املدعــى عليــه ‪ ،‬لذلــك كلــه ‪ ،‬فقــد حكمــت بــرد دعــوى املدعــي‬\n‫يف مواجهــة املدعــى عليــه لعــدم ثبــوت صحتهــا ‪ .‬وبــه قنــع املدعــى عليــه ‪،‬‬\n‫وقــرر املدعــي االعتــراض ‪ ،‬وجــرى تســليمه نســخة مــن احلكــم وإفهامــه‬\n‫بــأن لــه احلــق يف االعتــراض عليــه خــال ثالثــن يومــا ‪ ،‬وإال ســقط حقــه‬\n‫يف االعتــراض ‪ ،‬واكتســب احلكــم القطعيــة ‪ .‬وأقفلــت اجللســة الســاعة‬\n‫‪ . 03 :00‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                  ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/08/09‬ه ـ ‪.‬‬\n\n\n\n‫•صــدق احلكــم مــن محكمــة االســتئناف برقــم ‪ 35122832‬وتاريــخ‬\n                                                ‫‪1435/1/22‬هـ‪.‬‬\n\n\n\n                                                                                      ‫‪268‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":263,"source_page_end":268,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b4a95efa5139fd67a9b48f069323ca297f4bf810c8ab6e0b96e53ae700c2f474","normalized_text_hash":"4cd8847346576d0ba18ecaa2490ebe09f777418449b1551852ec5ba6b7de67e7","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p263-34293396"},{"id":"e0e467d3-83a8-5b08-a7b3-112edfb1e9b3","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مسروق -سرقة مبلغ مالي عن طريق احتيال مصريف -دفع املدعى عليه انه ليس املستفيد الفعلي -ثبوت استالم املبلغ بإقرار املدعى عليه -احلكم بإلزام املدعى عليه بدفع املبلغ املدعى به - إفهام املدعى عليه بالرجوع على من غره .","document_number":"33443865","case_number":"150210726","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/11/1","year":"1434","subject":"رد مسروق -سرقة مبلغ مالي عن طريق احتيال مصريف -دفع املدعى عليه انه ليس املستفيد الفعلي -ثبوت استالم املبلغ بإقرار املدعى عليه -احلكم بإلزام املدعى عليه بدفع املبلغ املدعى به - إفهام املدعى عليه بالرجوع على من غره .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/11/1 :‬هـ‬\n                       ‫ُ‬                 ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33443865 :‬‬\n                         ‫َر ْق ُم الدعوى‪150210726 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 349355‬تاريخه‪1434/1/12:‬هـ‬\n\n\n      ‫رد مســروق ‪ -‬ســرقة مبلــغ مالــي عــن طريــق احتيــال مصــريف ‪ -‬دفــع‬\n      ‫املدعــى عليــه انــه ليــس املســتفيد الفعلــي ‪ -‬ثبــوت اســتالم املبلــغ بإقــرار‬\n      ‫املدعــى عليــه ‪ -‬احلكــم بإلــزام املدعــى عليــه بدفــع املبلــغ املدعــى بــه ‪-‬‬\n                                     ‫إفهــام املدعــى عليــه بالرجــوع علــى مــن غــره ‪.‬‬\n\n\n\n\n      ‫‪( -1‬أن النبــي صلــى اهلل عليــه وســلم قضــى أن اليمــن علــى املدعــى‬\n                                                         ‫عليــه)‪ .‬رواه البخــاري ‪.‬‬\n      ‫‪ -2‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬البينــة علــى املدعــي واليمــن‬\n                                          ‫علــى املدعــى عليــه) رواه الترمــذي ‪.‬‬\n      ‫‪ -3‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬علــى اليــد مــا أخــذت حتــى‬\n                                                           ‫تؤديــه) رواه األربعــة ‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل املصــرف املدعــي بــأن املدعــى عليــه قــام بالتحايــل علــى‬\n      ‫موكلــه وذلــك بتقــدمي تفويــض مــزور يخولــه إجــراء التحويــات املاليــة‬\n      ‫مــن حســاب أحــد العمــاء لديــه ‪ ،‬ثــم قــام بتحويــل مبلــغ مالــي من حســاب‬\n      ‫العميــل املذكــور إلــى حســابه وقــام بســحبه مــن املصــرف نقــدا‪ ،‬وبعــد‬\n      ‫ذلــك اعتــرض العميــل علــى ســحب املبلــغ املذكــور مــن حســابه فاســتعاد‬\n\n‫‪269‬‬\n\f‫املصــرف مــن حســاب املدعــى عليــه نصــف ذلــك املبلــغ لصالــح العميــل‬\n‫املذكــور؛ ولــذا فقــد طلــب إلزامــه بإعــادة النصــف اآلخــر مــن ذلــك‬\n‫املبلــغ ‪ -‬أقــر املدعــى عليــه باســتالم املبلــغ املذكــور يف الدعــوى نقــدا‬\n‫بعــد أن مت حتويلــه إلــى حســابه‪ ،‬ودفــع بــأن شــخصا آخــر طلــب منــه‬\n‫املوافقــة علــى حتويــل املبلــغ إلــى حســابه فوافــق علــى ذلــك‪ ،‬وأنــه قــام‬\n‫بتســليم املبلــغ للشــخص املذكــور نقــدا بعــد اســتالمه لــه مــن املصــرف‪،‬‬\n‫ولــم يكــن يعلــم بتحايلــه علــى املدعــي لســرقة مبلــغ مالــي مــن حســاب‬\n‫أحــد عمالئــه ‪ -‬املدعــى عليــه أقــر باســتالم املبلــغ املذكــور يف الدعــوى‬\n‫نقــدا ‪ -‬قضــت احملكمــة بإلــزام املدعــى عليــه بتســليم املدعــي أصالــة‬\n‫املبلــغ املدعــى بــه وأفهمتــه بــأن لــه الرجــوع علــى مــن غــره متــى مــا ثبــت‬\n‫ذلــك ‪ -‬قنــع املدعــي باحلكــم وعــارض عليــه املدعــى عليــه ‪ -‬قــررت‬\n                              ‫محكمــة االســتئناف املوافقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 150210726‬وتاريــخ‬\n‫‪1430/08/04‬ه ـ املقيــدة باحملكمــة برقــم ‪ 3061885‬وتاريــخ‬\n‫‪1430/08/03‬ه ـ ففــي يــوم الســبت املوافق‪1433/05/08‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 08 :40‬وفيهــا حضــر ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم بصفتــه وكيــا عــن‪ ...‬ســعودي مبوجــب ســجل مدنــي رقــم‬\n‫بصفتــه رئيــس مجلــس إدارة البنــك ‪ .........‬وبوكالتــه عــن كل مــن ‪....‬‬\n‫ســجل مدنــي رقــم‪ ...‬و‪ ......‬ســجل مدنــي رقــم ‪ ....‬و‪ ....‬ســجل مدنــي رقــم ‪...‬‬\n\n                                                                                         ‫‪270‬‬\n\f      ‫و‪ ......‬ســجل مدنــي رقــم ‪ ....‬و‪ ......‬ســجل مدنــي رقــم ‪ ...‬و‪ ......‬ســجل مدنــي‬\n      ‫رقــم ‪ .......‬و‪ ...‬ســجل مدنــي رقــم‪ ...‬و‪ .......‬ســجل مدنــي رقــم‪ ...‬بالوكالــة‬\n      ‫رقــم ‪ 21719‬والوكالــة رقــم ‪ 21725‬الصادرتــن مــن هــذه اإلدارة يف‬\n      ‫‪1431/06/23‬ه ـ جلــد ‪ 3001‬وبصفتهــم أعضــاء مجلــس إدارة البنــك‬\n      ‫‪ .........‬شــركة مســاهمه ســعودية بالســجل التجــاري رقــم ‪ ......‬يف‬\n      ‫‪1376/12/27‬ه ـ ســجل جــدة والصــادر بــه املرســوم امللكــي رقــم م‪19/‬‬\n      ‫يف ‪1417/11/23‬هـ وقرار مجلس الوزراء رقم ‪ 186‬يف ‪1417/11/22‬هـ‬\n      ‫واملصــدق نظامــه األساســي مــن اإلدارة العامــة للشــركات بــوزارة‬\n      ‫التجــارة برقــم ‪ 2405/205/222‬يف ‪1422/06/24‬ه ـ واملتضمن النظام‬\n      ‫األساســي تعيــن األعضــاء يف اجلمعيــة العموميــة يف املــادة ‪ 16‬واملعينــن‬\n      ‫مبوجــب محضــر انعقــاد اجلمعيــة العامــة يف ‪1430/04/03‬ه ـ و اجلمعيــة‬\n      ‫العامــة احلاديــة عشــر يف ‪1431/04/15‬ه ـ ومبوجــب خطــاب مديــر عــام‬\n      ‫وزارة التجــارة و الصناعــة بجــدة برقــم ‪ 17167‬يف‪1431 / 05 / 20‬ه ـ‬\n      ‫وبعــد تعريفــه مــن‪ ...... :‬ســعودي ســجل مدنــي ‪ ...‬و‪ ......‬ســعودي ســجل‬\n      ‫مدنــي‪ .....‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بجنــوب‬\n      ‫جــدة برقــم ‪ 31391‬وتاريــخ ‪1431/9/20‬ه ـ جلــد ‪ 3097‬وادعــى علــى‬\n      ‫احلاضــر معــه ‪......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪....‬‬\n      ‫بصفتــه وكيــا لــ‪ ......‬فلســطيني اجلنســية مبوجــب اإلقامــة رقــم ‪....‬‬\n      ‫مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة شــمال محافظــة‬\n      ‫جــدة برقــم ‪ 35561‬وتاريــخ ‪1433/4/19‬ه ـ جلــد ‪ 11639‬قائــا‪ :‬لقــد‬\n      ‫قــام املدعــى عليــه بتحويــل مبلــغ وقــدره ‪ 300‬ألــف ريــال مــن حســاب ‪...‬‬\n      ‫لــدى البنــك ‪ ...‬رقــم إلــى حســابه رقــم لــدى البنــك ‪ ...‬مبوجــب تفويــض‬\n      ‫مــزور صــادر عــن املصنــع ‪ ،...‬وقــد تقــدم املصنــع ‪ ...‬بشــكوى لــدى البنك‬\n\n\n‫‪271‬‬\n\f‫بتاريــخ ‪2008/7/2‬م يعتــرض فيهــا علــى حتويــل املبلــغ املذكــور حلســاب‬\n‫شــخص غيــر معــروف لديهــم‪ ،‬ومــن خــال البحــث تبــن أن التحويــل مت‬\n‫مــن خــال املدعــى عليــه مبوجــب التفويــض املــزور وعليــه ختــم ومصــدق‬\n‫مــن الغرفــة التجاريــة‪ ،‬وعلــى الفــور مت مخاطبــة شــرطة محافظــة جــدة‬\n‫قســم مكافحــة التزييــف والتزويــر بتاريــخ ‪2009/1/26‬م وتزويدهــم‬\n‫بنمــوذج التفويــض املمنــوح للمدعــى عليــه مــن قبــل الشــركة ومنــوذج‬\n‫طلــب احلوالــة محــل النــزاع‪ ،‬وقــد صــدر التقريــر الفنــي لألدلــة اجلنائيــة‬\n‫بتاريــخ ‪2009/2/2‬م واملتضمــن أن التوقيــع املنســوب لصاحــب املصنــع‬\n‫مــزور‪ ،‬وقــد قــام البنــك ‪ ...‬بإعــادة مبلــغ وقــدره ‪ 150‬ألــف ريــال حلســاب‬\n‫املصنــع‪ ،‬وأطلــب احلكــم بإلــزام املدعــى عليــه بدفــع مبلــغ وقــدره ‪150‬‬\n‫ألــف ريــال ملوكلــي‪ .‬هــذه دعــواي‪ .‬وبعــرض ذلــك علــى املدعــى عليــه‬\n‫وكالــة قــال‪ :‬أطلــب اإلمهــال للــرد‪ .‬وبســؤال املدعــى عليــه وكالــة هــل‬\n‫اســتلم موكلــك مبلــغ ‪ 300‬ألــف ريــال محــل الدعــوى قــال‪ :‬نعــم‪ ،‬لقــد مت‬\n‫حتويــل هــذا املبلــغ حلســاب موكلــي‪ ،‬وتفاصيلــه أحضرهــا اجللســة‬\n‫القادمة‪ .‬ثم رفعت اجللسة لذلك‪ .‬ويف يوم الثالثاء املوافق‪1433/06/03‬هـ‬\n‫افتتحــت اجللســة الســاعة ‪ 01 :16‬وفيهــا حضــر ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم بصفتــه وكيــا عــن ســعودي مبوجــب ســجل مدنــي‬\n‫رقــم بصفتــه رئيــس مجلــس إدارة البنــك ‪ ...‬وبوكالتــه عــن كل مــن ‪..../‬‬\n‫ســجل مدنــي رقــم‪ ....‬و‪ ....‬ســجل مدنــي رقــم‪ ....‬و‪ ....‬ســجل مدنــي رقــم‪.....‬‬\n‫و‪ .....‬ســجل مدنــي رقــم‪ ...‬و‪ ....‬ســجل مدنــي رقــم ‪....‬و‪....‬ســجل مدنــي‬\n‫رقــم‪ .....‬و ‪ ...‬ســجل مدنــي رقــم‪ .......‬و‪ ....‬ســجل مدنــي رقــم‪ .....‬بالوكالــة‬\n‫رقــم ‪ 21719‬والوكالــة رقــم ‪ 21725‬الصادرتــن مــن هــذه اإلدارة يف ‪23‬‬\n‫‪1431 / 06 /‬ه ـ جلــد ‪ 3001‬وبصفتهــم أعضــاء مجلــس إدارة البنــك ‪...‬‬\n\n\n                                                                                      ‫‪272‬‬\n\f      ‫التجــاري شــركة مســاهمه ســعودية بالســجل التجــاري رقــم ‪ /‬يف‪/ 27‬‬\n      ‫‪1376 / 12‬ه ـ ســجل جــدة والصــادر بــه املرســوم امللكــي رقــم م ‪ 19 /‬يف‬\n      ‫‪1417 / 11 / 23‬ه ـ وقــرار مجلــس الــوزراء رقــم ‪ 186‬يف ‪/ 11 / 22‬‬\n      ‫‪1417‬ه ـ واملصــدق نظامــه األساســي مــن اإلدارة العامــة للشــركات‬\n      ‫بــوزارة التجــارة برقــم ‪ 2405 / 205 / 222‬يف ‪1422 / 06 / 24‬ه ـ‬\n      ‫واملتضمــن النظــام األساســي تعيــن األعضــاء يف اجلمعيــة العموميــة يف‬\n      ‫املــادة ‪ 16‬واملعينــن مبوجــب محضــر انعقــاد اجلمعيــة العامــة يف ‪04 / 03‬‬\n      ‫‪1430 /‬ه ـ و اجلمعيــة العامــة احلاديــة عشــر يف ‪1431 / 04 / 15‬ه ـ‬\n      ‫ومبوجــب خطــاب مديــر عــام وزارة التجــارة و الصناعــة بجــدة برقــم‬\n      ‫‪ 17167‬يف‪1431 / 05 / 20‬ه ـ وبعــد تعريفــه مــن‪....... :‬ســعودي ســجل‬\n      ‫مدنــي‪ .....‬و‪ ......‬ســعودي ســجل مدنــي ‪ ......‬مبوجــب الوكالــة الصــادرة‬\n      ‫مــن كتابــة العــدل الثانيــة بجنــوب جــدة برقــم ‪ 31384‬وتاريــخ‬\n      ‫‪1431/9/20‬ه ـ جلــد ‪ 3097‬وحضــر املدعــى عليــه وكالــة‪ ،‬وبســؤال‬\n      ‫املدعــى عليــه وكالــة عــن مــا طلــب اإلمهــال مــن أجلــه قــدم مذكــرة عــن‬\n      ‫موكلــه هــذا نصهــا‪ :‬إننــي وقبــل تاريــخ ‪1430/3/13‬ه ـ قمــت بالذهــاب‬\n      ‫إلــى مطــار امللــك عبــد العزيــز مبحافظــة جــدة الســتقبال احــد معــاريف‬\n      ‫حيــث أننــي أرســلت شــهاداتي الدراســية إلــى دولــة مصــر وذلك للتســجيل‬\n      ‫يف إحــدى اجلامعــات هنــاك وبعــد اســتالمي الشــهادات جاءنــي رجــل‬\n      ‫بالعقــد الرابــع مــن العمــر ويدعــى (‪ ).......‬وكانــت ترافقــه زوجتــه وابنــه‬\n      ‫وطلــب منــي أن أقــوم بإيصالــه إلــى شــارع ‪ ...‬وقمــت بإيصالــه وبعــد ذلــك‬\n      ‫طلــب منــي أن أقــوم بإيصالــه ملشــاويره اخلاصــة وذلــك مقابــل مبلــغ مائتان‬\n      ‫وخمســون (‪ )250‬ريــال فوافقــت لعــدم وجــود عمــل لــدي ‪ ،‬ويف اليــوم‬\n      ‫الثالــث مــن مجيئــه قــام باالتصــال بــي عنــد الســاعة احلادية عشــر صباحا‬\n\n\n‫‪273‬‬\n\f‫وقــال لــي انــه يريــد الذهــاب إلــى املطــار ويف الطريــق ذكــر لــي انــه ميلــك‬\n‫مؤسســة جتاريــة يف مدينــة الريــاض وانــه بحاجــة إلــى مبلــغ مالــي ولكــن‬\n‫ال يســتطيع أن يســحب املبلــغ مــن حســاب مؤسســته لعــدم وجــود اخلتــم‬\n‫لديــه فســألني أن كان يوجــد لــدي حســاب بالبنــك ‪ ...‬ليقــوم بتحويــل‬\n‫املبلــغ مــن حســاب مؤسســته إلــى حســابي ليتــم ســحبه مــن قبلــي ‪ ،‬فقمت‬\n‫بإعطائــه حســابي اخلــاص بالبنــك ‪ ...‬وبالفعــل مت التحويــل وكان املبلــغ‬\n‫قــدره ثالثمائــة ألــف (‪ )300,000‬ريــال وكان ذلــك بعــد االستفســار مــن‬\n‫فــرع البنــك ‪ ...‬مبطــار امللــك عبــد العزيــز ‪ ،‬فقــال لــي قــم بســحب مبلــغ‬\n‫مائتــان وخمســة وتســعون ألــف (‪ )295,000‬ريــال لــه وان أقــوم بأخــذ‬\n‫مبلــغ خمســة أالف (‪ )5000‬ريــال وذلــك مقابــل خدمتــي لــه وبعــد عشــرة‬\n‫شــهور قامــت املباحــث باســتيقايف بطريــق املدينــة وإيداعــي الســجن‬\n‫بدعــوى أن التحويــل مت بواســطة ورق مــزورة مــن مدينــة الريــاض التــي مت‬\n‫التحويــل منهــا حيــث اننــي ال اعلــم مــن الــذي قــام بهــذا العمــل طيلــة‬\n‫مكوثــي بالســجن لعلــم فضيلتكــم أن ال حــول لــي وال قــوة إال بــاهلل‪،‬‬\n‫وبعــد خروجــي بأمــر اهلل ســبحانه وتعالــى بحثــت عــن املتســبب عــن ذلــك‬\n‫وهــو شــخص فلســطيني اجلنســية ويدعــى ‪ /‬ورقــم جوالــه ‪ .../‬وعلمــت انــه‬\n‫هــو مــن انتحــل شــخصية كفيلــة املدعــو ‪ /‬واســتطعت أيضـ ًا بتوفيــق مــن‬\n‫اهلل ســبحانه وتعــال باحلصــول علــى رقــم جــوال كفيــل املدعــو ‪ /‬وهــو ‪/‬‬\n‫وقــد قمــت ببــاغ لشــرطة محافظــة جــدة لــدى ضابــط التحقيــق املختــص‬\n‫فأبلغنــي أن يتــم طلبــه عــن طريــق القاضــي لكــون القضيــة منظــورة‬\n‫لديــه ولــم يتــم لبــت بهــا‪ .‬لــذا ارجــو مــن اهلل ثــم مــن فضيلتكــم طلــب‬\n‫الشــخص الــذي قــام بذلــك وهــو املتســبب بدخولــي الســجن وكذلــك‬\n‫التزويــر وهــو مــن يســتحق العقــاب وليــس أنــا‪ .‬وبعــرض ذلــك علــى املدعــي‬\n\n\n                                                                                        ‫‪274‬‬\n\f      ‫وكالــة قــال‪ :‬أطلــب اإلمهــال للــرد‪ .‬ثــم رفعــت اجللســة لذلــك ولطلــب‬\n      ‫املتداخــل‪ .‬ويف يــوم الســبت املوافق‪1433/07/05‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ 01 :15‬وفيهــا حضــر املدعــي وكالــة علــي‪ ،‬وحضــر املدعــى‬\n      ‫عليــه أصالــة ‪ ...‬فلســطيني اجلنســية مبوجــب اإلقامــة رقــم ‪ ،‬وبســؤال‬\n      ‫املدعــي وكالــة عمــا طلــب الوكيــل اآلخــر اإلمهــال مــن أجلــه قــال‪ :‬إن‬\n      ‫مذكــرة املدعــى عليــه إمنــا هــي ســرد لقصــة ال عالقــة ملوكلــي البنــك‬\n      ‫فيهــا‪ ،‬وإمنــا يؤكــد فيهــا بــأن املبلــغ أودع يف حســابه بقبولــه ومعرفتــه‪،‬‬\n      ‫وأطلــب إلــزام املدعــى عليــه بإعــادة املبلــغ محــل الدعــوى وقــدره ‪150‬‬\n      ‫ألــف ريــال‪ ،‬والــذي أديــن بســببه لــدى ديــوان املظالــم وحكــم عليــه‬\n      ‫بغرامــة ماليــة والســجن‪ .‬وبعــرض ذلــك علــى املدعــى عليــه قــال‪ :‬إننــي أقــر‬\n      ‫باســتالم املبلــغ بعــد أن أودع يف حســابي‪ ،‬ولكــن ملصلحــة مســتفيد آخــر‬\n      ‫هــو ‪ ،...‬وقــد مت طلبــه لهــذه اجللســة ولــم يحضــر‪ ،‬وأطلــب إحضــاره بالقوة‬\n      ‫اجلبريــة‪ .‬وباالطــاع علــى أوراق املعاملــة وجــد أنــه مت طلــب ‪ ...‬وتبليــغ ‪...‬‬\n      ‫ابــن كفيــل املدعــى عليــه عــن طريــق محضــري اخلصــوم‪ .‬ثــم رفعــت‬\n      ‫إلحضــار املتداخــل أردنــي اجلنســية مبوجــب اإلقامــة رقــم ولــو أدى ذلــك‬\n      ‫الســتخدام القــوة اجلبريــة‪ .‬ويف يــوم األحــد املوافــق ‪1433/08/04‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة ‪ 02 :00‬وفيهــا حضــر الطرفــان‪ ،‬وقــد أبــرز‬\n      ‫املدعــى عليــه خطــاب مديــر شــعبة تنفيــذ األحــكام احلقوقيــة بشــمال‬\n      ‫جــده املكلــف برقــم ‪/79‬ح ش ‪ 22/‬وتاريــخ ‪1433/8/4‬ه ـ املتضمــن أنــه‬\n      ‫لــم يتــم العثــور علــى املذكــور حيــث أفادنــا ابنــه بــأن والــده مســافر خارج‬\n      ‫اململكــة حســبما يتضــح لكــم مــن محضــر االنتقــال املرفــق ‪ .‬أه ـ ثــم‬\n      ‫قــدم املدعــى عليــه مذكــرة هــذا نصهــا‪ :‬أوال ‪ /‬ال يحــق للبنــك ‪ ...‬إنــكار‬\n      ‫أو إثبــات مــا ذكرتــه يف اجللســة الســابقة وإن أنكــر أقوالــي فذلــك‬\n\n\n‫‪275‬‬\n\f‫يعتبــر اتهامــا باطــا وحيــث أننــي مــا زلــت أطالــب بالتحقــق مــن أقوالــي‬\n‫الســابقة وإحضــار الســيد ‪ /‬أردنــي اجلنســية وعنــد حضــوره ســوف يتــم‬\n‫إثبــات صحــة أقوالــي بــإذن اهلل ثانيــا ‪ /‬إن احلكــم الصــادر بحقــي مــن‬\n‫ديــوان املظالــم املتعلــق بقضيــة التزويــر لم يتم إصداره إال ألنني املســتفيد‬\n‫( ألن احلوالــة نزلــت يف حســابي ) مــن مبلــغ احلوالــة وانــه لــم يتــم احلكــم‬\n‫بنــاء علــى تورطــي بعمليــه التزويــر وحيــث أن املســتفيد الفعلــي مــن عمليه‬\n‫التحويــل هــو ‪.............‬وحيــث أن ديننــا احلنيــف قــد حثنــا علــى معاقبــة‬\n‫فاعــل اجلــرم وليــس شــخصا آخــر كمــا جــاء يف القــران الكــرمي قــول‬\n‫اهلل تعالــى ( وال تــزر وازرة وزر أخــرى) لذلــك نرجــو مــن فضيلتكــم‬\n‫التحقــق والتأكــد مــن اجلانــي وذلــك بإحضــار الســيد ‪ ...‬أردنــي اجلنســية‬\n‫وأخــذ أقوالــه وعندهــا بــإذن اهلل ســوف يتــم إظهــار احلــق ومعرفــه فاعــل‬\n‫اجلــرم‪ .‬وبعــرض ذلــك علــى املدعــي وكالــة قــال‪ :‬ليــس لــدي إضافــة علــى‬\n‫مــا ذكــر يف الدعــوى‪ ،‬وأطلــب اإلمهــال للرجــوع ملوكلــي يف ذلــك‪،‬‬\n‫وأطلــب التعميــم علــى املتداخــل أردنــي اجلنســية مبوجــب اإلقامــة رقــم‬\n‫بحســب إفــادة املدعــى عليــه‪ .‬ثــم رفعــت اجللســة لذلــك‪ .‬ويف يــوم األحــد‬\n‫املوافــق ‪1433/09/17‬ه ـ افتتحــت اجللســة الســاعة ‪ 01 :00‬وفيهــا حضر‬\n‫الطرفــان‪ ،‬ولــم يردنــا شــيء بخصــوص املتداخل ‪ ،‬وحيــث تعذر إحضاره‬\n‫فــإن الدعــوى تتوجــه للمدعــى عليــه‪ ،‬حيــث إن عليــه عــبء إحضــار‬\n‫املتداخــل‪ ،‬وبســؤال املدعــى عليــه البينــة علــى مــا دفــع بــه يف الدعــوى‬\n‫قــال‪ :‬أطلــب اإلمهــال إلحضارهــا‪ .‬ثــم رفعــت اجللســة لذلــك‪ .‬ويف يــوم‬\n‫االثنني املوافق ‪1433/11/01‬هـ افتتحت اجللســة الســاعة ‪ 01 :30‬وفيها‬\n‫حضــر الطرفــان‪ ،‬وبســؤال املدعــى عليــه عمــا طلــب اإلمهــال مــن أجلــه‬\n‫قــال‪ :‬أطلــب اإلمهــال مــرة أخــرى‪ .‬وبعــرض ذلــك علــى املدعــي وكالــة‬\n\n\n                                                                                      ‫‪276‬‬\n\f      ‫قــال‪ :‬ال أمهلــه‪ .‬فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‪ ،‬وبنــاء علــى‬\n      ‫إقــرار املدعــى عليــه باســتالم كامــل املبلــغ محــل الدعــوى وقــدره‬\n      ‫ثالثمائــة ألــف ريــال‪ ،‬وذلــك بإيــداع املبلــغ يف حســابه‪ ،‬ومــن ثــم صــرف‬\n      ‫مبلــغ قــدره مائتــان وخمســة وتســعون ألــف ريــال‪ ،‬وتســليم ذلــك املبلــغ‬\n      ‫للمدعــو ‪ ،‬وإبقــاؤه ملبلــغ خمســة آالف ريــال يف حســابه‪ ،‬وبنــاء علــى تعــذر‬\n      ‫الوصــول للمدعــو‪ ، .......‬وبنــاء علــى أن املدعــى عليــه لــم يقــم البينــة علــى‬\n      ‫دفعــه بعــد إمهالــه لذلــك‪ ،‬وحلديــث (علــى اليــد مــا أخــذت حتــى تؤديــه)‬\n      ‫رواه األربعــة‪ ،‬وحلديــث (أن النبــي صلــى اهلل عليــه وســلم قضى أن اليمني‬\n      ‫علــى املدعــى عليــه) رواه البخــاري‪ ،‬وحلديــث (البينــة علــى املدعــي‬\n      ‫واليمــن علــى املدعــى عليــه) رواه الترمــذي‪ ،‬قــال أبــو عيســى‪ :‬العمــل‬\n      ‫عنــد أهــل العلــم مــن أصحــاب النبــي صلــى اهلل عليــه وســلم وغيرهــم أن‬\n      ‫البينــة علــى املدعــي واليمــن علــى املدعــى عليــه‪ ،‬لذلــك كلــه‪ ،‬فقــد‬\n      ‫حكمــت علــى املدعــى عليــه ‪ ...‬بدفــع مبلــغ وقــدره مائــة وخمســون ألــف‬\n      ‫ريــال للمدعــي البنــك ‪ ، ...‬وأفهمــت املدعــى عليــه بــأن لــه الرجــوع علــى‬\n      ‫املدعــو باملبلــغ احملكــوم بــه متــى مــا ثبــت ذلــك‪ .‬وبه قنع املدعــي وكالة‪،‬‬\n      ‫وقــرر املدعــى عليــه االعتــراض‪ ،‬وجــرى تســليمه نســخة مــن احلكــم‬\n      ‫وإفهامــه بــأن لــه احلــق يف االعتــراض عليــه خــال ثالثــن يومــا‪ ،‬وإال‬\n      ‫ســقط حقــه يف االعتــراض‪ ،‬واكتســب احلكــم القطعيــة‪ .‬وأقفلــت‬\n      ‫اجللســة الســاعة ‪ 02 :00‬وبــاهلل التوفيــق‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                                 ‫وعلى آله وصحبه وسلم‪ .‬حرر يف ‪1433/11/01‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي باحملكمــة العامــة بجدة خلف‬\n      ‫الشــيخ ففــي يــوم الســبت املوافــق ‪1434/01/24‬ه ـ افتتحــت اجللســة‬\n      ‫الســاعة ‪ 8 :15‬وقــد عــادت املعاملــة مــن محكمــة االســتئناف بخطــاب‬\n\n\n‫‪277‬‬\n\f‫رئيســها رقــم ‪ 3429475‬وتاريــخ ‪1434/1/17‬ه ـ وبالقــرار رقم ‪349355‬‬\n‫وتاريــخ ‪1434/1/12‬ه ـ واملتضمــن مــا يلــي وبدراســة الصــك وصــورة‬\n‫ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم وحتــى ال‬\n‫يخفــى جــرى أثباتــه وأمــرت بإحلاقــه بصكــه وســجله وأقفلــت اجللســة‬\n‫الســاعة‪ 8 :32‬وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى‬\n                             ‫آلــه وصحبــه وســلم حــرر يف ‪1434/1/24‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                  ‫‪278‬‬\n\f279\n\f280\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":269,"source_page_end":280,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"84eb0d81b9c79642bac342ba76e31a768adcb136e736ac66161061175c818b59","normalized_text_hash":"34c3754272bd32581387eeb99e5c0885f0785cfabc2fc9e41a8583ae533d8ac3","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p269-33443865"},{"id":"1291bb0f-5960-5196-acc2-15143cd0c21b","document_type":"judgment","category":"judicial","subcategory":"general","title":"رد مختلس -اختاس مبالغ مالية عن طريق خيانة األمانة -بينات غير موصلة -إثبات الدفع بالبراءة -ضمان األجير اخلاص -احلكم برد دعوى -استحقاق املدعي ليمن خصمه على نفي الدعوى متى","document_number":"34261913","case_number":"410","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بخميس مشيط","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/8","year":"1434","subject":"رد مختلس -اختاس مبالغ مالية عن طريق خيانة األمانة -بينات غير موصلة -إثبات الدفع بالبراءة -ضمان األجير اخلاص -احلكم برد دعوى -استحقاق املدعي ليمن خصمه على نفي الدعوى متى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫تاريخه‪1434/7/8 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34261913 :‬‬\n                              ‫َر ْق ُم الدعوى‪410 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 34313612‬تاريخه‪1434/9/7:‬هـ‬\n\n\n      ‫رد مختلــس‪ -‬اختــاس مبالــغ ماليــة عــن طريــق خيانــة األمانــة ‪ -‬بينات‬\n      ‫غيــر موصلــة ‪ -‬إثبــات الدفــع بالبــراءة ‪ -‬ضمــان األجير اخلاص‪ -‬احلكم‬\n      ‫بــرد دعــوى‪ -‬اســتحقاق املدعــي ليمــن خصمــه علــى نفــي الدعــوى متــى‬\n                                                                     ‫طلبها‪.‬‬\n\n\n\n\n                                                               ‫األصل براءة الذمة‪.‬‬\n\n\n\n\n      ‫ادعــى وكيــل الشــركة املدعيــة علــى احلاضــر معــه بأنــه َّإبــان عملــه لدى‬\n      ‫موكلتــه كمديــر ألحــد فروعهــا قــام باختــاس مبالــغ ماليــة والتفريــط‬\n      ‫يف حتصيــل مســتحقات للشــركة املدعيــة‪ ،‬وطلــب إلزامــه بتســليم‬\n      ‫املبالــغ املترتبــة علــى ذلــك إلــى الشــركة موكلتــه‪ -‬أنكــر املدعــى‬\n      ‫عليــه الدعــوى جملــة وتفصيــا ودفــع بــأن جــزء مــن املبالــغ املدعــى بهــا‬\n      ‫هــي حتــت مســؤولية مندوبــي املبيعــات وال عالقــة لــه بهــا‪ -‬قــدم وكيــل‬\n      ‫املدعيــة عــددا مــن البينــات إلــى احملكمــة إال أنهــا غيــر موصلــة إلثبــات‬\n      ‫دعواه‪-‬كمــا أحضــر املدعــى عليــه شــاهدين إلثبــات مــا دفــع بــه فشــهدا‬\n      ‫مبــا يثبــت ذلــك وعــدال التعديــل الشــرعي‪ -‬ألن املدعــى عليــه يــده يــد‬\n      ‫أمانــة فــا يضمــن إال إذا تعــدى أو فــرط واألصــل بــراءة الذمــة‪ -‬لــذا‬\n\n‫‪281‬‬\n\f‫انتهــت جهــة التحقيــق إلــى عــدم اتهــام املدعــى عليــه مبــا نســب إليــه‪-‬‬\n‫وقضــت احملكمــة بصــرف النظــر عــن دعــوى املدعيــة وأفهمــت وكيلهــا‬\n‫بــأن لــه ميــن املدعــى عليــه علــى نفــي مــا أدعــى بــه متــى طلبهــا‪ -‬قنــع‬\n‫املدعــى عليــه باحلكــم وعــارض عليــه وكيــل املدعيــة‪ -‬قــررت محكمــة‬\n                                          ‫االســتئناف املوافقــة علــى احلكــم‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي يف احملكمــة العامــة بخميــس‬\n‫مشــيط وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫العامــة بخميــس مشــيط برقــم ‪ 410‬وتاريــخ ‪ 1431/07/02‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 312217‬وتاريــخ ‪ 1431/07/02‬ه ـ ففــي يــوم الثالثــاء‬\n‫املوافــق‪ 1432/06/28‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 :40‬وفيهــا حضر‬\n‫‪ ......‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ......‬حــال كونــه‬\n‫وكيــا عــن ‪ ......‬الوكيــل الشــرعي عــن بصفتهــم مديريــن لشــركة‬\n‫مجموعــة ‪ ......‬الصناعيــة مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل‬\n‫ا إن هــذا‬   ‫شــمال جــدة الثانيــة برقــم ‪ 99351‬يف ‪1431/12/3‬ه ـ قائ ـ ً‬\n‫احلاضــر معــي كان يعمــل لــدي الشــركة موكلتــي بصفتــه مديــر ًا لفرع‬\n‫الشــركة يف املنطقــة اجلنوبيــة منــذ مــا يقــارب ســبعة عشــر عام ـ ًا وقــد‬\n‫حصــل منــه خلــل يف عملــه يف الســنوات اخلمــس األخيــرة وترتــب علــى‬\n‫ذلــك عــدة مطالبــات للشــركة جتاهــه وحينهــا قامــت الشــركة بفصلــه‬\n‫مــن الشــركة وذلــك قبــل ســنة ونصــف تقريبـ ًا واملطالبــات التــي تطالــب‬\n‫بهــا الشــركة موكلتــي علــى النحــو التالــي‪ :‬أوالً‪ :‬قيمــة واحــد وخمســون‬\n‫ثالجــة قــام املدعــى عليــه بالتصــرف فيهــا وهــي عهــدة عليــه لــم يقــم‬\n\n                                                                                     ‫‪282‬‬\n\f      ‫بإرجاعهــا للشــركة حــن فصلــه وقيمــة هــذه الثالجــات خمســون ألــف‬\n      ‫وثمامنائــة وخمســة وأربعــون ( ‪ ) 50845‬ريــال فنطلــب إرجاعهــا أو قيمتها‪.‬‬\n      ‫ثاني ـاً‪ :‬فواتيــر صيانــة مصطنعــة مببلــغ قــدره ثالثــون ألــف وســتمائة‬\n      ‫وواحــد وتســعون ( ‪ ) 30691‬ريــال قــام املدعــى عليه باصطناعها وليســت‬\n      ‫صحيحــة‪ .‬ثالثـاً‪ :‬ديــون غيــر محصلــة مســتحقة للشــركة علــى اآلخريــن‬\n      ‫لــم يقــم املدعــى عليــه بتحصيلهــا وقدرهــا مائــة وواحــد وســبعون ألــف‬\n      ‫واثنــان وثالثــون (‪ )171032‬ريــا ًال وقــد نصــت املــادة اخلامســة مــن عقــد‬\n      ‫العمــل املبــرم بينهمــا علــى أن املدعــى عليــه مســئول عــن جميــع املبالــغ‬\n      ‫احلاصلــة واآلجلــة علــى اآلخريــن لــذا فــإن الشــركة موكلتــي تطالــب‬\n      ‫املدعــى عليــه بجميــع هــذه املطالبــات وقدرهــا مائتــان وواحــد وســتون‬\n      ‫ألفـ ًا وخمســمائة وثمانيــة وســتون (‪ )261568‬ريــا ًال هــذه دعــواي وبعــرض‬\n      ‫ذلــك علــى املدعــى عليــه أجــاب قائ ـاً‪ :‬مــا ذكــره املدعــي وكالــة يف‬\n      ‫دعــواه مــن أنــي كنــت موظف ـ ًا لــدى شــركة موكلتــه بصفتــي مديــر ًا‬\n      ‫لفــرع اجلنــوب فهــذا صحيــح ومــا ذكــره مــن املطالبــات املاليــة التــي‬\n      ‫يدعيهــا وأنــي مختلــس لهــا فهــذا غيــر صحيــح وقــد حققــت الشــرطة‬\n      ‫واالدعــاء العــام يف املعاملــة وليــس فيهــا مــا يثبــت ذلــك فأما‪.‬بالنســبة‬\n      ‫للثالجــات والتــي ذكرهــا يف دعواهــا فــكان دوري يف الفــرع هــو‬\n      ‫اســتالم الثالجــات مــن املصنــع وتســليمها للمندوبــن وهــم بدورهــم‬\n      ‫يقومــون بتوزيعهــا علــى احملــات ويتــم اســتالم الثالجــة مــن قبــل املنــدوب‬\n      ‫والتوقيــع علــى االســتالم وتكــون بذلــك يف عهــده املندوبــن وقــد مت‬\n      ‫تســليم املندوبــن جميــع الثالجــات التــي اســتلمتها وقــام أحــد املندوبــن‬\n      ‫وهــو املدعــو‪ ....../‬هنــدي اجلنســية بســحب مائــة وســبعني ثالجــة وقــام‬\n      ‫بعدهــا بالهــروب ومت التبليــغ عنــه ومت حتصيــل مائــة وأربعــة وخمســن‬\n\n\n‫‪283‬‬\n\f‫ثالجــة بعــد البحــث عنهــا وإجــراء املســح الــازم وبقــي منهــا ســتة عشــر‬\n‫ثالجــة وهــي لــدى بعــض احملــات وبالبحــث عنهــا تبــن أن هــذه احملــات‬\n‫قامــت باالنتقــال مــن أماكنهــا دون إشــعار الشــركة ومــع ذلــك فهــي‬\n‫ليســت عهــدة علـ ّـي وإمنــا هــي علــى املنــدوب الهــارب وكذلــك عــدد عشــر‬\n‫ثالجــات عنــد الغيــر وأمــا بالنســبة لفواتيــر الصيانــة التــي ذكرهــا فهــذا‬\n‫غيــر صحيــح بــل إن الصيانــة الفعليــة كانــت يجــب أن تكــون أكبــر‬\n‫مــن هــذا املبلــغ وقــد ُذكــر ذلــك لــدى جهــة التحقيــق بعــد اســتدعاء بعض‬\n‫املناديــب وإقرارهــم بــأن مــا كان يتــم صيانتــه مــن ثالجــة تقــدر صيانتهــا‬\n‫بأكثــر مــن ذلــك وأمــا بالنســبة للديــون غيــر احملصلــة فاجلــواب عنهــا‬\n‫كاجلــواب عــن الثالجــات الــواردة يف البنــد أو ًال مــن حيــث كــون مهمتــي‬\n‫توزيــع املســئوليات وأمــا الديــون فتكــون علــى املناديــب وهــم مســئولون‬\n‫مســئولية تامــة عــن حتصيلهــا مــن اآلخريــن وهــذا الهنــدي املذكــور أنفـ ًا‬\n‫عندمــا هــرب كان مطلوبـ ًا مببلــغ مائة وواحد وســبعون ألف (‪)171000‬‬\n‫ريــال عبــارة عــن ديــون لــدى اآلخريــن لــم يحصلهــا فقمــت أنــا ومنــدوب‬\n‫مــن الشــركة مصــري اجلنســية اســمه ‪ .....‬باملــرور علــى احملــات وتســليم‬\n‫هــذه الديــون وقــد مت اســتالم املدعــو‪ ....... /‬منهــا مبلــغ مائــة وســتة عشــر‬\n‫ألفـ ًا ومائتــان وســبعة وثالثــون (‪ )116237‬ريــا ًال وبقــي منهــا مبلــغ أربعــة‬\n‫وخمســون ألــف وســبعمائة وخمســة وتســعون (‪ )54795‬ريــا ًال وقــد أثبــت‬\n‫هــذا لــدى الشــرطة ومــا ذكــره يف العقــد املبــرم بينــي وبــن الشــركة‬\n‫مــن حتميلــي مســئولية هــذه الديــون غيــر محصلــه فقــد صــدر بعــده عقــد‬\n‫أخــر بتاريــخ أحــدث ينســخ ذلــك وأطلــب االطــاع عليهــا هكــذا أجــاب‬\n‫ويف جلســة أخــرى حضــر الطرفــان وجــرى عــرض جــواب املدعــى عليــه‬\n‫ا بالنســبة ملــا ذكــره املدعــى عليــه من‬  ‫علــى املدعــي وكالــة فأجــاب قائـ ً‬\n\n\n                                                                                       ‫‪284‬‬\n\f      ‫أن القضيــة حقــق فيهــا مــن قبــل الشــرطة واالدعــاء العــام وأنــه ليــس فيهــا‬\n      ‫مــا يثبــت الدعــوى فهــذا غيــر صحيــح بــل يوجــد عليــه إقــرارات تثبــت‬\n      ‫ذلــك مرفقــة بــأوراق املعاملــة ومــا ذكــره مــن أن دوره يف الفــرع هــو‬\n      ‫اســتالم الثالجــات وتوزيعهــا علــى املندوبــن وأنهــا عهــدة علــى املندوبــن‬\n      ‫فغيــر صحيــح بــل هــي عهــدة عليــه وعلــى املنــدوب وهــو ضامــن للمنــدوب‬\n      ‫كمــا نــص عليــه العقــد ومــا ذكــره مــن أن املنــدوب ‪ ......‬قــام بســحب‬\n      ‫مائــة وســبعني ثالجــة وهــرب بعــد ذلــك فهــذا صحيــح ومــا ذكــره مــن أنــه‬\n      ‫مت إرجــاع مائــة وأربعــة وخمســن (‪ )154‬ثالجــة وبقــي ســتة عشــر (‪)16‬‬\n      ‫ثالجــة فهــذا غيــر صحيــح بــل بقــي عشــرين (‪ )20‬ثالجــة وهــى علــى‬\n      ‫املنــدوب الهــارب ولكــن املدعــى عليــه ضامــن لهــا باإلضافــة إلــى أن‬\n      ‫عنــده ثمــان ( ‪ )8‬ثالجــات عهــدة شــخصية عليــه ومــا ذكرهــن مــن أن‬\n      ‫فواتيــر الصيانــة صحيحــة وأن الصيانــة الفعليــة كان يجــب أن تكــون‬\n      ‫قيمتهــا أكثــر مــن ذلــك فغيــر صحيــح ويــدل علــى ذلــك أن الفواتيــر‬\n      ‫متسلســلة وغيــر مطابقــة للفواتيــر الصــادرة مــن الورشــة املذكــورة‬\n      ‫كمــا أن صاحــب الورشــة أفادنــا بــأن الورشــة مغلقــة منــذ ثــاث ســنوات‬\n      ‫وهنــاك تقريــر صــادر مــن محاســب قانونــي يبــن اخللــل يف ذلــك ومــا‬\n      ‫ذكــره مــن الديــون غيــر احملصلــة مت اســتالم مائــة وســتة عشــر ألــف‬\n      ‫(‪ )116000‬ريــال منهــا فهــذا صحيــح ومــا ذكــره مــن أنــه بقــي منهــا مبلــغ‬\n      ‫أربعــة وخمســون وســبعمائة وخمســة وتســعون (‪ )54795‬ريــا ًال فصحيــح‬\n      ‫وهــو مســئول عنهــا مســئولية تامــة كمــا هــو مبــن يف العقــد املبــرم بينــه‬\n      ‫وبــن الشــركة هكــذا أجــاب وبعــرض ذلــك علــى املدعــى عليــه أجــاب‬\n      ‫قائـاً‪ :‬بالنســبة ملــا ذكــره املدعــي مــن كونــي ضامــن للمنــدوب الهــارب‬\n      ‫فهــذا غيــر صحيــح وليــس يف العقــد مــا يثبــت ذلــك ومــا ذكــره مــن أنــه‬\n\n\n‫‪285‬‬\n\f‫مت اســتالم مائــة وأربعــة وخمســن (‪ )154‬ثالجــة فصحيــح وقــد ذكرتــه‬\n‫ســابق ًا واملتبقــي منهــا ســتة عشــر (‪ )16‬ثالجــة وليســت عشــرين (‪)20‬‬\n‫كمــا ذكــر وأمــا بالنســبة لثمــان (‪ ) 8‬الثالجــات التــي ذكروهــا بأنهــا‬\n‫عهــدة عنــدي فهــي لــدى التاجــر ‪ ....‬يف أحــد املســارحة مت تســلمه إياهــا‬\n‫بطريقــة رســمية وهــي بذلــك يف عهدتــه فــإذا كان للشــركة مطالبــة‬\n‫فاملطالبــة عليــه علمـ ًا بأنــه قــد كتــب خطابـ ًا للشــركة ذكر بــأن هناك‬\n‫خمــس ثالجــات منهــا قــد فقــدت يف ظــل األحــداث األخيــرة يف احلــدود‬\n‫اجلنوبيــة وبقــي عنــده ثــاث ثالجــات ومســتعد بتســليم هــذه الثالجــات‬\n‫وأمــا التــي فقــدت فطلــب ســماحه منهــا أو التفاهــم معــه حيالها وبالنســبة‬\n‫ملــا ذكــره مــن الصيانــة فالصحيــح مــا ذكرتــه ســابق ًا ومــا ذكــره مــن‬\n‫كــون الفواتيــر متسلســلة فاجلــواب عنــه أن الورشــة قــد خصصــت لنــا‬\n‫فواتيــر معينــة إلصدارهــا نظــر ًا لكوننــا متعاملــن معهــم دائم ـ ًا وقــد‬\n‫حضــر صاحــب الورشــة لــدي الشــرطة وقــرر بــأن هــذه الفواتيــر صحيحــة‬\n‫وقــد اســتلم حقهــا وبالنســبة ملــا ذكــره مــن الديــون غيــر احملصلــة وأنــي‬\n‫ضامــن للمنــدوب الهــارب فغيــر صحيــح ذلــك أن البنــد اخلامــس يف العقــد‬\n‫الســابق نــص علــى أننــي أنــا واملنــدوب متضامنــان يف متابعــة هــذه الديــون‬\n‫عنــد العمــاء واملنــدوب هــو املســئول عــن حتصيــل هــذه ا لديــون وأن‬\n‫مســئولتي مــع املنــدوب عــن هــذه الديــون مــا دامــت عنــد العمــاء أمــا إذا‬\n‫حتصــل عليهــا املنــدوب فهــو املســئول عنهــا وهــو مــا حصــل يف قضيتنــا‬\n‫هــذه وهــذا فيمــا يتعلــق بالعقــد الســابق وأمــا يف العقــد اجلديــد املبــرم يف‬\n‫عــام ‪2001‬م وقــد أحضرتــه الشــركة املدعيــة وأرفقته باألوراق مســتدلة‬\n‫بــه رغــم عــدم توقيعــه مــن قبلهــم وقــد نــص يف هــذا العقــد يف الفقــرة (‬\n‫‪ ) 13‬علــى أن الطــرف الثانــي وهــو املنــدوب بأنــه مســئول عــن جميــع‬\n\n\n                                                                                       ‫‪286‬‬\n\f      ‫املبيعــات اآلجلــة التــي تتــم عــن طريقــة وهــذه الفواتيــر التــي يطالبوننــي‬\n      ‫بهــا لــم تتــم عــن طريقــي وإمنــا متــت عــن طريــق املنــدوب الهــارب ‪ ......‬وأنــا‬\n      ‫لــم أبــع بريــال واحــد عــن طريقــي وإمنــا صفتــي يف هــذا العقــد مديــر‬\n      ‫مبيعــات هكــذا أجــاب ويف جلســة أخــرى حضــر الطرفــان فجــرى منــي‬\n      ‫ا بينتــي العقــود املبرمــة‬‫ســؤال املدعــي البينــة علــى دعــواه فأجــاب قائ ـ ً‬\n      ‫بــن الشــركة موكلتــي وبــن املدعــى عليــه ثــم أبــرز العقــد املــدون علــى‬\n      ‫مطبوعــات مؤسســة ‪ ......‬برقــم بــدون يف ‪1992/11/11‬م واملتضمــن مــا‬\n      ‫نصــه‪ « :‬بســم اهلل الرحمــن الرحيــم عقــد عمــل حــرر هــذا العقــد بــن‬\n      ‫كال مــن‪ :‬أوال‪ /‬مؤسســة ‪ ......‬للتجــارة والصناعــة واخلدمــات الطبيــة‬\n      ‫لصاحبهــا ‪ /‬وميثلهــا يف هــذا العقــد ‪ /‬طــرف أولــف ثاني ـاً‪ /‬الســيد ‪/‬‬\n      ‫أردنــي اجلنســية رقــم ا جلــواز ‪ /‬مصــدره‪ /‬الريــاض عنوانــه يف بلــده ‪/‬‬\n      ‫فلســطني ت‪ /‬طــرف ثانــي كمــا أبــرز العقــد املــدون علــى مطبوعــات‬\n      ‫مجموعــة ‪ ......‬رقــم بــدون يف ‪1416/8/10‬ه ـ املوافــق ‪1996/1/1‬م‬\n      ‫واملتضمــن مــا نصــه‪ « :‬بســم اهلل الرحمــن الرحيــم عقــد عمــل حــرر هــذا‬\n      ‫العقــد بــن كال مــن‪ :‬أوالً‪ :‬مؤسســة ‪ ......‬للتجــارة والصناعــة واخلدمــات‬\n      ‫الطبيــة لصاحبهــا ‪...... /‬وميثلهــا يف هــذا العقــد ‪ ...... /‬طــرف أول ثاني ـاً‪:‬‬\n      ‫الســيد ‪ ...... /‬اجلنســية أردنــي جــواز ســفر رقــم ‪ ...... /‬مصــدره الريــاض‬\n      ‫العنــوان ‪ ......‬ت ‪ ......‬طــرف ثانــي كمــا أبــرز ســندات صــرف مــن حســاب‬\n      ‫مصنــع ‪ ......‬لأليــس كــرمي تبــدأ مــن الرقــم ‪ 13840‬يف ‪2007/7/1‬م‬\n      ‫وتنتهــي بالســند رقــم ‪ 13847‬يف ‪2007/7/1‬م مببالــغ مختلفــة ومرفق ـ ًا‬\n      ‫بهــذه الســندات فواتيــر نقديــة مــن مؤسســة ‪ ......‬للتبريــد والتكييــف‬\n      ‫تبــدأ مــن الرقــم ‪ 29582‬يف ‪1417/5/1‬ه ـ وتنهــي بالرقــم ‪ 29589‬يف‬\n      ‫‪2007/5/1‬م بنفــس املبالــغ الســابقة وهــذه الفواتيــر مبوجبهــا مت‬\n\n\n‫‪287‬‬\n\f‫الســحب مــن حســاب الشــركة املدعيــة مــن خــال ســندات الصــرف‬\n‫املذكــورة بعاليــة وبســؤال املدعــي عــن وجــه اســتدالله بهذيــن العقديــن‬\n‫ا إنــه ورد يف البنــد رقــم (‪)5‬‬  ‫وســندات الصــرف املذكــورة فأجــاب قائـ ً‬\n‫يف العقديــن بــأن املنــدوب أو مديــر الفــرع مســئول مســئولية تامــة عــن‬\n‫الديــون التــي للشــركة علــى اآلخريــن وبذلــك يكــون املدعــى عليــه‬\n‫مســئول عــن هــذه الديــون التــي اختلســها العامــل ‪ ......‬وبالنســبة للســندات‬\n‫فــإن هــذه الســندات قــد أخــذت أرقــام متسلســلة ممــا يثيــر الشــك لدينــا‬\n‫يف صحــة هــذا الســندات هكــذا أجــاب وبعــرض ذلــك علــى املدعــى‬\n‫ا بالنســبة ملــا ورد يف هــذا البنــد فــإن هــذا خــاص‬    ‫عليــه أجــاب قائ ـ ً‬\n‫بالديــون التــي لــدى اآلخريــن ولــم يتــم حتصيلهــا فــإن مديــر الفــرع يكون‬\n‫متضامــن مــع املنــدوب فيهــا أمــا إذا مت حتصيلهــا مــن قبــل املنــدوب فإنــه‬\n‫يكــون مســئو ًال عنهــا وال يعــد علــى املتضامــن معــه أي مســئولية حينهــا‬\n‫وهــو مــا حصــل يف قضيتنــا هــذه حيــث إن العامــل الهــارب ‪ ......‬قــد حصــل‬\n‫هــذه الديــون مــن العمــاء ولــم يقــم بتســليمها للشــركة وعليــه فــإن‬\n‫املطالبــة تتوجــه ضــده ثــم إن هذيــن العقديــن صادريــن منــذ تاريــخ قــدمي‬\n‫أحدهــا قبــل عشــرين ســنة واألخــر قبــل خمســة عشــر ســنة وقــد صــدر‬\n‫بعدهــا عقــد ًا أخــر بتاريــخ ‪2001/12/9‬م وقــد تضمــن هــذا العقــد بــأن‬\n‫املنــدوب هــو املســئول عــن الديــون اآلجلــة التــي تتــم عــن طريقــه هكــذا‬\n‫أجــاب ثــم أبــرز عقــد العمــل املــدون علــى مطبوعــات مجموعــة ‪......‬‬\n‫الصناعيــة واملــؤرخ يف ‪2001/12/6‬م واملتضمــن مــا نصــه‪ »:‬عقــد عمــل‬\n‫حــرر هــذا العقــد بــن كال مــن‪ :‬أوال ‪ /‬شــركة مجموعــة ‪ ......‬الصناعيــة‬\n‫وميثلهــا يف هــذا العقــد الشــيخ مــا طــرف أول ثانيــا الســيد ‪ /‬اجلنســية‬\n‫أردنــي طــرف ثانــي وبســؤال املدعــى عليــه عــن وجــه االســتدالل مــن هــذا‬\n\n\n                                                                                    ‫‪288‬‬\n\f      ‫ا لقــد ورد يف البنــد رقــم ( ‪ ) 13‬أن الطــرف الثانــي‬     ‫العقــد أجــاب قائ ـ ً‬\n      ‫املنــدوب مســئول عــن جميــع املبيعــات اآلجلــة التــي تتــم عــن طريقــه‬\n      ‫ويتعهــد بتحصيلهــا وتســديدها ويف حالــة عــدم حتصيلهــا ألي ســبب يحق‬\n      ‫للطــرف األول خصمهــا مــن راتبــه وحقوقــه وال يتــم إخــاء طرفــه إال بعــد‬\n      ‫ســداده وأنــا يف هــذا العقــد صفتــي مديــر مبيعــات ولســت مندوبـ ًا كمــا‬\n      ‫أن هــذا البنــد نــص علــى أن مســئولية املنــدوب هــو يف جميــع املبيعــات‬\n      ‫اآلجلــة التــي تتــم عــن طريقــه وأنــا لــم يتــم بيــع أي شــيء عــن طريقــي ولــو‬\n      ‫بريــال واحــد هكــذا أجــاب كمــا أضــاف بأنــه فيمــا يتعلــق بالتسلســل‬\n      ‫يف أرقــام الســندات والفواتيــر فقــد أجبــت عنــه يف اجللســة املاضيــة حيــث‬\n      ‫خصصــت لنــا املؤسســة التــي نتعامــل معهــا دفاتــر خاصــة للفواتيــر‬\n      ‫لكوننــا نتعامــل معهــا دائمـ ًا ومــن الطبيعــي أن تصــدر الفواتيــر بأرقــام‬\n      ‫متسلســل ًة وهــذا بشــهادة صحــاب الورشــة هكــذا أجــاب وبعــرض ذلــك‬\n      ‫ا بالنســبة ملــا ذكــره املدعــى عليــه مــن‬‫علــى املدعــي وكالــة أجــاب قائـ ً‬\n      ‫أن املنــدوب الهــارب قــام بتحصيــل هــذه الديــون مــن اآلخريــن وهــرب بهــا‬\n      ‫فهــذا غيــر صحيــح بــل إن الديــون ال زالــت عنــد اآلخريــن ونطلــب مــا‬\n      ‫يثبــت مــن أن املنــدوب الهــارب قــام بتحصيــل هــذه الديــون مــن اآلخريــن‬\n      ‫وأمــا فيمــا يتعلــق بالعقــد الــذي اســتدل بهــا املدعــى عليــه فهــو عقــد غيــر‬\n      ‫صحيــح حيــث خــا مــن توقيــع الشــركة موكلتــي وعليــه فمــا يســتدل‬\n      ‫بــه منــه غيــر صحيــح ومــا ذكــره مــن أن الورشــة التــي يتعاملــون معهــا‬\n      ‫خصصــت دفاتــر فواتيــر وســندات خاصــة فهــذا ال نعلــم عنــه ثــم إن هــذه‬\n      ‫الفواتيــر تختلــف عــن الفواتيــر التــي تصــدر عــن املؤسســة التــي تتعامــل‬\n      ‫معهــا الشــركة موكلتــي كمــا أن هــذه الســندات يالحــظ عليهــا بــأن‬\n      ‫املدعــى عليــه هــو املســلم واملســتلم يف نفــس الوقــت هكــذا أجــاب‬\n\n\n‫‪289‬‬\n\f‫ا بالنســبة ملــا ذكــروه مــن‬  ‫وبعــرض ذلــك علــى املدعــى عليــه أجــاب قائـ ً‬\n‫أن العامــل الهــارب لــم يقــم بتحصيــل الديــون التــي علــى اآلخريــن فأنــا‬\n‫أطلــب مــا يثبــت ذلــك ولــو كان مــا ذكــروه صحيح ـ ًا ملــاذا لــم يقومــوا‬\n‫بتحصيــل هــذه الديــون مباشــرة مــن العمــاء وملــاذا قامــوا بالتبليــغ عــن‬\n‫العامــل الهــارب ومطالبتــه باملبالــغ التــي اختلســها وأمــا العقــد الــذي‬\n‫يقولــون بأنــه غيــر نظامــي فأجيــب عنــه بأنهــم قــد قامــوا باالســتدالل‬\n‫بهــذا العقــد حــن قدمــوا الشــكوى لــدى الشــرطة ولــو كان العقــد غيــر‬\n‫صحيــح فلمــاذا يســتدلون بــه ثــم إن الطريقــة التــي تســير الشــركة عليــه‬\n‫يف التعاقــد مــع اآلخريــن أنهــا متلــي مــا تريــد إمالئــه ثــم تقــوم بإرســال‬\n‫العقــد للطــرف اآلخــر للتوقيــع عليــه وبعــد ذلــك يعــاد للشــركة وحتتفــظ‬\n‫بــه وال تعطــي للطــرف اآلخــر نســخة منــه وقــد توقــع هــذا العقــود وقــد ال‬\n‫توقعــه ومــا ذكــره مــن أن الفواتيــر غيــر مطابقــة للفواتيــر الصــادرة مــن‬\n‫الشــركة وأن املؤسســة مت إغالقهــا مــن قبــل ثــاث ســنوات فهــذا غيــر‬\n‫صحيــح بــل إن املؤسســة اســمها مؤسســة ‪ ......‬للتبريــد والتكييــف كمــا‬\n‫هــو مــدون يف الفواتيــر النقديــة وكمــا هــو مــدون يف إقــرار املؤسســة‬\n‫لــدى الشــرطة واملــدون علــى مطبوعــات املؤسســة وهــو مــؤرخ يف‬\n‫‪2010/6/23‬م وهــو كذلــك يــرد مــا زعمــوه مــن أن املؤسســة مغلقــة منــذ‬\n‫ثــاث ســنوات هكــذا أجــاب ثــم أبــرز اخلطــاب املــدون علــى مطبوعــات‬\n‫مؤسســة ‪ ......‬للتبريــد والتكييــف واملضمــن مــا نصــه‪ ( :‬بســم اهلل‬\n‫الرحمــن الرحيــم إلــى مــن يهمــه األمــر نفيــد نحــن مؤسســة ‪ ......‬للتبريــد‬\n‫والتكييــف بخميــس مشــيط أن جميــع الفواتيــر الصــادرة منــا ســواء‬\n‫كانــت فواتيــر قطــع غيــار أو فواتيــر ورشــة لشــركة أيــس كــرمي جمبــو‬\n‫طيلــة فتــرة تعاملهــم معنــا حلوالــي األربعــة عشــر ســنة املاضيــة أو أكثــر‬\n\n\n                                                                                      ‫‪290‬‬\n\f      ‫أثنــاء إدارة الســيد‪ / ....../‬لفــرع املنطقــة اجلنوبيــة كلهــا فواتير صحيحة‬\n      ‫ســواء كانــت بخــط يــده أو بحطنــا وذلــك حتــى نهايــة عملــة بالفــرع يف‬\n      ‫‪2010/10/24‬م ونفيــد أنــه قــد مت إغــاق وتصفيــة حســابنا معــه وال‬\n      ‫نطالبــه بشــيء كمــا أننــا نشــهد أن الســيد ‪ ...... /‬كان مثــا ًال لألمانــة‬\n      ‫والنزاهــة واألخــاق طيلــة تعاملــه معنــا‪ .‬واهلل ولــي التوفيــق مؤسســة ‪......‬‬\n      ‫للتبريــد والتكييــف اســم املســئول ‪ ......‬التوقيــع التاريــخ ‪2010/6/24‬م‬\n      ‫ا بــأن هــذا اخلطــاب يثبــت بــأن‬    ‫اخلتــم والبصمــة )‪.‬أ‪.‬ه ـ وأضــاف قائ ـ ً‬\n      ‫الفواتيــر التــي كانــت تصــدر منهــم صحيحــة وأنــه مت إغــاق احلســاب‬\n      ‫معــي علم ـ ًا بــأن مديــر الفــرع الــذي اســتلم اإلدارة منــي قــد حضــر لــدى‬\n      ‫مســئول الورشــة وهــو شــخص باكســتاني وال يحســن اللغــة العربيــة‬\n      ‫وكتــب خطاب ـ ًا بخــط يــده وجعــل املســئول بوقــع عليــه ويختــم بختــم‬\n      ‫الشــركة وقــد تضمــن هــذا اخلطــاب انــكار الفواتيــر الصــادرة منهــم‬\n      ‫وعنــد مقابلتــي بذلــك لــدى الشــرطة طلبــت منهــم إحضــار املســئول الــذي‬\n      ‫وقــع وســماع مــا لديــه وعنــد حضــوره أنكــر ذلــك وقــرر بــأن املديــر الــذي‬\n      ‫حضــر لديــة أفهمــه بــأن هــذا اخلطــاب بقــد تصفيــة حســابات املديــر‬\n      ‫الســابق مــع الشــركة وأنــه لــم يعــد لهــم أي مطالبــة جتاهــه ووقــع بنــا ء‬\n      ‫علــى ذلــك هكــذا أجــاب ثــم أبــرز اخلطــاب املــدون علــى مطبوعــات‬\n      ‫مؤسســة ‪ ......‬للتبريــد والتكييــف لبيــع قطــع الغيــار واملتضمــن‪( :‬الســادة‬\n      ‫‪ /‬مصنــع ‪ ......‬لآليســكرمي والعصيــر الســام عليكــم ورحمــه اهلل‬\n      ‫وبركاتــه نفيدكــم بــأن حســابنا الســابق مــع األخ ‪ /‬كان بــدون فواتيــر‬\n      ‫ومــن الواضــح مــن الفاتــورة أنــه قــام بأخــذ االســم اخلــاص بنــا للمحــل‬\n      ‫األخــر لنــا وقــام بتصويرهــا وعمــل كشــف حتــى يقــوم بكتابــة املبالــغ‬\n      ‫بنفســه وهــذه الفواتيــر ليســت لنــا كورشــة إصالح ومرفق طيــه الفاتورة‬\n\n\n‫‪291‬‬\n\f‫الــذي نحاســب بهــا وشــكر ًا مســئول الورشــة االســم ‪ ......‬التوقيــع‬\n‫البصمة)‪.‬أ‪.‬ه ـ وقــد كان حاضــر ًا يف أثنــاء اجللســة املديــر املســتلم إلدارة‬\n‫مــن املدعــى عليــه وهــو املدعــو ‪ /‬مصــري اجلنســية حامــل رخصــة اإلقامــة‬\n‫رقــم () وبعــرض ذلــك عليــه أجــا ب قائـاً‪ :‬صحيــح مــا أنــي كتبــت هــذا‬\n‫اخلطــاب بخــط يــدي لكــون العامــل ال يحســن اللغــة العربيــة وقــد كتــب‬\n‫مــا ذكــره لــي ثــم حضــر هــذا العامــل للشــرطة وأنكــر ذلــك وقــرر بأنــه‬\n‫وقــع علــى هــذا اخلطــاب بنــاء علــى أن هــذا اخلطــاب مخالصــة بــن‬\n‫الشــركة وبــن املديــر الســابق املدعــى عليــه وليــس علــى إنــكار تعامــل‬\n‫املدعــى عليــه مــع الشــركة وصحــة تعاملــه معهــا هكــذا أجــاب ثــم‬\n‫ا لــدي بينــة وهــي‬‫جــرى ســؤال املدعــي هــل لديــه مزيــد بينــة فأجــاب قائـ ً‬\n‫شــهادة هــذا احلاضــر معنــا ‪ /‬حامــل رخصــة اإلقامة الصــادرة من جوازات‬\n‫جــدة املديــر املســتلم لــإدارة مــن املدعــى عليــه وأطلــب ســماع مــا لديهــم‬\n‫وبســؤال املذكــور عمــا لديــه مــن شــهادة أجــاب أشــهد هلل بأنــي حــن‬\n‫اســتلمت اإلدارة مــن املدعــى عليــه يبــن لــي بــأن الفواتيــر التــي مت‬\n‫الصــرف مبوجبهــا مــن حســاب الشــركة تختلــف فيهــا اســم املؤسســة‬\n‫مــن اســم املؤسســة التــي تتعامــل معهــا الشــركة املدعيــة هــذا مــا لــدي‬\n‫مــن شــهادة ويف جلســة أخــرى حضــر حامــل بطاقــة الهويــة الوطنيــة رقــم‬\n‫ا عــن الوكيــل الشــرعي عــن بصفتهــم مديريــن‬            ‫حــال كونــه وكي ـ ً‬\n‫لشــركة مجموعــة ‪ ......‬الصناعيــة مبوجــب الوكالــة الصــادرة مــن‬\n‫كتابــة العــدل الثانيــة شــمال محافظــة جــدة برقــم ‪ 99351‬يف‬\n‫‪1431/12/3‬ه ـ املخــول لــه فيهــا حضــور اجللســات واملرافعــة واملدافعــة‬\n‫وتقــدمي املذكــرات واللوائــح االعتراضيــة وتقــدمي البينــات وســماع‬\n‫اخلصــوم والشــهود وردهــم ومناقشــتهم وتســميتهم ويف طلــب اليمــن‬\n\n\n                                                                                     ‫‪292‬‬\n\f      ‫وردهــا والقناعــة مــن عدمــه واإلقــرار واإلنــكار والصلــح ومتييــز‬\n      ‫األحــكام واســتئنافها وكالــة خاصــة وحضــر حلضــوره املدعــى عليــه ثــم‬\n      ‫جــرى عــرض الشــاهد وشــهادته املرصــودة يف اجللســة الســابقة علــى‬\n      ‫ا بــأن الشــاهد املذكــور قــد قــرر يف اجللســة‬   ‫املدعــى عليــه فأجــاب قائـ ً‬\n      ‫املاضيــة قبــل إدالئــه بشــهادته بأنــه قــد كتــب خطابـ ًا علــى لســان العامــل‬\n      ‫بالورشــة يديننــي فيــه ثــم حضــر العامــل للشــرطة وأنكــر ذلــك وهــذا‬\n      ‫قــادح يف قبــول شــهادته إذ كتــب عــن العامــل املذكــور مــا لــم يقلــه‬\n      ‫وبالنســبة لشــهادته فمــا ورد فيهــا غيــر صحيــح بــل إن الورشــة التــي‬\n      ‫تتعامل معها الشــركة املدعية أســمها مؤسســة ‪ ......‬للتبريد والتكييف‬\n      ‫والعامــل بهــذه الورشــة أقــر بــأن هــذه الفواتيــر صــادرة مــن ورشــتهم كما‬\n      ‫هــو موجــود يف أوراق املعاملــة هكــذا أجــاب ثــم جــرى ســؤال املدعــي‬\n      ‫ا اكتفــي مبــا يف أوراق‬       ‫وكالــة هــل لديــة مزيــد بينــه فأجــاب قائ ـ ً‬\n      ‫املعاملــة هكــذا أجــاب ثــم جــرى ســؤال املدعــى عليــه هــل لديــه مــا يريــد‬\n      ‫ا نعــم أوالً‪ :‬إن كفيلــي هــو شــركة مجموعــة ‪......‬‬     ‫إضافتــه فأجــاب قائـ ً‬\n      ‫للصناعــة كمــا هــو مبــن يف بطاقــة اإلقامــة اخلاصــة بــي وهــذا االســم‬\n      ‫للشــركة ذكــر كطــرف أول يف العقــد املبــرم بينــي وبــن هــذه‬\n      ‫الشــركة يف العقــد املبــرم يف عــام ‪2001‬م وهــذا يقــوى قولــي بــأن هــذا‬\n      ‫العقــد صحيــح بينمــا ذكــر يف العقــد املبــرم يف عــام ‪1996‬م بــأن الطــرف‬\n      ‫األول هــو مؤسســة ‪.....‬وذلــك قبــل حتويــل مســمى املؤسســة إلــى شــركة‬\n      ‫وبعــد التحويــل مت تغييــر كل شــيء حتــى االقامــات مت تغييرهــا وهــذا‬\n      ‫يؤكــد مــا ذكــرت بــأن هــذا العقــد األخيــر صحيــح إضافــة إلــى قــدم‬\n      ‫تاريــخ العقــد املبــرم يف عــام ‪1996‬م ثاني ـاً‪ :‬ورد يف تقريــر احملاســب‬\n      ‫القانونــي املرفــق عبــارة ( هــذه الديــون حتــت مســئولية املنــدوب ) ثالثــا‪:‬‬\n\n\n‫‪293‬‬\n\f‫يوجــد يف أورق املعاملــة العقــد املبــرم بــن الشــركة وبــن املنــدوب ‪......‬‬\n‫وقــد تضمــن البنــد (‪ )13‬بــأن املنــدوب مســئول عــن جميــع الديــون ويتعهــد‬\n‫بتســديدها‪ .‬رابعــا‪ :‬أن العقــد املبــرم بينــي وبــن الشــركة ال يوجــد فيــه‬\n‫مــا ينــص علــى أننــي مســئول عــن الثالجــات خامســا‪ :‬يوجــد يف أوراق‬\n‫املعاملــة قائمــة باســتالم املنــدوب الهــارب للثالجــات املذكــورة وعددهــا‬\n‫(‪ )172‬ثالجــة وقــد ذيــل عليهــا إقــرار املنــدوب مبســئوليته عنهــا مســئولية‬\n‫تامــة عــن هــذه الثالجــات وأنهــا يف عهدتــه ويتحمــل مســئولية أي ثالجــة‬\n‫مفقــودة سادســا‪ :‬بالنســبة لثالجــات (‪ )16‬التــي لــم تســتلمها الشــركة‬\n‫مــن عهــدة املنــدوب الهــارب هنــاك عقــود مرفقــة بــأوراق املعاملــة تثبــت‬\n‫بــأن املنــدوب الهــارب قــام بتســليم هــذه الثالجــات للعميــل ومت توقيــع‬\n‫العقــد بــن الطرفــن وســلم املنــدوب للشــركة العقــد مبينــا فيــه محــل‬\n‫وجــود الثالجــة وإذا قــام العميــل بنقــل احملــل أو بيعــه ونحــوه فــإن‬\n‫الشــركة تطالــب العميــل وال تعــود علــى املنــدوب أو املديــر إذ مهمــة‬\n‫املنــدوب واملديــر تنتهــي بتوقيــع العقــد وتســليمه للشــركة ســابعا‪ :‬إن‬\n‫العقــود تبــرم بــن الشــركة املدعيــة كطرف أول وبــن العميل كطرف‬\n‫ثانــي يقــوم املنــدوب بالتوقيــع عــن الشــركة وبــه تكــون الشــركة هــي‬\n‫املســئولة عــن هــذه الثالجــات فهــي التــي تتابعهــا ولهــا حــق التصــرف‬\n‫فيهــا ومطالبــة العميــل بهــا مبــا يترتــب علــى ذلــك مــن حقــوق ثامنــا‪:‬‬\n‫ثالجــات املنــدوب ‪ ......‬لــم تســتلم جديــد وإمنــا ‪ %90‬منهــا لهــا عــدت‬\n‫ســنوات تاســعا‪ :‬ثالجــات العصيــر الثمانيــة هــي ثالجــات اســكر مي‬\n‫مســتهلكه جــدا يتــم أعطاهــا لعميــل العصيــر بعــد إصالحهــا علــى‬\n‫حســابه اخلــاص ليســتخدمها يف تبريــد العصيــر يف املقاصــف ويوجــد يف‬\n‫املعاملــة عقــد مختــوم مبســؤولية العميــل عــن هــذه الثالجــات وعلــى‬\n\n\n                                                                                   ‫‪294‬‬\n\f      ‫الشــركة مطالبتــه بهــا‪ .‬عاشــرا‪ :‬الشــركة هــي كفيلــة للمندوبــن وهي‬\n      ‫التــي أرســلتهم للعمــل لــدي الفــرع وهــي املســؤولة عنهــم وصفتــي يف‬\n      ‫الفــرع اإلشــراف علــى أعمالهــم وتوزيــع املهــام بينهــم ومتابعــة ذلــك فقــط‬\n      ‫احلــادي عشــر‪ :‬أود اخــذ االعتبــار بتحقيــق الشــرطة مــع منســوبي الفــرع‬\n      ‫بخصــوص عــدد الثالجــات التــي كانــت ترســل إلــى الورشــة لإلصــاح‬\n      ‫هكــذا أجــاب وبعــرض ذلــك علــى املدعــي وكالــة أجــاب قائــا بــان مــا‬\n      ‫ذكــره املدعــى عليــه كالم مرســل وليــس يف صلــب القضيــة هكــذا‬\n      ‫أجــاب ويف جلســة أخــرى فيهــا حضــر الطرفــان فجــرى ســؤال املدعــى‬\n      ‫عليــه هــل أحضــر مــا يريــد إضافتــه كمــا قــرر يف اجللســة املاضيــة‬\n      ‫فأجــاب قائــا نعــم قــد أحضرتــه معــي ثــم أبــرز مذكــرة مكونــة مــن‬\n      ‫(‪ )26‬صفحــة مقيــدة يف هــذه احملكمــة برقــم ( ‪ ) 321284138‬يف‬\n      ‫‪1432/10/15‬ه ـ وأضــاف بــأن لــدي شــاهد يشــهد بــأن الشــركة تطلب‬\n      ‫مــن العاملــن توقيــع العقــود ثــم بعثهــا لهــم دون توقيــع مــن قبــل الشــركة‬\n      ‫وأن املنــدوب هــو املســئول عــن حتصيــل الديــون التــي لــدى اآلخريــن‬\n      ‫كمــا أن لــدي شــاهد آخــر وهــو ضابــط يف شــرطة خميــس مشــيط‬\n      ‫يشــهد بــأن املدعــو قــد أقــر لديــه بأنــي مظلــوم يف هــذه القضيــة وأنــه‬\n      ‫مضغــوط عليــه مــن قبــل الشــركة لــإدالء بالشــهادة هكــذا قــرر‪،‬‬\n      ‫كمــا جــرى ســؤال املدعــي وكالــة هــل لديــه مــا يرغــب يف إضافتــه‬\n      ‫فأجــاب قائــا أكتفــي مبــا قدمتــه ومت رصــده ســابقا وبالنســبة ملــا قدمه‬\n      ‫املدعــى عليــه فهــو شــيء مكــرر وأطلــب إنهــاء القضيــة واحلكــم فيهــا‬\n      ‫هكــذا أجــاب ويف جلســة أخــرى فيهــا حضــر املدعــي وكالــه واملدعــى‬\n      ‫عليــه وأحضــر املدعــى عليــه شــاهدين معــه وطلــب ســماع مــا لديهمــا مــن‬\n      ‫شــهادة وهــم كل مــن ‪ /‬حامــل بطاقــة الهويــة الوطنيــة رقــم ســجل أبهــا و‬\n\n\n‫‪295‬‬\n\f‫املدعــو ‪ /‬مصــري اجلنســية حامــل اإلقامــة رقــم وبســؤال كل واحــد‬\n‫منهمــا عــن عمــره وعملــه ومقــر إقامتــه وقرابتــه باملدعــى عليــه ومــا لديــه‬\n‫مــن شــهادة أجــاب األول عمــري ثالثــون عامــا وأعمــل مديــرا ملخفــر‬\n‫احلفائــر التابــع حملافظــة خميــس مشــيط وأســكن يف مدينــة أبهــا وليــس‬\n‫هنــاك بينــي وبــن املدعــى عليــه قرابــة ومــا لــدي مــن شــهادة فأشــهد أنــي‬\n‫كنــت محققــا يف هــذه القضيــة أثنــاء عملي يف مركز شــرطة الشــمالية‬\n‫وكان يحضــر لــدي يف املركــز ثالثــة أشــخاص مــن قبــل املدعــي أولهما‬\n‫اســمه وكان مديــرا لفــرع الشــركة املدعيــة يف اجلنــوب آنــذاك والثانــي‬\n‫الوكيــل الشــرعي للشــركة واســمه والثالــث شــخص أســمه وال أعــرف‬\n‫عالقتــه بالشــركة إال أن الوكيــل الشــرعي مــا كان يتكلــم يف هــذه‬\n‫القضيــة إال بعــد أن يتكلــم املدعــو‪ ...... /‬واملدعــو‪ ...... /‬ويف يــوم مــن‬\n‫األيــام تقــدم ‪ ......‬يف احلضــور وقــرر أمامــي بــأن دعــوى الشــركة املدعيــة‬\n‫ليســت صحيحــة وأن املدعــى عليــه ‪ ......‬مظلــوم وإمنــا يريــد صاحــب‬\n‫الشــركة املدعيــة أهانتــه وإذاللــه حتــى يقــدم اعتــذاره لديــه إال أن‬\n‫املدعــى عليــه رفــض ذلــك وأن هــذه ليســت املــرة األولــى التــي يفعــل‬\n‫صاحــب الشــركة مبوظفيــه هــذه الفعلــة هكــذا قــرر املدعــو ‪...... /‬‬\n‫أمامــي هــذا مــا لــدي مــن شــهادة كمــا أجــاب الشــاهد الثانــي قائــا‬\n‫عمــري ســتة وأربعــون عامــا تقريبــا وأعمــل حاليــا يف مؤسســة ‪......‬‬\n‫للتجــارة وأســكن يف ‪ ......‬وال يوجــد بينــي وبــن املدعــى عليــه قرابــة ومــا‬\n‫لــدي مــن شــهادة فأنــا أشــهد أنــي كنــت أعمــل لــدي الشــركة املدعيــة‬\n‫مــن عــام ‪1414‬ه ـ وحتــى عــام ‪1427‬ه ـ مبســمى منــدوب مبيعــات وكان‬\n‫طريقــة الشــركة يف إبــرام العقــود مــع موظفيهــا أنهــا جتعــل املوظــف‬\n‫يوقــع علــى عقــد العمــل قبــل توقيــع صاحــب الشــركة ومــن ثــم يرســل‬\n\n\n                                                                                      ‫‪296‬‬\n\f      ‫العقــد للشــركة يف جــدة وال يعــود لنــا بعــد ذلــك هــذه النقطــة األولــى‬\n      ‫والنقطــة الثانيــة أن منــدوب املبيعــات للشــركة هــو املســئول عن املبيعات‬\n      ‫وعــن حتصيــل الديــون التــي للشــركة علــى اآلخريــن والنقطــة الثالثــة أن‬\n      ‫املنــدوب يقــوم بعــد حتصيــل الديــون بتســليم مــا لديــة من نقود للمحاســب‬\n      ‫ومــن ثــم يأخــذ املنــدوب ســندا بذلــك مــن احملاســب ويخصــم ذلــك مــن‬\n      ‫العهــد التــي علــى املنــدوب للشــركة وليــس ملديــر الفــرع أي عالقــة بذلــك‬\n      ‫وإمنــا دورة تنظيــم العمــل وإدارتــه بــن منســوبي الفــرع وليــس مســئوال عــن‬\n      ‫الديــون التــي للشــركة علــى اآلخريــن وإمنــا املســئول عنهــا منــدوب‬\n      ‫املبيعــات هــذا مــا لــدي مــن شــهادة وبعــرض الشــاهدين وشــهادتهم علــى‬\n      ‫املدعــي وكالــة أجــاب قائــا بالنســبة للشــاهدين فــا أعلــم عنهمــا شــيئا‬\n      ‫وبالنســبة للشــهادة فأطلــب مهلــة للــرد عليــه ويف جلســة أخــرى لــدي أنــا‬\n      ‫‪ ......‬القاضــي املنتــدب باحملكمــة العامــة بخميــس مشــيط مبوجــب‬\n      ‫قــرار رئيــس مجلــس القضــاء األعلــى رقــم ( ‪ )22536‬يف ‪1433/12/29‬‬\n      ‫ه ـ واملكلــف بعمــل املكتــب القضائــي الرابــع مبوجــب خطــاب رئيــس‬\n      ‫هــذه احملكمــة رقــم (‪ ) 3433830‬يف ‪1434/1/5‬ه ـ حضــر الطرفــان ثم‬\n      ‫جــرى عــرض مــا جــاء يف شــهادة الشــاهد األول ‪ /‬علــى املدعــي وكالــة‬\n      ‫أجــاب مــا جــاء يف شــهادته ال أعلــم صحتــه وال أعــرف حــال الشــاهد‪ ،‬ثــم‬\n      ‫جــرى عــرض شــهادة الشــاهد الثانــي علــى املدعي وكالة أجاب شــهادته‬\n      ‫غيــر صحيحــة وأطلــب مواجهــة الشــاهد مــرة ثانيــة لســؤاله أمــا الشــاهد‬\n      ‫فــا أعرفــه‪ ،‬ومبــا أنــه كان موظــف يف الشــركة فرمبــا كان بينــه‬\n      ‫وبــن الشــركة مشــاكل ولذلــك شــهد ضدهــا‪ ،‬هــذه إجابتــي ويف‬\n      ‫جلســة أخــرى لــدي أنــا القاضــي باحملكمــة العامــة بخميــس مشــيط‬\n      ‫القائــم بعمــل املكتــب القضائــي الرابــع فيهــا حضــر ســعودي اجلنســية‬\n\n\n‫‪297‬‬\n\f‫ا عــن املدعــي‬ ‫مبوجــب بطاقــة الهويــة الوطنيــة رقــم ( ‪ ) ...‬بصفتــه وكيـ ً‬\n‫أصالــة عــن نفســه وبصفتــه شــريك يف شــركة مجموعــة ‪ ......‬الصناعيــة‬\n‫مبوجــب الوكالــة الصــادرة مــن كاتــب العــدل املكلــف يف الغرفــة‬\n‫التجاريــة الصناعيــة بجــدة رقــم ( ‪ ) ...‬وتاريــخ ‪1434/6/24‬ه ـ والــذي لــه‬\n‫فيهــا حــق املطالبــة وإقامــة الدعــاوي واملرافعــة واملدافعــة وســماع‬\n‫الدعــاوي والــرد عليهــا طلــب اليمــن ورده واالمتنــاع عنــه وحضــر حلضوره‬\n‫املدعــى عليــه ثــم مت تــاوة مــا مت رصــده فصادقــا عليــه واحضــر املدعــى‬\n‫عليــه الشــاهد مصــر اجلنســية باإلقامــة رقــم(‪ )...‬كمــا أحضــر الشــاهد‬\n‫الثانــي مصــري اجلنســية باإلقامــة رقــم (‪ )...‬وبســؤالهما عمــا لديهمــا مــن‬\n‫شــهادة شــهد األول قــال أشــهد بــاهلل العظيــم قــال كنــت أعمــل مندوبـ ًا‬\n‫يف الشــركة املدعيــة مــن عــام ‪1994‬م إلــى عــام ‪2004‬م وكان أخــر‬\n‫عقــد وقعنــا عليــه باســم شــركة مجموعــة ‪ ......‬الصناعيــة وكنــت‬\n‫مســئو ًال عــن جميــع العهــد التــي كانــت أســلمها واســتلمها ومســئوال عــن‬\n‫حتصيــل الديــون وليــس ملديــر الفــرع يف ذلــك إي مســؤولية يف حتصيــل‬\n‫الديــون يف جلســة أخــرى وفيهــا حضــر ســعودي اجلنســية مبوجــب الســجل‬\n‫ا عــن أصالــة عــن نفســه وبصفتــه مديــر‬  ‫املدنــي رقــم (‪ )...‬بصفتــه وكيـ ً‬\n‫الشــركة يف شــركة مجموعــة ‪ ......‬الصناعيــة وذلــك بصفتــه شــريكا‬\n‫يف الشــركة مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل املكلــف‬\n‫يف الغرفــة التجاريــة الصناعيــة بجــدة برقــم() وتاريــخ ‪1434/7/3‬ه ـ‬\n‫كمــا حضــر املدعــى عليــه وبســؤال املدعــي وكالــة عــن الشــهود ومــا‬\n‫جــاء يف شــاهدتهم قــال أمــا الشــهود فــا اعرفهــم وبعــد مراجعــة شــؤون‬\n‫املوظفــن تبــن أنهــم يعملــون يف مســتحضرات التجميــل وليــس يف مصنع‬\n‫اآليــس كــرمي والعصيــر ‪ ....‬وهــو مختلــف متامــا هــذه إجابتــي عــن الشــهود‬\n\n\n                                                                                   ‫‪298‬‬\n\f      ‫وبســؤاله عــن البينــة عــن أن الثالجــات ال حتتــاج إلــى صيانــة يف الفواتيــر‬\n      ‫التــي ذكــرت يف اجللســات الســابقة قــال أمــا الثالجــات فيــه حتتــاج إلــى‬\n      ‫صيانــة دوريــة ثــم جــرى ســؤال املدعــى عليــه هــل احضر مزكني للشــهود‬\n      ‫قــال نعــم فاحضــر ســوري اجلنســية مبوجــب اإلقامــة رقــم (‪ )......‬و‪......‬‬\n      ‫فلســطيني اجلنســية مبوجــب اإلقامــة رقــم (‪ )......‬وبســؤالهما عــن الشــهود‬\n      ‫قــاال نزكيهــم وهــم عــدول ثــم جــرى ســؤال املدعــي وكالــة هــل مزيــد‬\n      ‫بينــات قــال ليــس لــدي إال مــا جــاء يف أوراق املعاملــة وبســؤال املدعــى‬\n      ‫عليــه هــل لديــة مــا يريــد إضافتــه قــال اكتفــي مبــا جــاء يف الــوراق‬\n      ‫املعاملــة ‪.‬أ‪.‬ه ـ فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وملصادقــة‬\n      ‫الوكيــل الشــرعي علــى أن املدعــى عليــه هــو مديــر الفــرع وقــد عمــل مــا‬\n      ‫يقــارب عشــرين ســنة فيــده يــد أمــن ألنــه يتصــرف بــإذن مــن املالــك فــا‬\n      ‫يضمــن إال إذا تعــدى أو فــرط واألصــل بــراءة الذمــة حتــى يأتــي مــا ينقــل‬\n      ‫هــذا األصــل ولكــون جهــة التحقيــق قــد انتهــت مــن هــذه القضيــة‬\n      ‫وبنتيجــة ونــص احلاجــة منهــا كمــا جــاء علــى لفــه رقــم(‪ )95‬أو ًال ‪ /‬وجــود‬\n      ‫تناقــض يف تقريــر احملاســب القانونــي والــذي مت إرفاقــه مــن قبــل مصنــع‬\n      ‫‪ ......‬وذلــك ملــا جــاء يف أقــوال الوكيــل الشــرعي أن املنــدوب الهــارب هــو‬\n      ‫املســئول عــن تلــك املبالــغ بدايــة لكــن أهمــل يف حتصيلهــا بصفتــه مديــر‬\n      ‫للفــرع وبالتالــي هــو املســئول عنهــا كمــا تضمنــه التقريــر وكذلــك مــا‬\n      ‫جــاء يف أقــوال املدعــى عليــه أنــه مت حتصيــل أكثــر املبلــغ املوجــود‬\n      ‫بالتقريــر ويقــدر بحوالــي مائــة وســتة عشــر ألــف (‪ )116000‬ريــال مــن‬\n      ‫أصــل مائــة وواحــد وســبعون ألــف (‪ )171000‬ريــال وكذلــك العثــور‬\n      ‫علــى معظــم الثالجــات يف الســوق مــن عهــده املتهــم الهــارب ‪ ......‬وعددها‬\n      ‫(‪ )154‬ثالجــة مــن أصــل (‪ )170‬ثالجــة وهــذا مــا قــرره مديــر الفــرع‬\n\n\n‫‪299‬‬\n\f‫احلالــي ومحاســب الشــركة ومندوبهــا وجيــه وكذلــك وجــود الورقــة‬\n‫مكتوبــة بخــط املديــر احلالــي للفــرع علــى الورقــة اخلاصــة بــورش ‪......‬‬\n‫وهــي بتاريــخ متأخــر عــن تاريــخ إعــداد احملاســب القانونــي وكذلــك‬\n‫العقــد املرفــق واملســتند عليــه يف املــادة (‪ )13‬يخــص املنــدوب وليــس مدير‬\n‫الفــرع كمــا أن األوراق التــي مت إرفاقهــا بالتقريــر القانونــي بخصــوص‬\n‫هــذه الدعــوى هــي نفــس األوراق املوجــودة لدينــا مــن قبــل بخصــوص‬\n‫الدعــوى ضــد هــروب املنــدوب هنــدي اجلنســية‪ .‬ثاني ـاً‪ /‬عــدم توجيــه‬\n‫االتهــام للمدعــو ‪ ....../‬مبــا ينســب إليــه ســواء يف املبالــغ املاليــة أو‬\n‫الثالجــات أو التزويــر يف الفواتيــر رغــم إصــرار املدعــي بــأن هــو املســئول‬\n‫كونــه كان املديــر للفــرع وذلــك ملــا جــاء يف أقــوال الوكيــل الشــرعي‬\n‫أن هــذه الدعــوى تخــص املنــدوب الهــارب ‪ ......‬وأن تلــك الديــون يف ذمتــه‬\n‫وإلنــكار املدعــى عليــه ‪ ......‬أن كل مــا ورد غيــر صحيــح كمــا أنــه‬\n‫ليــس املســئول عمــا ورد جتــاه ذلــك املنــدوب الهــارب والــذي ســبق وأن مت‬\n‫اإلبــاغ عنــه رســمي ًا ولعــدم صحــة مــا اســتند عليــه املصنــع يف التقريــر‬\n‫بخصــوص املــادة (‪ )13‬ألنهــا تخــص املنــدوب الهــارب وكان مديــر للفــرع‬\n‫وكذلــك مــا ذكــره املدعــو للمحقــق داخــل مكتبــه بــأن الدعــوى ضــده‬\n‫غيــر صحيحــة وان الشــركة فقــط تريــد إذاللــه وإهانتــه ‪.‬أ‪.‬ه ـ ولكــون‬\n‫العقــد الــذي اســتدلوا بــه يف تقريــر احملاســب القانونــي الــذي قدمتــه‬\n‫الشــركة املدعيــة علــى لفــة رقــم (‪ )13‬هــو عقــد متأخــر عــن العقــود‬\n‫الــذي تســتدل بــه الشــركة علــى أن مديــر الفــرع متضامــن مــع املناديــب‬\n‫وجــاء يف هــذا العقــد املتأخــر باســم شــركة مجموعــة ‪ ......‬الفقــرة (‪)13‬‬\n‫ونصهــا يف العقــد‪ ( :‬منــه الطــرف الثانــي املنــدوب مســئول عــن جميــع‬\n‫املبيعــات اآلجلــة التــي تتــم عــن طريقــه ويتعهــد بتحصيلهــا وتســديدها‬\n\n\n                                                                                    ‫‪300‬‬\n\f      ‫ويف حالــة عــدم حتصيلهــا ألي ســبب كان يحــق للطــرف األول خصمهــا‬\n      ‫مــن راتبــه وحقوقــه وال يتــم إخــاء طرفــه إال بعــد ســداده)‪.‬أ‪.‬هـ ال حجــة‬\n      ‫للشــركة بعــدم توقيعهــا حيــث أنهــا قدمتــه حجــة لهــا يف الدعــوى‪.‬‬\n      ‫فيكــون ال حجــة لهــا علــى تضمــن مديــر الفــرع يف الديــون غير احملصلة‬\n      ‫وكــذا يف الثالجــات وأمــا الفواتيــر فــا بينــة لهــم علــى أنهــا غيــر‬\n      ‫صحيحــة بــل مــا جــاء يف تقريــر التحقيــق علــى لفــه (‪ )99‬أن قيمتهــا‬\n      ‫صحيحــة وجــاء فيهــا أنهــا مــن نفــس املؤسســة التــي تتعامــل املدعيــة معهــا‬\n      ‫كمــا يف الفواتيــر ولكــون املدعــى عليــه قــد أقــر بتســليم ثمــان ثالجــات‬\n      ‫وهــي لــدى التاجــر وهــي مســلمة لــه بعهــد وتواقيــع واملهمــة يف ذلــك عنــد‬\n      ‫الشــركة تنتهــي بتوقيــع العهــد وبتســليمه للشــركة وهــي مســؤولة بعــد‬\n      ‫ذلــك عــن املطالبــة بهــا ولكــون املدعــى عليــه قــد أحضــر البينــة املعدلــة‬\n      ‫شــرع ًا علــى أن املناديــب هــم املســئولون يف الشــركة عــن حتصيــل‬\n      ‫الديــون وعهدهــم وهــم مســئولون عنهــا وال مســؤولية ملديــر الفــرع وإمنــا‬\n      ‫مهمتــه اإلشــراف وتوزيــع املهــام لهــذا كلــه فقــد صرفــت النظــر عــن‬\n      ‫دعــوى املدعيــة وأفهمــت املدعــي وكالــة بــأن ليــس لــه إال ميــن املدعــى‬\n      ‫عليــه لنفــي مــا أدعــى بــه متــى طلبهــا وبــه حكمــت وبعرضــه علــى‬\n      ‫الطرفــن واملدعــى عليــه قــرر القناعــة وقــرر املدعــي وكالــة عــدم‬\n      ‫القناعــة وســيتقدم بالئحــة اعتراضيــة وأفهمتــه مبراجعــة احملكمــة يــوم‬\n      ‫الســبت ‪1434/7/8‬ه ـ الســتالم نســخة مــن احلكــم لتقــدمي الئحتــه‬\n      ‫االعتراضيــة خــال ثالثــن يــوم مــن تاريــخ صــدور الصــك يف حــال انتهــاء‬\n      ‫املــدة ولــم يتقــدم يكتســب القطعيــة‪ .‬وبــاهلل التوفيــق وصلــى اهلل وســلم‬\n                                            ‫على نبينا محمد حرر يف ‪1434/7/8‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق ‪1434/10/18‬ه ـ‬\n\n\n‫‪301‬‬\n\f‫افتتحــت اجللســة وقــد وردتنــا املعاملــة مــن محكمــة االســتئناف مبنطقــة‬\n‫عســير برقــم ‪ 342052378‬وتاريــخ ‪1434/9/21‬ه ـ وبرفقهــا القــرار‬\n‫ذي الرقــم ‪ 34313612‬وتاريــخ ‪1434/9/7‬ه واملتضمــن‪ :‬احلمــد هلل‬\n‫وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة لتدقيــق القضايــا‬\n‫واجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة الــواردة‬\n‫مــن فضيلــة مســاعد رئيــس احملكمــة العامــة بخميــس مشــيط برقــم‬\n‫‪ 3213003‬وتاريــخ ‪1434/8/9‬ه ـ املرفــق بهــا الصــك الصــادر من فضيلة‬\n‫القاضــي باحملكمــة الشــيخ ‪ /‬برقــم ‪ 34261913‬وتاريــخ ‪1434/7/8‬ه‬\n‫اخلــاص بدعــوى ‪ /‬شــركة مجموعــة ‪ ......‬الصناعيــة ضــد ‪ /‬يف قضيــة (‬\n‫اختــاس) علــى الصفــة املوضحــة يف الصــك املتضمــن حكــم فضيلتــه‬\n‫مبــا هــو مــدون ومفصــل فيــه وبدراســة الصــك وصــورة ضبطــه والالئحــة‬\n‫االعتراضيــة وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم واهلل املوفــق‬\n‫صلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬قاضــي اســتئناف‬\n‫توقيعــه وختمــه وقاضــي اســتئناف توقيعــه وختمــه ورئيــس الدائــرة‬\n‫توقيعــه وختمــه‪ .‬وللبيــان جــرى إحلاقــه وبــاهلل التوفيــق وصلــى اهلل علــى‬\n                                         ‫نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                   ‫‪302‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a1c7c722-328b-51d4-86f7-30f50f66d580","source_page_start":281,"source_page_end":302,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c45bd263d42ce0e42d1c11161cc261aad68983580639ef6f4f9b95cb6fac9f1d","normalized_text_hash":"20faf028cc3722f75a6d967a25f710fb789e4ccfa9216747075356ff488efc7c","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v3-p281-34261913"}]$archive_payload$::jsonb) AS x LIMIT 25
